-- ── (0) أعمدة إضافية على جدول السلم القائم (لا تمسّ الإصدارات السابقة) ──
ALTER TABLE framework_rubric ADD COLUMN IF NOT EXISTS group_ar     text;
ALTER TABLE framework_rubric ADD COLUMN IF NOT EXISTS source_pages int[];

COMMENT ON COLUMN framework_rubric.group_ar IS
  'مجموعة الوصف داخل المعيار الفرعي حين تقسّمها الوثيقة (مثل اختبار TIMSS)';

-- ── (1) الأوصاف ────────────────────────────────────────────────
CREATE TEMP TABLE _q26_rubric (
  sub text, row_index int, level int, descriptor text, group_ar text, pages int[]
) ON COMMIT DROP;

INSERT INTO _q26_rubric (sub, row_index, level, descriptor, group_ar, pages) VALUES
  ('1.1.1', 1, 5, 'رؤية ورسالة وقيم المدرسة واضحة ومعلنة، وتتوافق مع توجهات الدولة وسياساتها التعليمية، ويتم نشرها بطرقٍ متنوعة ومستمرة وفعالة جداً، مما أسهم في تعزيز معرفة ووعي جميع الأطراف المعنية بها وبأدوارهم في تحقيقها.', NULL, ARRAY[56]),
  ('1.1.1', 1, 4, 'رؤية ورسالة وقيم المدرسة واضحة ومعلنة، وتتوافق مع توجهات الدولة وسياساتها التعليمية، ويتم نشرها بطرقٍ متنوعة وفعالة، مما أسهم في تعزيز معرفة ووعي الغالبية العظمى من الأطراف المعنية بها وبأدوارهم في تحقيقها.', NULL, ARRAY[56]),
  ('1.1.1', 1, 3, 'رؤية ورسالة وقيم المدرسة واضحة ومعلنة، وتتوافق مع توجهات الدولة وسياساتها التعليمية، ويتم نشرها بطرقٍ مناسبة، مما أسهم في معرفة ووعي معظم الأطراف المعنية بها وبأدوارهم في تحقيقها.', NULL, ARRAY[56]),
  ('1.1.1', 1, 2, 'تتوافق رؤية ورسالة وقيم المدرسة مع توجهات الدولة وسياساتها التعليمية، إلا أنه يتم نشرها بطرقٍ محدودة، مما أدى إلى معرفة ووعي بعض الأطراف المعنية بها وبأدوارهم في تحقيقها.
أو
رؤية ورسالة وقيم المدرسة تتوافق مع توجهات الدولة وسياساتها التعليمية، ويتم نشرها، إلا أن صياغة أحد هذه المكونات (الرؤية أو الرسالة) غير واضحة وتحتاج إلى تطوير لتعزيز وضوحها وقابليتها للقياس.', NULL, ARRAY[56]),
  ('1.1.1', 1, 1, 'تتوافق رؤية ورسالة وقيم المدرسة مع توجهات الدولة وسياساتها التعليمية، إلا أنه يتم نشرها بطرقٍ محدودة جداً، مما أدى إلى معرفة ووعي قلة من الأطراف المعنية بها وبأدوارهم في تحقيقها.
أو
رؤية ورسالة وقيم المدرسة تتوافق مع توجهات الدولة وسياساتها التعليمية، ويتم نشرها، إلا أن صياغة كلٍ من الرؤية والرسالة غير واضحة وتحتاج إلى تطوير لتعزيز وضوحهما واتساقهما.
أو
لا تتوافق الرؤية والرسالة والقيم مع توجهات الدولة وسياساتها التعليمية.', NULL, ARRAY[56]),
  ('1.1.1', 2, 5, 'جميع أهداف المدرسة واضحة ومحددة، وقابلة للقياس، وتتوافق مع رؤية ورسالة المدرسة وقيمها وتسهم في تحقيقها، وتحقيق توجهات الدولة، وتدعم قيم المجتمع وثقافته.', NULL, ARRAY[57]),
  ('1.1.1', 2, 4, 'الغالبية العظمى من أهداف المدرسة واضحة ومحددة، وقابلة للقياس، وتتوافق مع رؤية ورسالة المدرسة وقيمها وتسهم في تحقيقها، وتحقيق توجهات الدولة، وتدعم قيم المجتمع وثقافته.', NULL, ARRAY[57]),
  ('1.1.1', 2, 3, 'معظم أهداف المدرسة واضحة وقابلة للقياس، وتتوافق مع رؤية ورسالة المدرسة وقيمها، وتسهم في تحقيقها.', NULL, ARRAY[57]),
  ('1.1.1', 2, 2, 'بعض أهداف المدرسة واضحة وتتوافق مع رؤية ورسالة المدرسة وقيمها، مما يؤثر على تحقيق الرؤية والرسالة.', NULL, ARRAY[57]),
  ('1.1.1', 2, 1, 'قلة من أهداف المدرسة واضحة وتتوافق مع رؤية ورسالة المدرسة وقيمها، مما يؤثر سلباً على تحقيق الرؤية والرسالة.
أو
أهداف المدرسة غير واضحة ولا تتوافق مع رؤية ورسالة المدرسة وقيمها.', NULL, ARRAY[57]),
  ('1.1.1', 3, 5, 'يتم دمج الرؤية والرسالة والقيم والأهداف في جميع جوانب العمل المدرسي، مع تحقيق انسجام تام بين التوجهات النظرية والممارسات العملية، مما يعزز من تحقيقها. بشكلٍ فعال جداً.', NULL, ARRAY[57]),
  ('1.1.1', 3, 4, 'يتم دمج الرؤية والرسالة والقيم والأهداف في الغالبية العظمى من جوانب العمل المدرسي، مع تحقيق انسجام بين التوجهات النظرية والممارسات العملية، مما يعزز من تحقيقها بشكلٍ فعال.', NULL, ARRAY[57]),
  ('1.1.1', 3, 3, 'يتم دمج الرؤية والرسالة والقيم والأهداف في معظم جوانب العمل المدرسي، مما يعزز من تحقيقها بشكلٍ مناسب.', NULL, ARRAY[57]),
  ('1.1.1', 3, 2, 'يتم دمج الرؤية والرسالة والقيم والأهداف في بعض جوانب العمل المدرسي، مما أدى إلى تحقيقها بشكلٍ محدود.', NULL, ARRAY[57]),
  ('1.1.1', 3, 1, 'يتم دمج الرؤية والرسالة والقيم والأهداف في قلة جوانب العمل المدرسي، مما أدى إلى تحقيقها بشكلٍ محدود جداً.
أو
لا يتم دمج الرؤية والرسالة والأهداف في جوانب العمل المدرسي.', NULL, ARRAY[57]),
  ('1.1.2', 1, 5, 'تتوافق الموارد المادية في المدرسة بشكلٍ كامل مع رؤيتها ورسالتها، حيث تتوفر جميع المباني والمرافق والتجهيزات اللازمة التي تدعم تحقيق الرؤية والرسالة.', NULL, ARRAY[57,58]),
  ('1.1.2', 1, 4, 'تتوافق الموارد المادية في المدرسة بشكلٍ كبير مع رؤيتها ورسالتها، حيث تتوفر الغالبية العظمى من المباني والمرافق والتجهيزات اللازمة التي تدعم تحقيق الرؤية والرسالة.', NULL, ARRAY[57,58]),
  ('1.1.2', 1, 3, 'تتوافق الموارد المادية في المدرسة بشكلٍ مناسب مع رؤيتها ورسالتها، حيث تتوفر معظم المباني والمرافق والتجهيزات اللازمة التي تدعم تحقيق الرؤية والرسالة.', NULL, ARRAY[57,58]),
  ('1.1.2', 1, 2, 'تتوافق الموارد المادية في المدرسة بشكلٍ محدود مع رؤيتها ورسالتها، حيث تتوفر بعض المباني والمرافق والتجهيزات التي تدعم تحقيق الرؤية والرسالة.
أو
تتوافق الموارد المادية في المدرسة مع رؤيتها ورسالتها، إلا أن توظيفها في الممارسات العملية ما يزال بحاجة إلى تطوير، بما يعزز دعم تحقيق الرؤية والرسالة بصورة أكثر فاعلية.', NULL, ARRAY[57,58]),
  ('1.1.2', 1, 1, 'تتوافق الموارد المادية في المدرسة بشكلٍ محدود جداً مع رؤيتها ورسالتها، حيث تتوفر قلة من المباني والمرافق والتجهيزات التي تدعم تحقيق الرؤية والرسالة.', NULL, ARRAY[57,58]),
  ('1.1.2', 2, 5, 'تتوافق الموارد البشرية في المدرسة بشكلٍ كامل مع رؤيتها ورسالتها، حيث أن جميع الموظفين مؤهلون وذو كفاءة عالية ويدعمون بشكلٍ فعال جداً تحقيق الرؤية والرسالة.', NULL, ARRAY[58]),
  ('1.1.2', 2, 4, 'تتوافق الموارد البشرية في المدرسة بشكلٍ كبير مع رؤيتها ورسالتها، حيث أن الغالبية العظمى من الموظفين مؤهلون ويدعمون بشكلٍ فعال تحقيق الرؤية والرسالة.', NULL, ARRAY[58]),
  ('1.1.2', 2, 3, 'تتوافق الموارد البشرية في المدرسة بشكلٍ مناسب مع رؤيتها ورسالتها، حيث أن معظم الموظفين مؤهلون ويدعمون تحقيق الرؤية والرسالة.', NULL, ARRAY[58]),
  ('1.1.2', 2, 2, 'تتوافق الموارد البشرية في المدرسة بشكلٍ محدود مع رؤيتها ورسالتها، حيث يمتلك بعض الموظفين المؤهلات والكفاءات التي تدعم تحقيق الرؤية والرسالة.
أو
تتوافق الموارد البشرية في المدرسة مع رؤيتها ورسالتها من حيث المؤهلات والكفاءات، إلا أن توظيف هذه الكفاءات في الممارسات العملية ما يزال بحاجة إلى تطوير، بما يعزز دعم تحقيق الرؤية والرسالة بصورة أكثر فاعلية.', NULL, ARRAY[58]),
  ('1.1.2', 2, 1, 'تتوافق الموارد البشرية في المدرسة بشكلٍ محدود جداً مع رؤيتها ورسالتها، حيث يمتلك قلة من الموظفين المؤهلات والكفاءات التي تدعم تحقيق الرؤية والرسالة.', NULL, ARRAY[58]),
  ('1.1.2', 3, 5, 'الوضع المالي للمدرسة مستقر، والموارد المالية كافية لتغطية جميع احتياجات المدرسة بشكلٍ فعال جداً ومستمر، ويتم وضع تقديرات مستقبلية للموارد المالية وتطوير استراتيجيات لضمان استدامة الميزانية، مما يسهم في تحقيق الرؤية والرسالة والأهداف.', NULL, ARRAY[59]),
  ('1.1.2', 3, 4, 'الوضع المالي للمدرسة مستقر، والموارد المالية تغطي الغالبية العظمى من احتياجات المدرسة بشكلٍ فعال ومستمر، ويتم وضع تقديرات مستقبلية للموارد المالية، مما يسهم في تحقيق الرؤية والرسالة والأهداف.', NULL, ARRAY[59]),
  ('1.1.2', 3, 3, 'الموارد المالية تغطي معظم احتياجات المدرسة بشكلٍ مناسب، مما يسهم في تحقيق الرؤية والرسالة والأهداف.', NULL, ARRAY[59]),
  ('1.1.2', 3, 2, 'الموارد المالية تغطي بعض احتياجات المدرسة، مما أثر على تحقيق الرؤية والرسالة والأهداف.', NULL, ARRAY[59]),
  ('1.1.2', 3, 1, 'لا تغطي الموارد المالية احتياجات المدرسة أو تغطيها بشكلٍ محدود جداً، مما أثر سلباً على تحقيق الرؤية والرسالة والأهداف.', NULL, ARRAY[59]),
  ('1.1.3', 1, 5, 'تُطبق المدرسة آلية وإجراءات واضحة ومستمرة وشاملة لمراجعة ومتابعة مدى تحقيق عناصر الرؤية والرسالة والأهداف، وتستفيد من نتائج المراجعة بشكلٍ فعال جداً في اتخاذ القرارات، وتحديث الرسالة والأهداف (عند الحاجة)، بما يضمن توافق جميع عناصر الرؤية والرسالة والأهداف مع احتياجات المدرسة، وتوجهات الدولة، والمتغيرات المحلية والعالمية.', NULL, ARRAY[59,60]),
  ('1.1.3', 1, 4, 'تُطبق المدرسة آلية وإجراءات واضحة ومستمرة لمراجعة ومتابعة مدى تحقيق عناصر الرؤية والرسالة والأهداف، وتستفيد من نتائج المراجعة بشكلٍ فعال في اتخاذ القرارات، وتحديث الرسالة والأهداف (عند الحاجة)، بما يضمن توافق الغالبية العظمى من عناصر الرؤية والرسالة والأهداف مع احتياجات المدرسة وتوجهات الدولة.', NULL, ARRAY[59,60]),
  ('1.1.3', 1, 3, 'تُطبق المدرسة آلية وإجراءات لمراجعة ومتابعة مدى تحقيق عناصر الرؤية والرسالة والأهداف، وتستفيد من نتائج المراجعة بشكلٍ مناسب في اتخاذ القرارات، وتحديث الرسالة والأهداف (عند الحاجة)، بما يضمن توافق معظم عناصر الرؤية والرسالة والأهداف مع احتياجات المدرسة وتوجهات الدولة.', NULL, ARRAY[59,60]),
  ('1.1.3', 1, 2, 'تُطبق المدرسة إجراءات محدودة لمراجعة ومتابعة مدى تحقيق عناصر الرؤية والرسالة والأهداف، مما أدى إلى توافق بعض عناصرها مع احتياجات المدرسة وتوجهات الدولة.
أو
تُطبق المدرسة آلية وإجراءات لمراجعة مدى تحقيق الرؤية والرسالة والأهداف، إلا أنها تستفيد من نتائج هذه المراجعة بشكلٍ محدود، مما أثر على مستوى تحقيق الرؤية والرسالة.', NULL, ARRAY[59,60]),
  ('1.1.3', 1, 1, 'لا يتم مراجعة ومتابعة مدى تحقيق عناصر الرؤية والرسالة والأهداف.
أو
تطبق المدرسة إجراءات لمراجعة الرؤية والرسالة والأهداف بدون إجراء التعديل أو التحديث، حتى عند الحاجة.', NULL, ARRAY[59,60]),
  ('1.1.3', 2, 5, 'مشاركة جميع الأطراف المعنية بطرق متنوعة ومنتظمة ومستمرة في عمليات مراجعة الرؤية والرسالة والأهداف، مع توظيف مشاركاتهم وملاحظاتهم ومقترحاتهم بشكلٍ فعال جداً في عمليات المراجعة والتحديث.', NULL, ARRAY[60]),
  ('1.1.3', 2, 4, 'مشاركة الغالبية العظمى من الأطراف المعنية بطرق متنوعة ومنتظمة في عمليات مراجعة الرؤية والرسالة والأهداف، مع توظيف مشاركاتهم وملاحظاتهم ومقترحاتهم بشكلٍ فعال في عمليات المراجعة والتحديث.', NULL, ARRAY[60]),
  ('1.1.3', 2, 3, 'مشاركة معظم الأطراف المعنية بطرق متنوعة في عمليات مراجعة الرؤية والرسالة والأهداف، مع توظيف مشاركاتهم وملاحظاتهم ومقترحاتهم بشكلٍ مناسب في عمليات المراجعة والتحديث.', NULL, ARRAY[60]),
  ('1.1.3', 2, 2, 'مشاركة بعض الأطراف المعنية في عمليات مراجعة الرؤية والرسالة والأهداف، مع الاستفادة من مشاركاتهم ومقترحاتهم في عمليات المراجعة والتحديث.
أو
مشاركة الأطراف المعنية في عمليات مراجعة الرؤية والرسالة والأهداف، إلا أن توظيف مشاركاتهم وملاحظاتهم ومقترحاتهم في عمليات المراجعة والتحديث يتم بشكلٍ محدود.', NULL, ARRAY[60]),
  ('1.1.3', 2, 1, 'مشاركة قلة من الأطراف المعنية في عمليات مراجعة الرؤية والرسالة والأهداف، مع الاستفادة من مشاركاتهم ومقترحاتهم في عمليات المراجعة والتحديث.
أو
لا يتم مشاركة الأطراف المعنية في عمليات مراجعة الرؤية والرسالة والأهداف.', NULL, ARRAY[60]),
  ('1.2.1', 1, 5, 'تلتزم المدرسة بتطبيق جميع لوائح وأنظمة وزارة التربية والتعليم والتعليم العالي والجهات الحكومية ذات العلاقة.', NULL, ARRAY[60,61]),
  ('1.2.1', 1, 4, 'تلتزم المدرسة بتطبيق الغالبية العظمى من لوائح وأنظمة وزارة التربية والتعليم والتعليم العالي والجهات الحكومية ذات العلاقة.', NULL, ARRAY[60,61]),
  ('1.2.1', 1, 3, 'تلتزم المدرسة بتطبيق معظم لوائح وأنظمة وزارة التربية والتعليم والتعليم العالي والجهات الحكومية ذات العلاقة.', NULL, ARRAY[60,61]),
  ('1.2.1', 1, 2, 'تلتزم المدرسة بتطبيق بعض لوائح وأنظمة وزارة التربية والتعليم والتعليم العالي والجهات الحكومية ذات العلاقة.', NULL, ARRAY[60,61]),
  ('1.2.1', 1, 1, 'تلتزم المدرسة بتطبيق قلة من لوائح وأنظمة وسياسات وزارة التربية والتعليم والتعليم العالي والجهات الحكومية ذات العلاقة.', NULL, ARRAY[60,61]),
  ('1.2.2', 1, 5, 'تعد المدرسة خططاً استراتيجية وسنوية متكاملة، تتسم بالشمولية والجودة العالية، وتغطي جميع أهداف المدرسة واحتياجاتها وأولوياتها.', NULL, ARRAY[61]),
  ('1.2.2', 1, 4, 'تعد المدرسة خططاً استراتيجية وسنوية تتسم بالشمولية والجودة، وتغطي الغالبية العظمى من أهداف المدرسة واحتياجاتها وأولوياتها', NULL, ARRAY[61]),
  ('1.2.2', 1, 3, 'تعد المدرسة خططاً استراتيجية وسنوية تتسم بجودة مناسبة، وتغطي بعض أهداف المدرسة وأولوياتها.', NULL, ARRAY[61]),
  ('1.2.2', 1, 2, 'تعد المدرسة خططاً استراتيجية وسنوية تتسم بجودة محدودة، وتغطي قلة من أهداف المدرسة وأولوياتها.
أو
تعد المدرسة خططاً استراتيجية وسنوية شاملة لأهداف المدرسة وأولوياتها، إلا أنها تفتقر للجودة.
أو
تعد المدرسة خططاً استراتيجية وسنوية ذات جودة، إلا أنها تغطي أهداف المدرسة بشكل محدود.', NULL, ARRAY[61]),
  ('1.2.2', 1, 1, 'تعد المدرسة خططاً استراتيجية وسنوية تغطي أهداف المدرسة، إلا أنه يتم تنفيذ الخطط بشكلٍ يسهم في تحقيق قلة من الأهداف، مما يؤثر سلباً على تحقيق الرؤية والرسالة.
أو
لا تعد المدرسة خططاً استراتيجية و/أو سنوية.', NULL, ARRAY[61]),
  ('1.2.2', 2, 5, 'تنفيذ الخطط (الاستراتيجية والسنوية) بشكلٍ فعال جداً وبكفاءة عالية، مما يسهم في تحقيق جميع عناصر الرؤية والرسالة والأهداف وأولويات المدرسة،', NULL, ARRAY[61]),
  ('1.2.2', 2, 4, 'تنفيذ الخطط (الاستراتيجية والسنوية) بشكلٍ فعال وبكفاءة، مما يسهم في تحقيق الغالبية العظمى من عناصر الرؤية والرسالة والأهداف وأولويات المدرسة،', NULL, ARRAY[61]),
  ('1.2.2', 2, 3, 'تنفيذ الخطط (الاستراتيجية والسنوية) بشكلٍ مناسب، مما يسهم في تحقيق معظم عناصر الرؤية والرسالة والأهداف وأولويات المدرسة،', NULL, ARRAY[61]),
  ('1.2.2', 2, 2, 'تنفيذ الخطط (الاستراتيجية والسنوية) بشكلٍ محدود، مما يسهم في تحقيق بعض عناصر الرؤية والرسالة والأهداف وأولويات المدرسة،', NULL, ARRAY[61]),
  ('1.2.2', 2, 1, 'تنفيذ الخطط (الاستراتيجية والسنوية) بشكلٍ محدود جداً، مما يسهم في تحقيق قلة من عناصر الرؤية والرسالة والأهداف وأولويات المدرسة،', NULL, ARRAY[61]),
  ('1.2.2', 3, 5, 'إعداد وتنفيذ خطة متكاملة وشاملة لإدارة الأزمات والطوارئ، مع توفير البنية التحتية والموارد الداعمة، بما يضمن استمرارية العملية التعليمية بشكلٍ فعال جداً لجميع الطلبة، ويعكس جاهزية مؤسسية وكفاءة عالية في القدرة على الاستجابة والتكيف في مختلف الظروف.', NULL, ARRAY[62]),
  ('1.2.2', 3, 4, 'إعداد وتنفيذ خطة شاملة لإدارة الأزمات والطوارئ، مع توفير البنية التحتية والموارد الداعمة، بما يضمن استمرارية العملية التعليمية بشكلٍ فعال للغالبية العظمى من الطلبة.', NULL, ARRAY[62]),
  ('1.2.2', 3, 3, 'إعداد وتنفيذ خطة شاملة لإدارة الأزمات والطوارئ، مع توفير البنية التحتية والموارد الداعمة، بما يضمن استمرارية العملية التعليمية بشكلٍ مناسب لمعظم الطلبة.', NULL, ARRAY[62]),
  ('1.2.2', 3, 2, 'إعداد وتنفيذ خطة لإدارة الأزمات والطوارئ وتوفير الموارد الداعمة، بما يسهم في استمرارية العملية التعليمية بشكلٍ مناسب لبعض الطلبة.
أو
إعداد خطة شاملة لإدارة الأزمات والطوارئ، وتوفير البنية التحتية والموارد الداعمة، إلا أن تنفيذ الخطة يتم بشكلٍ محدود مما يؤثر على استمرارية العملية التعليمية.', NULL, ARRAY[62]),
  ('1.2.2', 3, 1, 'إعداد وتنفيذ خطة لإدارة الأزمات والطوارئ، بما يسهم في استمرارية العملية التعليمية لقلة من الطلبة.
أو
وجود خطة لإدارة الأزمات والطوارئ، إلا أنها تفتقر إلى الجودة والتكامل ولا تلبي المتطلبات اللازمة لضمان استمرارية العملية التعليمية.
أو
لا يتم إعداد / تنفيذ خطة لإدارة الأزمات والطوارئ بما يضمن استمرارية العملية التعليمية.', NULL, ARRAY[62]),
  ('1.2.3', 1, 5, 'إعداد سياسات مدرسية شاملة ومتكاملة وذات جودة عالية تغطي جميع جوانب العمل المدرسي، ويتم نشرها وتوضيحها لكافة الأطراف المعنية بما يضمن وضوحها ويعزز اتساق الممارسات المدرسية.', NULL, ARRAY[62,63]),
  ('1.2.3', 1, 4, 'إعداد سياسات مدرسية ذات جودة تغطي الغالبية العظمى من جوانب العمل المدرسي، ويتم نشرها وتوضيحها لكافة الأطراف المعنية.', NULL, ARRAY[62,63]),
  ('1.2.3', 1, 3, 'إعداد سياسات مدرسية ذات جودة تغطي معظم جوانب العمل المدرسي، ويتم نشرها وتوضيحها لكافة الأطراف المعنية.', NULL, ARRAY[62,63]),
  ('1.2.3', 1, 2, 'إعداد سياسات مدرسية تغطي بعض جوانب العمل المدرسي.
أو
إعداد سياسات تغطي جوانب العمل المختلفة في المدرسة، إلا أنها تفتقر للجودة.
أو
يتم إعداد سياسات تغطي جوانب العمل المختلفة، إلا أن نشرها وتوضيحها للأطراف المعنية يتم بشكلٍ محدود، مما أثر على المعرفة والفهم بها.', NULL, ARRAY[62,63]),
  ('1.2.3', 1, 1, 'إعداد سياسات مدرسية تغطي قلة من جوانب العمل في المدرسة.', NULL, ARRAY[62,63]),
  ('1.2.3', 2, 5, 'يتم تطبيق السياسات بشكلٍ مستمر وفعال جداً، مما يسهم في تنظيم وتسيير جميع جوانب العمل المدرسي.', NULL, ARRAY[63]),
  ('1.2.3', 2, 4, 'يتم تطبيق السياسات بشكلٍ فعال، بما يضمن تنظيم وتسيير الغالبية العظمى من جوانب العمل المدرسي بكفاءة.', NULL, ARRAY[63]),
  ('1.2.3', 2, 3, 'يتم تطبيق السياسات بشكل مناسب، بما يضمن تنظيم وتسيير معظم جوانب العمل المدرسي.', NULL, ARRAY[63]),
  ('1.2.3', 2, 2, 'يتم تطبيق السياسات بشكل محدود ويفتقر للاتساق، مما أدى إلى تنظيم بعض جوانب العمل المدرسي.', NULL, ARRAY[63]),
  ('1.2.3', 2, 1, 'يتم تطبيق السياسات بشكلٍ محدود جداً، مما أدى إلى تنظيم قلة من جوانب العمل المدرسي.
أو
لا يتم الالتزام بتنفيذ السياسات أو يتم بشكل محدود جداً.', NULL, ARRAY[63]),
  ('1.2.3', 3, 5, 'يتم مراجعة جميع السياسات بشكلٍ مستمر وتحديثها عند الحاجة، لضمان توافقها مع المتغيرات الجديدة والتطورات واحتياجات المدرسة.', NULL, ARRAY[63,64]),
  ('1.2.3', 3, 4, 'يتم مراجعة الغالبية العظمى من السياسات بشكلٍ دوري وتحديثها عند الحاجة، وهناك سياسات تحتاج إلى تحسينات طفيفة لضمان توافقها مع المتغيرات الجديدة والتطورات واحتياجات المدرسة.', NULL, ARRAY[63,64]),
  ('1.2.3', 3, 3, 'يتم مراجعة معظم السياسات وتحديثها عند الحاجة، وهناك سياسات تحتاج إلى تحسينات إضافية لضمان التوافق الكامل مع المتغيرات والتطورات واحتياجات المدرسة.', NULL, ARRAY[63,64]),
  ('1.2.3', 3, 2, 'يتم مراجعة السياسات بشكلٍ محدود، ويتم تحديث بعضها، والعديد من السياسات بحاجة إلى تحسينات كبيرة لضمان التوافق مع المتغيرات والتطورات واحتياجات المدرسة.', NULL, ARRAY[63,64]),
  ('1.2.3', 3, 1, 'يتم مراجعة السياسات بشكلٍ محدود جداً، وهناك ضعف كبير في عملية التعديل والتحديث، مما يتطلب مراجعة شاملة وتحسينات كبيرة لضمان توافق السياسات مع المتغيرات والتطورات واحتياجات المدرسة.
أو
لا يتم مراجعة السياسات المدرسية.', NULL, ARRAY[63,64]),
  ('1.2.4', 1, 5, 'الهيكل التنظيمي واضح ومتوافق تماماً مع حجم المدرسة وطبيعتها، وشامل لجميع الأقسام والوظائف، ويتضمن توزيعاً دقيقاً للأدوار والمسؤوليات، ويوضح التسلسل الوظيفي، مما يسهم بشكلٍ فعال جداً في تعزيز التنسيق والمتابعة، وتنظيم العمل.', NULL, ARRAY[64]),
  ('1.2.4', 1, 4, 'الهيكل التنظيمي واضح وشامل للغالبية العظمى من الأقسام والوظائف، ويتضمن توزيعاً للأدوار والمسؤوليات، ويوضح التسلسل الوظيفي، مما يسهم بشكلٍ فعال في تعزيز التنسيق والمتابعة وتنظيم العمل.', NULL, ARRAY[64]),
  ('1.2.4', 1, 3, 'الهيكل التنظيمي واضح وشامل لمعظم الأقسام والوظائف، ويتضمن توزيعاً للأدوار والمسؤوليات، ويوضح التسلسل الوظيفي، مما يعزز التنسيق والمتابعة بشكلٍ مناسب.', NULL, ARRAY[64]),
  ('1.2.4', 1, 2, 'يتوافق الهيكل التنظيمي بشكلٍ محدود مع حجم المدرسة وطبيعتها، حيث يشمل بعض الأقسام والوظائف.', NULL, ARRAY[64]),
  ('1.2.4', 1, 1, 'يتوافق الهيكل التنظيمي بشكلٍ محدود جداً مع حجم المدرسة وطبيعتها، ويشمل قلة من الأقسام والوظائف فقط.
أو
لا يتوافق الهيكل التنظيمي مع حجم المدرسة وطبيعتها.', NULL, ARRAY[64]),
  ('1.2.4', 2, 5, 'تم إعداد توصيف وظيفي دقيق ومفصل لجميع الوظائف في المدرسة، مع تعريف واضح للموظفين بكل مهمة ومسؤولية، مما يضمن فهماً تاماً لمسؤولياتهم، ويعزز قدرتهم على أداء مهامهم بشكلٍ فعال جداً.', NULL, ARRAY[64]),
  ('1.2.4', 2, 4, 'تم إعداد توصيف وظيفي دقيق ومفصل للغالبية العظمى من الوظائف في المدرسة، مع تعريف واضح للموظفين بمهامهم، مما يضمن فهماً لمسؤولياتهم، ويعزز قدرتهم على أداء مهامهم بشكلٍ فعال.', NULL, ARRAY[64]),
  ('1.2.4', 2, 3, 'تم إعداد توصيف وظيفي لمعظم الوظائف في المدرسة، مع تعريف الموظفين بمهامهم، مما يضمن فهماً لمسؤولياتهم، ويعزز قدرتهم على أداء مهامهم بشكلٍ مناسب.', NULL, ARRAY[64]),
  ('1.2.4', 2, 2, 'تم إعداد توصيف وظيفي لبعض الوظائف في المدرسة، مما أدى إلى تعريف الموظفين بمهامهم وفهمهم لمسؤولياتهم بشكلٍ محدود.
أو
تم إعداد توصيف وظيفي للوظائف في المدرسة، مع تعريف محدود للموظفين بمهامهم ومسؤولياتهم.', NULL, ARRAY[64]),
  ('1.2.4', 2, 1, 'تم إعداد توصيف وظيفي لقلة من الوظائف في المدرسة، مما أدى إلى تعريف الموظفين بمهامهم وفهمهم لمسؤولياتهم بشكلٍ محدود جداً.
أو
تم إعداد توصيف وظيفي للوظائف في المدرسة، ولم يتم تعريف الموظفين بمهامهم ومسؤولياتهم،', NULL, ARRAY[64]),
  ('1.2.4', 3, 5, 'يتم توزيع وتفويض المهام بشكلٍ عادل، وحسب مؤهلات وإمكانيات وخبرات جميع الموظفين، وبما يتوافق مع احتياجات كل قسم، مما يسهم بشكلٍ فعال جداً في تعزيز الكفاءة والإنتاجية وسرعة إنجاز العمل.', NULL, ARRAY[65]),
  ('1.2.4', 3, 4, 'يتم توزيع وتفويض المهام بشكلٍ عادل، وحسب مؤهلات وإمكانيات وخبرات الغالبية العظمى من الموظفين، مما يسهم بشكلٍ فعال في تعزيز الإنتاجية وسرعة إنجاز العمل.', NULL, ARRAY[65]),
  ('1.2.4', 3, 3, 'يتم توزيع وتفويض المهام بشكلٍ عادل، وحسب مؤهلات وخبرات معظم الموظفين، مما يسهم بشكلٍ مناسب في تعزيز الإنتاجية وإنجاز العمل.', NULL, ARRAY[65]),
  ('1.2.4', 3, 2, 'يتم توزيع وتفويض المهام حسب مؤهلات وخبرات بعض الموظفين، مما يسهم بشكلٍ محدود في تعزيز الكفاءة وإنجاز العمل.
أو
يتم توزيع وتفويض المهام بين الموظفين حسب المؤهلات والخبرات، إلا أن ذلك لا يتم بشكلٍ عادل مما أثر على كفاءة العمل.', NULL, ARRAY[65]),
  ('1.2.4', 3, 1, 'يتم توزيع وتفويض المهام، حسب مؤهلات وخبرات قلة من الموظفين، مما أثر سلباً على تعزيز الكفاءة في العمل.
أو
لا يتم توزيع وتفويض المهام بشكلٍ عادل / حسب مؤهلات وخبرات الموظفين.', NULL, ARRAY[65]),
  ('1.2.4', 4, 5, 'يتم تطبيق آلية وإجراءات واضحة ومنظمة لمتابعة وتغطية غياب الموظفين، وضمان التزامهم بمواعيد العمل في جميع الأقسام والمراحل الدراسية، مما يسهم بشكلٍ فعال جداً في ضمان سير العملية التعليمية وكفاءة الأداء الإداري والتعليمي.', NULL, ARRAY[65]),
  ('1.2.4', 4, 4, 'يتم تطبيق آلية وإجراءات واضحة ومنظمة لمتابعة وتغطية غياب الموظفين، وضمان التزامهم بمواعيد العمل في الغالبية العظمى من الأقسام والمراحل الدراسية، مما يسهم بشكلٍ فعال في ضمان سير العملية التعليمية وكفاءة الأداء.', NULL, ARRAY[65]),
  ('1.2.4', 4, 3, 'يتم تطبيق آلية وإجراءات واضحة ومنظمة لمتابعة وتغطية غياب الموظفين، وضمان التزامهم بمواعيد العمل في معظم الأقسام والمراحل الدراسية، مما يسهم بشكلٍ مناسب في ضمان سير العملية التعليمية.', NULL, ARRAY[65]),
  ('1.2.4', 4, 2, 'يتم تطبيق آلية وإجراءات واضحة لمتابعة وتغطية غياب الموظفين في بعض الأقسام والمراحل الدراسية، مما يسهم بشكلٍ محدود في ضمان سير العملية التعليمية.', NULL, ARRAY[65]),
  ('1.2.4', 4, 1, 'يتم تطبيق آلية وإجراءات-لمتابعة وتغطية غياب الموظفين في قلة من الأقسام والمراحل الدراسية، مما يسهم بشكلٍ محدود جداً في ضمان سير العملية التعليمية.
أو
لا يتم متابعة دوام الموظفين /تغطية غياب الموظفين.', NULL, ARRAY[65]),
  ('1.3.1', 1, 5, 'يتم متابعة وتقييم أداء الموظفين كلٌ حسب وصفه الوظيفي بانتظام، وفق إجراءات واضحة ومعلنة وفعالة جداً، ويتم تقديم تغذية راجعة منتظمة ودقيقة، مما يسهم في تحسين أداء جميع الموظفين.', NULL, ARRAY[66]),
  ('1.3.1', 1, 4, 'يتم متابعة وتقييم أداء الموظفين كلٌ حسب وصفه الوظيفي بانتظام وفق إجراءات فعالة ومعلنة، ويتم تقديم تغذية راجعة منتظمة، مما يسهم في تحسين أداء الغالبية العظمى من الموظفين.', NULL, ARRAY[66]),
  ('1.3.1', 1, 3, 'يتم متابعة وتقييم أداء الموظفين بانتظام وفق إجراءات مناسبة، ويتم تقديم تغذية راجعة منتظمة، مما يسهم في تحسين أداء معظم الموظفين.', NULL, ARRAY[66]),
  ('1.3.1', 1, 2, 'يتم متابعة وتقييم أداء الموظفين بشكلٍ محدود، مع تقديم تغذية راجعة غير منتظمة / محدودة، مما أدى إلى تحسين أداء بعض الموظفين.
أو
يتم متابعة وتقييم أداء الموظفين، مع تقديم تغذية راجعة محدودة، مما أدى إلى تحسين أداء بعض الموظفين.
أو
إجراءات متابعة وتقييم أداء الموظفين واضحة، إلا أن تطبيقها يقتصر على بعض الموظفين، مما أثر على تحسين الأداء الوظيفي.', NULL, ARRAY[66]),
  ('1.3.1', 1, 1, 'يتم تقييم ومتابعة أداء الموظفين بشكلٍ محدود جداً، مع تقديم تغذية راجعة غير منتظمة / عدم تقديم تغذية راجعة، مما أدى إلى تحسن أداء قلة من الموظفين.
أو
إجراءات متابعة وتقييم أداء الموظفين غير واضحة وتفتقر للجودة، مما أثر سلباً على تحسين الأداء الوظيفي.
أو
لا يتم متابعة وتقييم أداء الموظفين.', NULL, ARRAY[66]),
  ('1.3.2', 1, 5, 'تطبيق آلية وإجراءات فعالة جداً وواضحة ومتنوعة ومنتظمة لمراقبة ومتابعة التحصيل الأكاديمي للطلبة، والاستفادة من تحليل النتائج والمتابعة في اتخاذ القرارات المناسبة لدعم العملية التعليمية والتعديل على الخطط والسياسات، مما يسهم في تحسين ودعم تعلم جميع الطلبة.', NULL, ARRAY[67]),
  ('1.3.2', 1, 4, 'تطبيق آلية وإجراءات فعالة وواضحة ومنتظمة لمراقبة ومتابعة التحصيل الأكاديمي للطلبة، والاستفادة من تحليل النتائج والمتابعة في اتخاذ القرارات المناسبة لدعم العملية التعليمية والتعديل على الخطط والسياسات، مما يسهم في تحسين ودعم تعلم الغالبية العظمى من الطلبة.', NULL, ARRAY[67]),
  ('1.3.2', 1, 3, 'تطبيق آلية وإجراءات مناسبة لمراقبة ومتابعة التحصيل الأكاديمي للطلبة، والاستفادة من تحليل النتائج والمتابعة في اتخاذ القرارات المناسبة لدعم العملية التعليمية والتعديل على الخطط، مما يسهم في تحسين ودعم تعلم معظم الطلبة.', NULL, ARRAY[67]),
  ('1.3.2', 1, 2, 'تطبيق إجراءات محدودة لمراقبة ومتابعة التحصيل الأكاديمي للطلبة والاستفادة من نتائجهم، مما أدى إلى تحسن ودعم تعلم بعض الطلبة.
أو
تطبيق آلية وإجراءات واضحة لمراقبة ومتابعة التحصيل الأكاديمي للطلبة، إلا أن الاستفادة من تحليل النتائج والمتابعة في اتخاذ القرارات الداعمة للعملية التعليمية تتم بشكلٍ محدود، مما أدى إلى تحسين ودعم تعلم بعض الطلبة.', NULL, ARRAY[67]),
  ('1.3.2', 1, 1, 'تطبيق إجراءات محدودة جداً لمراقبة ومتابعة التحصيل الأكاديمي للطلبة والاستفادة من نتائجهم، مما أدى إلى دعم تعلم قلة من الطلبة أو لم يكن لها أثر في تحسين تعلم الطلبة.', NULL, ARRAY[67]),
  ('1.3.2', 2, 5, 'تطبيق آلية وإجراءات فعالة جداً وواضحة وشاملة ومستمرة لمراقبة ومتابعة سلوك الطلبة، والاستفادة منها في وضع برامج وخطط متكاملة مما أسهم في ضبط وتعزيز سلوك جميع الطلبة.', NULL, ARRAY[67,68]),
  ('1.3.2', 2, 4, 'تطبيق آلية وإجراءات فعالة وواضحة ومستمرة لمراقبة ومتابعة سلوك الطلبة، والاستفادة منها مما أسهم في ضبط وتعزيز سلوك الغالبية العظمى من الطلبة.', NULL, ARRAY[67,68]),
  ('1.3.2', 2, 3, 'تطبيق آلية وإجراءات مناسبة لمراقبة ومتابعة سلوك الطلبة، والاستفادة منها في وضع برامج وخطط مما أسهم في ضبط وتعزيز سلوك معظم الطلبة.', NULL, ARRAY[67,68]),
  ('1.3.2', 2, 2, 'تطبيق إجراءات محدودة لمراقبة ومتابعة سلوك الطلبة، أدت إلى ضبط وتعزيز سلوك بعض الطلبة.
أو
تطبيق إجراءات لمراقبة ومتابعة سلوك الطلبة، والاستفادة منها في وضع البرامج والخطط، إلا أن ذلك انعكس بشكلٍ محدود على ضبط وتعزيز سلوك الطلبة.', NULL, ARRAY[67,68]),
  ('1.3.2', 2, 1, 'تطبيق إجراءات محدودة جداً لمراقبة ومتابعة سلوك الطلبة، أدت إلى ضبط وتعزيز سلوك قلة من الطلبة.
أو
لا يوجد إجراءات لمراقبة ومتابعة سلوك الطلبة', NULL, ARRAY[67,68]),
  ('1.3.3', 1, 5, 'تطبيق آلية وإجراءات فعالة جداً واضحة وشاملة ومستمرة لمتابعة وتقييم الخطط والبرامج، ويتم مراجعة وتحديث الخطط والبرامج بشكلٍ شامل بناءً على نتائج التقييم والتغذية الراجعة، مما أدى إلى تحقيق جميع أهدافها.', NULL, ARRAY[68]),
  ('1.3.3', 1, 4, 'تطبيق آلية وإجراءات فعالة وواضحة ومستمرة لمتابعة وتقييم الخطط والبرامج، ويتم مراجعة وتحديث الخطط والبرامج بناءً على نتائج التقييم والتغذية الراجعة، مما أدى إلى تحقيق الغالبية العظمى من أهدافها.', NULL, ARRAY[68]),
  ('1.3.3', 1, 3, 'تطبيق آلية وإجراءات مناسبة لمتابعة وتقييم الخطط والبرامج، ويتم مراجعة الخطط والبرامج وتحديثها بناءً على نتائج التقييم، مما أدى إلى تحقيق معظم أهدافها.', NULL, ARRAY[68]),
  ('1.3.3', 1, 2, 'تنفيذ إجراءات محدودة لمتابعة وتقييم الخطط والبرامج، ويتم مراجعتها بشكلٍ غير منتظم مما أدى إلى تحقيق بعض أهدافها.', NULL, ARRAY[68]),
  ('1.3.3', 1, 1, 'تنفيذ إجراءات محدودة جداً لمتابعة وتقييم الخطط والبرامج، مما أدى إلى تحقيق قلة من أهدافها.
أو
لا يتم متابعة وتقييم الخطط والبرامج.', NULL, ARRAY[68]),
  ('1.3.4', 1, 5, 'تُطبّق المدرسة أنظمة أتمتة متكاملة تغطي جميع العمليات التعليمية والإدارية، ويتم توظيفها بشكلٍ منهجي ومنتظم في متابعة أداء الموظفين والطلبة وتنفيذ الخطط المدرسية، مع دقة عالية في إدخال البيانات وتحديثها بصورة مستمرة، بما يضمن موثوقية التقارير والمخرجات الصادرة عن هذه الأنظمة، ويُسهم بشكلٍ فعال جداً في تعزيز كفاءة الأداء وفاعلية المتابعة والمساءلة.', NULL, ARRAY[68,69]),
  ('1.3.4', 1, 4, 'تُطبّق المدرسة أنظمة أتمتة تغطي الغالبية العظمى من العمليات التعليمية والإدارية، ويتم توظيفها بشكلٍ منهجي ومنتظم في متابعة أداء الموظفين والطلبة وتنفيذ الخطط المدرسية، مع دقة في إدخال البيانات وتحديثها، بما يضمن موثوقية التقارير والمخرجات الصادرة عن هذه الأنظمة، ويُسهم بشكلٍ فعال في تعزيز كفاءة الأداء وفاعلية المتابعة والمساءلة.', NULL, ARRAY[68,69]),
  ('1.3.4', 1, 3, 'تُطبّق المدرسة أنظمة أتمتة تغطي معظم العمليات التعليمية والإدارية، ويتم توظيفها في متابعة أداء الموظفين والطلبة وتنفيذ الخطط المدرسية، مع دقة في إدخال البيانات وتحديثها، بما يضمن موثوقية التقارير والمخرجات الصادرة عن هذه الأنظمة، ويُسهم بشكلٍ مناسب في تعزيز كفاءة الأداء وفاعلية المتابعة والمساءلة.', NULL, ARRAY[68,69]),
  ('1.3.4', 1, 2, 'تُطبّق المدرسة أنظمة أتمتة تغطي بعض العمليات التعليمية والإدارية، مع دقة في إدخال البيانات وتحديثها، مما يسهم بشكلٍ محدود في تعزيز كفاءة الأداء وفاعلية المتابعة والمساءلة.
أو
تُطبّق المدرسة أنظمة أتمتة لإدارة العمليات التعليمية والإدارية، مع وجود تفاوت في تفعيل استخدامها وانتظام إدخال البيانات، مما أثر على فاعلية متابعة الأداء وتعزيز المساءلة.
أو
تُطبّق المدرسة أنظمة أتمتة لإدارة العمليات التعليمية والإدارية، إلا أن البيانات تفتقر إلى الجودة، مما أثر على موثوقية التقارير والمخرجات الصادرة عن هذه الأنظمة وفاعلية استخدامها.', NULL, ARRAY[68,69]),
  ('1.3.4', 1, 1, 'تُطبّق المدرسة أنظمة أتمتة تغطي قلة من العمليات التعليمية والإدارية، مما يسهم بشكلٍ محدود جداً في متابعة الأداء وتعزيز المساءلة.
أو
لا تُطبّق المدرسة أنظمة أتمتة، مما يؤثر سلباً على فعالية متابعة الأداء وتعزيز المساءلة.', NULL, ARRAY[68,69]),
  ('1.3.5', 1, 5, 'يتم متابعة أداء المدرسة من قبل المالك / مجلس الإدارة بانتظام وبشكلٍ شامل ودقيق، لقياس مدى تقدم المدرسة نحو تحقيق أهدافها الاستراتيجية، ويتم تقديم الدعم والتوجيه الكامل بشكلٍ فعال جداً للإدارة التنفيذية، مما يعزز تنفيذ الخطة الاستراتيجية ويضمن تحقيق جميع أهدافها بنجاح وبكفاءة عالية.', NULL, ARRAY[69,70]),
  ('1.3.5', 1, 4, 'يتم متابعة أداء المدرسة من قبل المالك / مجلس الإدارة بانتظام وبشكلٍ شامل، لقياس مدى تقدم المدرسة نحو تحقيق أهدافها الاستراتيجية، ويتم تقديم الدعم والتوجيه بشكلٍ فعال للإدارة التنفيذية، مما يعزز تنفيذ الخطة الاستراتيجية ويضمن تحقيق الغالبية العظمى من أهدافها بكفاءة.', NULL, ARRAY[69,70]),
  ('1.3.5', 1, 3, 'يتم متابعة أداء المدرسة من قبل المالك / مجلس الإدارة بانتظام، لقياس مدى تقدم المدرسة نحو تحقيق أهدافها الاستراتيجية، ويتم تقديم الدعم والتوجيه بشكلٍ مناسب للإدارة التنفيذية، مما يعزز تنفيذ الخطة الاستراتيجية ويضمن تحقيق معظم أهدافها.', NULL, ARRAY[69,70]),
  ('1.3.5', 1, 2, 'يتم متابعة أداء المدرسة وتقديم الدعم والتوجيه للإدارة التنفيذية من قبل المالك / مجلس الإدارة بشكلٍ محدود، مما أدى إلى تحقيق بعض الأهداف.
أو
يتم متابعة أداء المدرسة من قبل المالك / مجلس الإدارة، ولكن يتم تقديم الدعم والتوجيه للإدارة التنفيذية بشكلٍ محدود، مما أدى إلى تحقيق بعض الأهداف.', NULL, ARRAY[69,70]),
  ('1.3.5', 1, 1, 'يتم متابعة أداء المدرسة وتقديم الدعم والتوجيه للإدارة التنفيذية من قبل المالك / مجلس الإدارة بشكلٍ محدود جداً، مما أدى إلى تحقيق قلة من الأهداف.
أو
لا يتم متابعة أداء المدرسة من قبل المالك / مجلس الإدارة.', NULL, ARRAY[69,70]),
  ('1.4.1', 1, 5, 'تُطبق المدرسة آلية وإجراءات منهجية واضحة ومحددة لتقييم أدائها وإعداد الدراسة الذاتية بمشاركة جميع الأطراف المعنية والاستفادة بفعالية عالية من مشاركتهم مما انعكس على إعداد الدراسة الذاتية بجودة عالية.', NULL, ARRAY[70]),
  ('1.4.1', 1, 4, 'تُطبق المدرسة آلية وإجراءات منهجية واضحة لتقييم أدائها وإعداد الدراسة الذاتية، بمشاركة الغالبية العظمى من الأطراف المعنية والاستفادة بفعالية من مشاركتهم، مما انعكس على إعداد الدراسة الذاتية بجودة.', NULL, ARRAY[70]),
  ('1.4.1', 1, 3, 'تُطبق المدرسة آلية وإجراءات واضحة لتقييم أدائها وإعداد الدراسة الذاتية، بمشاركة معظم الأطراف المعنية والاستفادة من مشاركتهم بشكلٍ مناسب مما انعكس على إعداد الدراسة الذاتية بجودة مناسبة.', NULL, ARRAY[70]),
  ('1.4.1', 1, 2, 'تطبق المدرسة إجراءات محدودة لتقييم أدائها وإعداد الدراسة الذاتية، بمشاركة بعض الأطراف المعنية مما أدى إلى انخفاض جودة الدراسة الذاتية.', NULL, ARRAY[70]),
  ('1.4.1', 1, 1, 'تقوم المدرسة بتقييم أدائها وإعداد الدراسة الذاتية بمشاركة قلة من الأطراف المعنية مما أدى إلى جودة محدودة جداً.
أو
لا يتم مشاركة الأطراف المعنية في إعداد الدراسة الذاتية.', NULL, ARRAY[70]),
  ('1.4.1', 2, 5, 'تتسم نتائج الدراسة الذاتية بدقة عالية جداً والواقعية في التعبير عن الواقع الفعلي للمدرسة، وتدعّم بأدلة وشواهد متسقة معها، وتتوافق جميع نتائج الدراسة الذاتية ونقاط القوة والتحسين مع نتائج التقييم الخارجي لفريق الاعتماد.', NULL, ARRAY[70,71]),
  ('1.4.1', 2, 4, 'تتسم نتائج الدراسة الذاتية بدقة عالية والواقعية في التعبير عن الواقع الفعلي للمدرسة، وتدعّم بأدلة وشواهد متسقة معها، وتتوافق الغالبية العظمى من نتائج الدراسة الذاتية ونقاط القوة والتحسين مع نتائج التقييم الخارجي لفريق الاعتماد.', NULL, ARRAY[70,71]),
  ('1.4.1', 2, 3, 'تتسم نتائج الدراسة الذاتية بالدقة والواقعية بشكلٍ مناسب في التعبير عن الواقع الفعلي للمدرسة، وتدعّم بأدلة وشواهد متسقة معها، وتتوافق معظم نتائج الدراسة الذاتية ونقاط القوة والتحسين مع نتائج التقييم الخارجي لفريق الاعتماد.', NULL, ARRAY[70,71]),
  ('1.4.1', 2, 2, 'تتسم نتائج الدراسة الذاتية بشكلٍ محدود من الواقعية في التعبير عن الواقع الفعلي للمدرسة، وتدعّم بأدلة وشواهد محدودة، وتتوافق بعض نتائج الدراسة الذاتية ونقاط القوة والتحسين مع نتائج التقييم الخارجي لفريق الاعتماد.', NULL, ARRAY[70,71]),
  ('1.4.1', 2, 1, 'تتسم نتائج الدراسة الذاتية بشكلٍ محدود جداً من الواقعية، وتتوافق قلة من نتائج الدراسة الذاتية ونقاط القوة والتحسين مع نتائج التقييم الخارجي لفريق الاعتماد، مع ضعف في الدقة والواقعية وندرة في الأدلة والشواهد الداعمة.
أو
لا تتسم نتائج تقرير الدراسة الذاتية بالدقة والواقعية في التعبير عن الواقع الفعلي للمدرسة، ولم تتمكن من تحديد نقاط التحسين في المدرسة، وتفتقر إلى الأدلة والشواهد الداعمة، ولا تتوافق نتائجها مع نتائج التقييم الخارجي لفريق الاعتماد.', NULL, ARRAY[70,71]),
  ('1.4.2', 1, 5, 'شمولية خطة التحسين لجميع جوانب التحسين التي حددتها المدرسة لنفسها في تقرير الدراسة الذاتية.', NULL, ARRAY[71]),
  ('1.4.2', 1, 4, 'شمولية خطة التحسين للغالبية العظمى من جوانب التحسين التي حددتها المدرسة لنفسها في تقرير الدراسة الذاتية.', NULL, ARRAY[71]),
  ('1.4.2', 1, 3, 'شمولية خطة التحسين لمعظم جوانب التحسين التي حددتها المدرسة لنفسها في تقرير الدراسة الذاتية.', NULL, ARRAY[71]),
  ('1.4.2', 1, 2, 'شمولية خطة التحسين لبعض جوانب التحسين التي حددتها المدرسة لنفسها في تقرير الدراسة الذاتية', NULL, ARRAY[71]),
  ('1.4.2', 1, 1, 'شمولية خطة التحسين لقلة من جوانب التحسين التي حددتها المدرسة لنفسها في تقرير الدراسة الذاتية.', NULL, ARRAY[71]),
  ('1.4.2', 2, 5, 'جميع مكونات خطة التحسين ذات جودة عالية، ومُعَدَّة بدقةٍ ووضوح، وتتوافق الخطة مع إمكانات المدرسة ومواردها المادية والبشرية بشكلٍ فعال جداً.', NULL, ARRAY[72]),
  ('1.4.2', 2, 4, 'الغالبية العظمى من مكونات خطة التحسين مُعَدَّة بدقةٍ ووضوح، وتتوافق الخطة مع إمكانات المدرسة ومواردها المادية والبشرية بشكلٍ فعال.', NULL, ARRAY[72]),
  ('1.4.2', 2, 3, 'معظم مكونات خطة التحسين مُعَدَّة بدقةٍ ووضوح، وتتوافق الخطة مع إمكانات المدرسة ومواردها المادية والبشرية بشكلٍ مناسب.', NULL, ARRAY[72]),
  ('1.4.2', 2, 2, 'بعض مكونات خطة التحسين مُعَدَّة بدقةٍ ووضوح، في حين تفتقر بقية المكونات إلى ذلك.
أو
تتسم مكونات خطة التحسين بالدقة والوضوح، إلا أن الخطة تتوافق بشكلٍ محدود مع إمكانات المدرسة ومواردها المادية والبشرية.', NULL, ARRAY[72]),
  ('1.4.2', 2, 1, 'قلة من مكونات خطة التحسين مُعَدَّة بدقةٍ ووضوح، مع ضعف عام في جودة بقية المكونات.
أو
لا تتوافق خطة التحسين مع إمكانات المدرسة ومواردها المادية والبشرية.', NULL, ARRAY[72]),
  ('1.4.3', 1, 5, 'يعكس تقرير تقدم الأداء العمل بشكلٍ شامل على جميع جوانب التحسين، ويقدم معلومات شاملة وبيانات دقيقة للنتائج والتحسين الذي تم تحقيقه مدعماً بالأدلة الكافية والشاملة.', NULL, ARRAY[72]),
  ('1.4.3', 1, 4, 'يعكس تقرير تقدم الأداء العمل على الغالبية العظمى من جوانب التحسين، ويقدم معلومات وبيانات دقيقة للنتائج والتحسين الذي تم تحقيقه مدعماً بالأدلة الكافية.', NULL, ARRAY[72]),
  ('1.4.3', 1, 3, 'يعكس تقرير تقدم الأداء العمل على معظم جوانب التحسين، ويقدم معلومات وبيانات مناسبة للتحسين الذي تم تحقيقه مدعماً بالأدلة المناسبة.', NULL, ARRAY[72]),
  ('1.4.3', 1, 2, 'يعكس تقرير تقدم الأداء العمل على بعض جوانب التحسين، ويقدم معلومات وبيانات وأدلة محدودة للتحسين الذي تم تحقيقه.
أو
يعكس تقرير تقدم الأداء العمل على جوانب التحسين، إلا أن بعض المعلومات والبيانات أو/ والأدلة الواردة فيه تتسم بالدقة أو الشمول.', NULL, ARRAY[72]),
  ('1.4.3', 1, 1, 'يعكس تقرير تقدم الأداء العمل على قلة من جوانب التحسين.', NULL, ARRAY[72]),
  ('1.5.1', 1, 5, 'آلية وطرق التواصل بين القيادة والموظفين، وبين الموظفين وبعضهم البعض متنوعة وفعالة جداً وتسهم في إنجاز العمل بكفاءة عالية، كما أن الجو العام في المدرسة إيجابي، ويتسم بالتعاون والانتماء، والإحساس بالمسؤولية بين جميع الموظفين.', NULL, ARRAY[73,74]),
  ('1.5.1', 1, 4, 'آلية وطرق التواصل بين القيادة والموظفين، وبين الموظفين وبعضهم البعض متنوعة وفعالة وتسهم في إنجاز العمل بكفاءة، كما أن الجو العام في المدرسة إيجابي، ويتسم بالتعاون، والإحساس بالمسؤولية بين الغالبية العظمى من الموظفين.', NULL, ARRAY[73,74]),
  ('1.5.1', 1, 3, 'آلية وطرق التواصل بين القيادة والموظفين، وبين الموظفين وبعضهم البعض متنوعة وتسهم في إنجاز العمل بشكلٍ مناسب، كما أن الجو العام في المدرسة إيجابي، ويتسم بالتعاون، والإحساس بالمسؤولية بين معظم الموظفين.', NULL, ARRAY[73,74]),
  ('1.5.1', 1, 2, 'طرق التواصل بين القيادة والموظفين، وبين الموظفين وبعضهم البعض محدودة، مما أثر على إنجاز العمل، كما أن الجو العام في المدرسة يتسم بالتعاون، والإحساس بالمسؤولية بين بعض الموظفين.
أو
طرق التواصل بين القيادة والموظفين، وبين الموظفين وبعضهم البعض متنوعة، إلا أن الجو العام في المدرسة يفتقر إلى الإيجابية والتعاون.
أو
طرق التواصل بين القيادة والموظفين، وبين الموظفين وبعضهم البعض محدودة / غير منتظمة، إلا أن الجو العام في المدرسة يتسم بالإيجابية والتعاون المقبول والإحساس بالمسؤولية بين العاملين.', NULL, ARRAY[73,74]),
  ('1.5.1', 1, 1, 'طرق التواصل بين القيادة والموظفين، وبين الموظفين وبعضهم البعض محدودة جداً، مما أثر سلباً على إنجاز العمل، كما أن الجو العام في المدرسة يتسم بالتعاون، والإحساس بالمسؤولية بين قلة من الموظفين.', NULL, ARRAY[73,74]),
  ('1.5.1', 2, 5, 'يتم صرف رواتب الموظفين في الوقت المحدد، وتطبيق نظام حوافز فعال جداً يُعزز استقرار الموظفين ويحفزهم على تقديم أداء متميز، وقد بلغت نسبة انتقال الموظفين خلال الأعوام الثلاثة الأخيرة أقل من 10%.', NULL, ARRAY[74]),
  ('1.5.1', 2, 4, 'يتم صرف رواتب الموظفين في الوقت المحدد، وتطبيق نظام حوافز فعال يُعزز استقرار الموظفين ويحفزهم على الأداء بجودة، وقد تراوحت نسبة انتقال الموظفين خلال الأعوام الثلاثة الأخيرة بين (10% - 15%).', NULL, ARRAY[74]),
  ('1.5.1', 2, 3, 'يتم صرف رواتب الموظفين في الوقت المحدد، وتطبيق نظام حوافز مناسب يُعزز استقرار الموظفين ويحفزهم على الأداء الجيد، وقد تراوحت نسبة انتقال الموظفين خلال الأعوام الثلاثة الأخيرة بين (16% - 20%).', NULL, ARRAY[74]),
  ('1.5.1', 2, 2, 'يتم صرف رواتب الموظفين في الوقت المحدد، لكن يتم تطبيق نظام حوافز يُعزز استقرار الموظفين بشكلٍ محدود، وقد تراوحت نسبة انتقال الموظفين خلال الأعوام الثلاثة الأخيرة بين (21% - 25%).
أو
يتم صرف رواتب الموظفين في الوقت المحدد، ويتم تطبيق نظام حوافز، إلا أن نسبة انتقال الموظفين خلال الأعوام الثلاثة الأخيرة تراوحت بين (21% - 25%).', NULL, ARRAY[74]),
  ('1.5.1', 2, 1, 'يتم صرف رواتب الموظفين في الوقت المحدد، لكن لا يتم تطبيق نظام حوافز، وقد تجاوزت نسبة انتقال الموظفين في الأعوام الثلاثة الأخيرة 25%.
أو
لا يتم صرف رواتب الموظفين في الوقت المحدد.', NULL, ARRAY[74]),
  ('1.5.1', 3, 5, 'يتم تنفيذ آلية وإجراءات متنوعة وفعالة جداً ومستمرة لقياس رضا الموظفين عن كافة جوانب العمل في المدرسة، ويشارك جميع الموظفين في الاستجابة لاستبانات ذات جودة لقياس مدى الرضا حول جوانب العمل المختلفة.', NULL, ARRAY[74,75]),
  ('1.5.1', 3, 4, 'يتم تنفيذ آلية وإجراءات متنوعة وفعالة ومستمرة لقياس رضا الموظفين عن كافة جوانب العمل في المدرسة، ويشارك الغالبية العظمى من الموظفين في الاستجابة لاستبانات ذات جودة لقياس مدى الرضا حول جوانب العمل المختلفة.', NULL, ARRAY[74,75]),
  ('1.5.1', 3, 3, 'يتم تنفيذ آلية وإجراءات متنوعة لقياس رضا الموظفين عن جوانب العمل في المدرسة، ويشارك معظم الموظفين في الاستجابة لاستبانات ذات جودة لقياس مدى الرضا حول جوانب العمل في المختلفة.', NULL, ARRAY[74,75]),
  ('1.5.1', 3, 2, 'يتم تنفيذ إجراءات لقياس رضا الموظفين عن جوانب العمل في المدرسة، ويشارك بعض الموظفين في الاستجابة لاستبانات لقياس مدى الرضا حول جوانب العمل المختلفة.
أو
يشارك الموظفون في الاستجابة لاستبانات لقياس مدى الرضا حول جوانب العمل، لكن الاستبانات تفتقر للجودة.', NULL, ARRAY[74,75]),
  ('1.5.1', 3, 1, 'يتم تنفيذ إجراءات لقياس رضا الموظفين عن جوانب العمل في المدرسة، ويشارك قلة من الموظفين في الاستجابة لاستبانات قياس مدى الرضا حول جوانب العمل المختلفة.
أو
لا يتم اجراء استبانات لقياس مدى رضا الموظفين حول جوانب العمل المختلفة.', NULL, ARRAY[74,75]),
  ('1.5.1', 4, 5, 'يظهر تحليل نتائج استبانات قياس الرضا أن متوسط رضا الموظفين يتراوح بين (90% - 100%). (بشرط ألّا تقل نسبة المشاركة عن 70% من الموظفين)', NULL, ARRAY[75]),
  ('1.5.1', 4, 4, 'يظهر تحليل نتائج استبانات قياس الرضا أن متوسط رضا الموظفين يتراوح بين (80% - 89%). (بشرط ألّا تقل نسبة المشاركة عن 70% من الموظفين)', NULL, ARRAY[75]),
  ('1.5.1', 4, 3, 'يظهر تحليل نتائج استبانات قياس الرضا أن متوسط رضا الموظفين يتراوح بين (70% - 79%). (بشرط ألّا تقل نسبة المشاركة عن 70% من الموظفين)', NULL, ARRAY[75]),
  ('1.5.1', 4, 2, 'يظهر تحليل نتائج استبانات قياس الرضا أن متوسط رضا الموظفين يتراوح بين (60% - 69%).
أو
يظهر تحليل نتائج استبانات قياس الرضا أن متوسط رضا الموظفين يتراوح بين (70% - 100%)، ولكن نسبة المشاركة تقل عن 70% من الموظفين.', NULL, ARRAY[75]),
  ('1.5.1', 4, 1, 'يظهر تحليل نتائج استبانات قياس الرضا أن متوسط رضا الموظفين أقل من (60%).', NULL, ARRAY[75]),
  ('1.5.2', 1, 5, 'يتم التواصل مع الطلبة بطرق متنوعة وفعالة جداً ومنتظمة، بما يضمن الوعي بالخدمات المقدمة والمشاركة الإيجابية لجميع الطلبة في الحياة المدرسية.', NULL, ARRAY[75,76]),
  ('1.5.2', 1, 4, 'يتم التواصل مع الطلبة بطرق متنوعة وفعالة ومنتظمة، بما يضمن الوعي بالخدمات المقدمة والمشاركة الإيجابية للغالبية العظمى من الطلبة في الحياة المدرسية.', NULL, ARRAY[75,76]),
  ('1.5.2', 1, 3, 'يتم التواصل مع الطلبة بطرق مناسبة، بما يضمن الوعي بالخدمات المقدمة والمشاركة الإيجابية لمعظم الطلبة في الحياة المدرسية.', NULL, ARRAY[75,76]),
  ('1.5.2', 1, 2, 'يتم التواصل مع الطلبة بطرق محدودة، مما أدى إلى وعي بعض الطلبة بالخدمات المقدمة، وأثر على مستوى مشاركتهم في الحياة المدرسية.
أو
يتم التواصل مع الطلبة بطرق متنوعة، إلا أن ذلك انعكس على مشاركة بعض الطلبة فقط في الحياة المدرسية.', NULL, ARRAY[75,76]),
  ('1.5.2', 1, 1, 'يتم التواصل مع الطلبة بطرق محدودة جداً، مما أدى إلى وعي قلة من الطلبة بالخدمات المقدمة، وأثر سلباً على مستوى مشاركتهم في الحياة المدرسية.', NULL, ARRAY[75,76]),
  ('1.5.2', 2, 5, 'يتم تنفيذ آلية وإجراءات متنوعة وفعالة جداً ومستمرة، لقياس رضا الطلبة وأخذ آرائهم ومقترحاتهم عن الخدمات المدرسية، والاستفادة منها في تطوير جوانب العمل، ويشارك جميع الطلبة في الاستجابة لاستبانات ذات جودة لقياس مدى رضاهم حول جوانب العمل المختلفة.', NULL, ARRAY[76]),
  ('1.5.2', 2, 4, 'يتم تنفيذ آلية وإجراءات متنوعة وفعالة ومستمرة، لقياس رضا الطلبة وأخذ آرائهم ومقترحاتهم عن الخدمات المدرسية، والاستفادة منها في تطوير جوانب العمل، ويشارك الغالبية العظمى من الطلبة في الاستجابة لاستبانات ذات جودة لقياس مدى الرضا حول جوانب العمل المختلفة.', NULL, ARRAY[76]),
  ('1.5.2', 2, 3, 'يتم تنفيذ آلية وإجراءات مناسبة لقياس رضا الطلبة وأخذ آرائهم ومقترحاتهم عن الخدمات المدرسية والاستفادة منها في تطوير جوانب العمل، ويشارك معظم الطلبة في الاستجابة لاستبانات ذات جودة لقياس مدى الرضا حول جوانب العمل في المختلفة.', NULL, ARRAY[76]),
  ('1.5.2', 2, 2, 'يتم تنفيذ إجراءات محدودة لقياس رضا الطلبة وأخذ مقترحاتهم عن الخدمات المدرسية، ويشارك بعض الطلبة في الاستجابة لاستبانات لقياس مدى الرضا حول جوانب العمل المختلفة.
أو
يشارك الطلبة في الاستجابة لاستبانات لقياس مدى الرضا حول جوانب العمل، لكن الاستبانات تفتقر للجودة.
أو
يشارك الطلبة في الاستجابة لاستبانات لقياس مدى الرضا حول جوانب العمل، لكن لا يتم الاستفادة منها في تطوير جوانب العمل.', NULL, ARRAY[76]),
  ('1.5.2', 2, 1, 'يتم تنفيذ إجراءات لقياس رضا الطلبة عن الخدمات المدرسية، ويشارك قلة من الطلبة في الاستجابة لاستبانات لقياس مدى الرضا حول جوانب العمل المختلفة.
أو
لا يتم اجراء استبانات لقياس مدى رضا الطلبة حول جوانب العمل المختلفة.', NULL, ARRAY[76]),
  ('1.5.2', 3, 5, 'يظهر تحليل نتائج استبانات قياس الرضا أن متوسط رضا الطلبة يتراوح بين (90% - 100%). (بشرط ألّا تقل نسبة المشاركة عن 70% من الطلبة)', NULL, ARRAY[77]),
  ('1.5.2', 3, 4, 'يظهر تحليل نتائج استبانات قياس الرضا أن متوسط رضا الطلبة يتراوح بين (80% - 89%). (بشرط ألّا تقل نسبة المشاركة عن 70% من الطلبة)', NULL, ARRAY[77]),
  ('1.5.2', 3, 3, 'يظهر تحليل نتائج استبانات قياس الرضا أن متوسط رضا الطلبة يتراوح بين (70% - 79%). (بشرط ألّا تقل نسبة المشاركة عن 70% من الطلبة)', NULL, ARRAY[77]),
  ('1.5.2', 3, 2, 'يظهر تحليل نتائج استبانات قياس الرضا أن متوسط رضا الطلبة يتراوح بين (60% - 69%).
أو
يظهر تحليل نتائج استبانات قياس الرضا أن متوسط رضا الطلبة يتراوح بين (70% - 100%) ولكن نسبة المشاركة تقل عن 70% من الطلبة', NULL, ARRAY[77]),
  ('1.5.2', 3, 1, 'يظهر تحليل نتائج استبانات قياس الرضا أن متوسط رضا الطلبة أقل من 60%.', NULL, ARRAY[77]),
  ('1.5.2', 4, 5, 'يتم تشكيل مجلس طلابي يضم ممثلين من جميع الصفوف الدراسية، ويقوم بدورٍ فعال جداً في الحياة المدرسية، مما يسهم في تعزيز التواصل بفعالية عالية بين الطلبة والإدارة.', NULL, ARRAY[77]),
  ('1.5.2', 4, 4, 'يتم تشكيل مجلس طلابي يضم ممثلين من الغالبية العظمى من الصفوف الدراسية، ويقوم بدورٍ فعال في الحياة المدرسية، مما يسهم في تعزيز التواصل بفعالية بين الطلبة والإدارة.', NULL, ARRAY[77]),
  ('1.5.2', 4, 3, 'يتم تشكيل مجلس طلابي يضم ممثلين من معظم الصفوف الدراسية، ويقوم بدورٍ مناسب في الحياة المدرسية، مما يسهم في تعزيز التواصل بين الطلبة والإدارة.', NULL, ARRAY[77]),
  ('1.5.2', 4, 2, 'يتم تشكيل مجلس طلابي يضم ممثلين من بعض الصفوف الدراسية، ويقوم بدورٍ محدود في الحياة المدرسية.
أو
يتم تشكيل مجلس طلابي يضم ممثلين للطلبة من مختلف الصفوف الدراسية، إلا أنه يقوم بدورٍ محدود في الحياة المدرسية.', NULL, ARRAY[77]),
  ('1.5.2', 4, 1, 'يتم تشكيل مجلس طلابي يضم ممثلين من قلة من الصفوف الدراسية، ويقوم المجلس بدورٍ محدود جداً في الحياة المدرسية / ليس له دور على الإطلاق في المدرسة.
أو
لا يوجد مجلس طلابي في المدرسة.', NULL, ARRAY[77]),
  ('1.5.3', 1, 5, 'يتم التواصل مع أولياء الأمور والاستجابة التامة لمقترحاتهم وشكواهم بآلية وطرق فعالة جداً ومتنوعة ومنتظمة، لتعريفهم بكافة أمور ومستجدات المدرسة، بما يضمن توفير معرفة شاملة وفهم واضح لجميع أولياء الأمور عن جوانب العمل المدرسي، وتعزيز التفاعل الإيجابي بين المدرسة والأسرة.', NULL, ARRAY[77,78]),
  ('1.5.3', 1, 4, 'يتم التواصل مع أولياء الأمور والاستجابة لمقترحاتهم وشكواهم بآلية وطرق فعالة ومتنوعة ومنتظمة، لتعريفهم بمختلف أمور ومستجدات المدرسة، بما يضمن توفير معرفة شاملة وفهم للغالبية العظمى من أولياء الأمور عن جوانب العمل المدرسي والاستجابة لشكواهم.', NULL, ARRAY[77,78]),
  ('1.5.3', 1, 3, 'يتم التواصل مع أولياء الأمور والاستجابة لمقترحاتهم وشكواهم بآلية وطرق مناسبة، لتعريفهم بأمور ومستجدات المدرسة، بما يضمن توفير معرفة وفهم لمعظم أولياء الأمور عن جوانب العمل المدرسي.', NULL, ARRAY[77,78]),
  ('1.5.3', 1, 2, 'يتم التواصل مع أولياء الأمور والاستجابة لمقترحاتهم وشكواهم بطرق محدودة لتعريفهم بأمور ومستجدات المدرسة، مما أدى إلى معرفة بعض أولياء الأمور عن جوانب العمل المدرسي.
أو
يتم التواصل مع أولياء الأمور بطرق متنوعة لتعريفهم بأمور ومستجدات المدرسة، إلا أن ذلك أدى إلى معرفة محدودة لدى أولياء الأمور عن جوانب العمل المدرسي.', NULL, ARRAY[77,78]),
  ('1.5.3', 1, 1, 'يتم التواصل مع أولياء الأمور بطرق محدودة جداً لتعريفهم بأمور ومستجدات المدرسة، مما أدى إلى معرفة قلة من أولياء الأمور عن جوانب العمل المدرسي.', NULL, ARRAY[77,78]),
  ('1.5.3', 2, 5, 'تنفيذ أنشطة وبرامج متنوعة ومنتظمة ومستمرة تهدف إلى جذب وتعزيز مشاركة أولياء الأمور في الحياة المدرسية، وإشراكهم في العملية التعليمية، مما أدى إلى مشاركة جميع أولياء الأمور، وساهم بشكلٍ فعال جداً في دعم تعلم أبنائهم وتعزيز أدائهم.', NULL, ARRAY[78,79]),
  ('1.5.3', 2, 4, 'تنفيذ أنشطة وبرامج متنوعة ومنتظمة تهدف إلى جذب وتعزيز مشاركة أولياء الأمور في الحياة المدرسية، وإشراكهم في العملية التعليمية، مما أدى إلى مشاركة الغالبية العظمى من أولياء الأمور، وساهم بشكلٍ فعال في دعم تعلم أبنائهم وتعزيز أدائهم.', NULL, ARRAY[78,79]),
  ('1.5.3', 2, 3, 'تنفيذ أنشطة وبرامج تهدف إلى جذب وتعزيز مشاركة أولياء الأمور في الحياة المدرسية، وإشراكهم في العملية التعليمية، مما أدى إلى مشاركة معظم أولياء الأمور، وساهم بشكلٍ مناسب في دعم تعلم أبنائهم وتعزيز أدائهم.', NULL, ARRAY[78,79]),
  ('1.5.3', 2, 2, 'تنفيذ أنشطة وبرامج محدودة لجذب وتعزيز مشاركة أولياء الأمور في الحياة المدرسية، مما أدى مشاركة بعض أولياء الأمور في العملية التعليمية ودعم أبنائهم.
أو
تنفيذ أنشطة وبرامج تهدف إلى جذب وتعزيز مشاركة أولياء الأمور في الحياة المدرسية، وإشراكهم في العملية التعليمية، إلا أن المشاركة كانت محدودة واقتصرت على بعض أولياء الأمور.
أو
يشارك أولياء الأمور في الحياة المدرسية والعملية التعليمية، إلا أنه يتم تنفيذ أنشطة وبرامج محدودة لتعزيز مشاركتهم بما يسهم في دعم تعلم أبنائهم وتعزيز أدائهم.', NULL, ARRAY[78,79]),
  ('1.5.3', 2, 1, 'تنفيذ أنشطة وبرامج محدودة جداً لجذب وتعزيز مشاركة أولياء الأمور في الحياة المدرسية، مما أدى مشاركة قلة من أولياء الأمور في العملية التعليمية ودعم أبنائهم.
أو
لا يتم تنفيذ أنشطة وبرامج لجذب وتعزيز مشاركة أولياء الأمور في الحياة المدرسية، وإشراكهم في العملية التعليمية.', NULL, ARRAY[78,79]),
  ('1.5.3', 3, 5, 'يتم قياس مدى رضا أولياء الأمور عن جودة التعليم وكافة الخدمات المدرسية من خلال استبانات منتظمة وشاملة وذات جودة عالية، وتتراوح نسبة مشاركة أولياء الأمور واستجابتهم لهذه الاستبانات بين (80% - 100%).', NULL, ARRAY[79,80]),
  ('1.5.3', 3, 4, 'يتم قياس مدى رضا أولياء الأمور عن جودة التعليم وكافة الخدمات المدرسية من خلال استبانات منتظمة وشاملة وذات جودة، وتتراوح نسبة مشاركة أولياء الأمور واستجابتهم لهذه الاستبانات بين (70% - 79%).', NULL, ARRAY[79,80]),
  ('1.5.3', 3, 3, 'يتم قياس مدى رضا أولياء الأمور عن جودة التعليم وكافة الخدمات المدرسية من خلال استبانات مناسبة منتظمة وشاملة، وتتراوح نسبة مشاركة أولياء الأمور واستجابتهم لهذه الاستبانات بين (60% - 69%).', NULL, ARRAY[79,80]),
  ('1.5.3', 3, 2, 'يتم قياس مدى رضا أولياء الأمور عن جودة التعليم والخدمات المدرسية من خلال استبانات منتظمة وشاملة، وتتراوح نسبة مشاركة أولياء الأمور واستجابتهم لهذه الاستبانات بين (50% - 59%).
أو
يشارك أولياء الأمور في الاستجابة لاستبانات لقياس مدى الرضا، لكن الاستبانات تشمل بعض جوانب العمل المدرسي، وليست ذات جودة.', NULL, ARRAY[79,80]),
  ('1.5.3', 3, 1, 'يتم قياس مدى رضا أولياء الأمور عن جودة التعليم والخدمات المدرسية من خلال استبانات منتظمة، إلا أن نسبة مشاركة أولياء الأمور واستجابتهم لهذه الاستبانات أقل من (50%).
أو
لا يتم قياس مدى رضا أولياء الأمور عن جودة التعليم والخدمات المدرسية.', NULL, ARRAY[79,80]),
  ('1.5.3', 4, 5, 'يُظهر تحليل نتائج استبانات قياس الرضا، أن متوسط رضا أولياء الأمور عن جودة التعليم والخدمات المدرسية يتراوح بين (90% - 100%). (بشرط ألّا تقل نسبة المشاركة عن 70% من أولياء الأمور).', NULL, ARRAY[80]),
  ('1.5.3', 4, 4, 'يُظهر تحليل نتائج استبانات قياس الرضا، أن متوسط رضا أولياء الأمور عن جودة التعليم والخدمات المدرسية يتراوح بين (80% - 89%). (بشرط ألّا تقل نسبة المشاركة عن 70% من أولياء الأمور).', NULL, ARRAY[80]),
  ('1.5.3', 4, 3, 'يُظهر تحليل نتائج استبانات قياس الرضا، أن متوسط رضا أولياء الأمور عن جودة التعليم والخدمات المدرسية يتراوح بين (70% - 79%). (بشرط ألّا تقل نسبة المشاركة عن 70% من أولياء الأمور).', NULL, ARRAY[80]),
  ('1.5.3', 4, 2, 'يُظهر تحليل نتائج استبانات قياس الرضا، أن متوسط رضا أولياء الأمور عن جودة التعليم والخدمات المدرسية يتراوح بين (60% - 69%). (بشرط ألّا تقل نسبة المشاركة عن 70% من أولياء الأمور).
أو
يُظهر تحليل نتائج استبانات قياس الرضا أن متوسط الرضا يتراوح بين (70% - 100%) ولكن نسبة المشاركة تقل عن 70% من أولياء الأمور.', NULL, ARRAY[80]),
  ('1.5.3', 4, 1, 'يُظهر تحليل نتائج استبانات قياس الرضا، أن متوسط رضا أولياء الأمور عن جودة التعليم والخدمات المدرسية أقل من (60%).', NULL, ARRAY[80]),
  ('1.5.4', 1, 5, 'تقوم المدرسة بالتواصل مع مؤسسات المجتمع من خلال آلية وطرق تواصل متنوعة ومنتظمة، وتستفيد من مختلف مؤسسات المجتمع في تلبية جميع احتياجات الطلبة، ودعم تعلمهم بشكلٍ فعال جداً ومستمر.', NULL, ARRAY[80,81]),
  ('1.5.4', 1, 4, 'تقوم المدرسة بالتواصل مع مؤسسات المجتمع من خلال آلية وطرق تواصل منتظمة، وتستفيد من مؤسسات المجتمع في تلبية الغالبية العظمى من احتياجات الطلبة، ودعم تعلمهم بشكلٍ فعال ومستمر.', NULL, ARRAY[80,81]),
  ('1.5.4', 1, 3, 'تقوم المدرسة بالتواصل مع مؤسسات المجتمع من خلال آلية وطرق تواصل منتظمة، وتستفيد من مؤسسات المجتمع في تلبية معظم احتياجات الطلبة، ودعم تعلمهم بشكلٍ مناسب.', NULL, ARRAY[80,81]),
  ('1.5.4', 1, 2, 'تقوم المدرسة بالتواصل مع مؤسسات المجتمع من خلال طرق تواصل محدودة، وتستفيد منها في تلبية بعض احتياجات الطلبة ودعم تعلمهم.', NULL, ARRAY[80,81]),
  ('1.5.4', 1, 1, 'تتواصل المدرسة مع مؤسسات المجتمع من خلال طرق تواصل محدودة جداً، وتستفيد منها في تلبية قلة من احتياجات الطلبة.
أو
لا تتواصل المدرسة مع مؤسسات المجتمع.', NULL, ARRAY[80,81]),
  ('2.1.1', 1, 5, 'يتوافق المنهج الدراسي بشكلٍ كامل مع رؤية المدرسة ورسالتها وأهدافها، ويعزز تنمية الكفاءات المحلية والعالمية مع مراعاة السياق الثقافي المحلي، كما أن المصادر التعليمية ملائمة للمنهج الدراسي وتدعم تحقيق أهدافه، وتتوافق المعايير المطبقة مع التوقعات التعليمية للمرحلة العمرية في جميع المواد الدراسية.', NULL, ARRAY[97]),
  ('2.1.1', 1, 4, 'يتوافق المنهج الدراسي مع رؤية المدرسة ورسالتها وأهدافها، ويعزز تنمية الكفاءات المحلية والعالمية مع مراعاة السياق الثقافي المحلي، كما أن المصادر التعليمية ملائمة للمنهج الدراسي وتدعم تحقيق أهدافه، وتتوافق المعايير المطبقة مع التوقعات التعليمية للمرحلة العمرية في الغالبية العظمى من المواد الدراسية.', NULL, ARRAY[97]),
  ('2.1.1', 1, 3, 'يتوافق المنهج الدراسي مع رؤية المدرسة ورسالتها وأهدافها، ويعزز تنمية الكفاءات المحلية والعالمية مع مراعاة السياق الثقافي المحلي، كما أن المصادر التعليمية ملائمة للمنهج الدراسي وتدعم تحقيق أهدافه، وتتوافق المعايير المطبقة مع التوقعات التعليمية للمرحلة العمرية في معظم المواد الدراسية.', NULL, ARRAY[97]),
  ('2.1.1', 1, 2, 'يتوافق المنهج الدراسي مع رؤية المدرسة ورسالتها وأهدافها، كما أن المصادر التعليمية ملائمة للمنهج الدراسي، إلا أن المعايير المطبقة تتوافق مع التوقعات التعليمية للمرحلة العمرية في بعض المواد الدراسية.', NULL, ARRAY[97]),
  ('2.1.1', 1, 1, 'يتوافق المنهج الدراسي مع رؤية المدرسة ورسالتها وأهدافها، كما أن المصادر التعليمية ملائمة للمنهج الدراسي، إلا أن المعايير المطبقة تتوافق مع التوقعات التعليمية للمرحلة العمرية في قلة من المواد الدراسية.
أو
لا يتوافق المنهج الدراسي مع رؤية المدرسة ورسالتها وأهدافها.
و/أو
المصادر التعليمية غير ملائمة للمنهج الدراسي.
و/أو
لا تتوافق المعايير المطبقة في المواد الدراسية مع التوقعات التعليمية للمرحلة العمرية.', NULL, ARRAY[97]),
  ('2.1.1', 2, 5, 'يتضمن المنهج الدراسي جميع المجالات التعليمية التي تسهم في تحقيق تنمية متكاملة للطلبة، ويُظهر توازناً واضحاً وشاملًا بين الجوانب المعرفية والمهارية والقيمية في محتوى المنهج ونواتج التعلم.', NULL, ARRAY[98]),
  ('2.1.1', 2, 4, 'يتضمن المنهج الدراسي الغالبية العظمى من المجالات التعليمية التي تسهم في تحقيق تنمية للطلبة، ويُظهر توازناً بين الجوانب المعرفية والمهارية والقيمية في محتوى المنهج ونواتج التعلم.', NULL, ARRAY[98]),
  ('2.1.1', 2, 3, 'يتضمن المنهج الدراسي معظم المجالات التعليمية التي تسهم في تحقيق تنمية للطلبة، ويُظهر توازناً بين الجوانب المعرفية والمهارية والقيمية.', NULL, ARRAY[98]),
  ('2.1.1', 2, 2, 'يتضمن المنهج الدراسي بعض المجالات التعليمية، مما أثر على تحقيق تنمية متكاملة للطلبة.
أو
يتضمن المنهج الدراسي مجالات تعليمية متنوعة، إلا أنه يراعي التوازن بين الجوانب المعرفية والمهارية والقيمية بشكلٍ محدود، مما أثر على مراعاة احتياجات الطلبة.', NULL, ARRAY[98]),
  ('2.1.1', 2, 1, 'يتضمن المنهج الدراسي قلة من المجالات التعليمية، و/ أو لا يحقق توازناً بين الجوانب المعرفية والمهارية والقيمية، مما أدى إلى مراعاة احتياجات الطلبة بشكلٍ محدود جداً، وأثر بشكلٍ سلبي على تحقيق تنمية متكاملة للطلبة.', NULL, ARRAY[98]),
  ('2.1.2', 1, 5, 'إعداد خطط (سنوية/فصلية) ذات جودة عالية، وشاملة وواضحة ومفصلة لتطبيق المنهج، بما يتوافق مع متطلبات المنهج واحتياجات الطلبة والتوقعات المطلوبة في جميع المواد الدراسية، مع مراعاة التكامل في التخطيط بين المواد الدراسية المختلفة عند التخطيط للمنهج.', NULL, ARRAY[98]),
  ('2.1.2', 1, 4, 'إعداد خطط (سنوية/فصلية) ذات جودة، وشاملة وواضحة لتطبيق المنهج، بما يتوافق مع متطلبات المنهج واحتياجات الطلبة في الغالبية العظمى من المواد الدراسية، ويتم مراعاة التكامل في التخطيط بين المواد الدراسية عند التخطيط للمنهج.', NULL, ARRAY[98]),
  ('2.1.2', 1, 3, 'إعداد خطط (سنوية/فصلية) مناسبة لتطبيق المنهج، بما يتوافق مع متطلبات المنهج واحتياجات الطلبة في معظم المواد الدراسية، ويتم مراعاة التكامل بين المواد الدراسية عند التخطيط للمنهج.', NULL, ARRAY[98]),
  ('2.1.2', 1, 2, 'إعداد خطط (سنوية/فصلية) ذات جودة محدودة لتطبيق المنهج، وبما يتوافق مع متطلبات المنهج واحتياجات الطلبة في بعض المواد الدراسية.
أو
يتم إعداد خطط مناسبة (سنوية/فصلية) لتطبيق المنهج في المواد الدراسية المختلفة، لكن يتم مراعاة التكامل بشكلٍ محدود بين المواد الدراسية عند التخطيط للمنهج.', NULL, ARRAY[98]),
  ('2.1.2', 1, 1, 'يتم إعداد خطط ذات جودة محدودة جداً (سنوية/فصلية) لتطبيق المنهج، وبما يتوافق مع متطلبات المنهج واحتياجات الطلبة في قلة من المواد الدراسية.', NULL, ARRAY[98]),
  ('2.1.2', 2, 5, 'جميع خطط الدروس الأسبوعية / اليومية ذات جودة وشاملة لكافة العناصر الأساسية وتتوافق مع أهداف الدروس واحتياجات الطلبة المختلفة، مع الالتزام بتنفيذها بشكل يسهم في تحقيق أهداف التعلم بشكلٍ فعال جداً', NULL, ARRAY[99]),
  ('2.1.2', 2, 4, 'الغالبية العظمى من خطط الدروس الأسبوعية / اليومية ذات جودة وشاملة لكافة العناصر الأساسية، وتتوافق مع أهداف الدروس واحتياجات الطلبة المختلفة، مع الالتزام بتنفيذها بشكل يسهم في تحقيق أهداف التعلم بشكلٍ فعال.', NULL, ARRAY[99]),
  ('2.1.2', 2, 3, 'معظم خطط الدروس الأسبوعية / اليومية ذات جودة وشاملة لكافة العناصر الأساسية، وتتوافق مع أهداف الدروس واحتياجات الطلبة، مع الالتزام بتنفيذها بشكل يسهم في تحقيق أهداف التعلم بشكلٍ مناسب.', NULL, ARRAY[99]),
  ('2.1.2', 2, 2, 'بعض خطط الدروس الأسبوعية / اليومية ذات جودة وشاملة للعناصر الأساسية ومتوافقة مع أهداف الدروس واحتياجات الطلبة، ويتم الالتزام بتنفيذها بشكلٍ محدود مما يؤثر على تحقيق أهداف التعلم.', NULL, ARRAY[99]),
  ('2.1.2', 2, 1, 'قلة من خطط الدروس الأسبوعية / اليومية شاملة للعناصر الأساسية، ومتوافقة مع أهداف الدروس واحتياجات الطلبة، مما يؤثر سلباً على تحقيق أهداف التعلم.
أو
لا يتم إعداد خطط الدروس الأسبوعية / اليومية.', NULL, ARRAY[99]),
  ('2.1.3', 1, 5, 'يتم إعداد وتنفيذ خطة شاملة للبرامج والأنشطة المصاحبة للمنهج، تتوافق مع أهداف المنهج وتدعم تحقيقها، وتتناسب مع احتياجات الطلبة وميولهم وتعزز تطوير مهاراتهم، ويتم مشاركة جميع الطلبة في تلك الأنشطة.', NULL, ARRAY[99,100]),
  ('2.1.3', 1, 4, 'يتم إعداد وتنفيذ خطة للبرامج والأنشطة المصاحبة للمنهج، تتوافق مع أهداف المنهج وتدعم تحقيقها، وتتناسب مع احتياجات الطلبة وتعزز تطوير مهاراتهم، ويتم مشاركة الغالبية العظمى من الطلبة في تلك الأنشطة.', NULL, ARRAY[99,100]),
  ('2.1.3', 1, 3, 'يتم إعداد وتنفيذ خطة للبرامج والأنشطة المصاحبة للمنهج، تتوافق مع أهداف المنهج، وتتناسب مع احتياجات الطلبة وميولهم وتعزز تطوير مهاراتهم، ويتم مشاركة معظم الطلبة في هذه الأنشطة.', NULL, ARRAY[99,100]),
  ('2.1.3', 1, 2, 'يتم إعداد وتنفيذ خطة للبرامج والأنشطة المصاحبة للمنهج، تتوافق مع أهداف المنهج، وتتناسب مع احتياجات الطلبة، لكن يتم مشاركة بعض الطلبة في هذه الأنشطة.
أو
يتم إعداد وتنفيذ خطة للبرامج والأنشطة المصاحبة للمنهج، وتتم مشاركة الطلبة في هذه الأنشطة، إلا أن الخطة تتوافق مع أهداف المنهج وتتناسب مع احتياجات الطلبة بشكلٍ محدود.', NULL, ARRAY[99,100]),
  ('2.1.3', 1, 1, 'يتم إعداد وتنفيذ خطة للبرامج والأنشطة المصاحبة للمنهج، تتوافق مع أهداف المنهج، لكن يتم مشاركة قلة من الطلبة في هذه الأنشطة.
أو
يتم إعداد وتنفيذ خطة للبرامج والأنشطة المصاحبة للمنهج، وتتم مشاركة الطلبة، إلا أن الخطة تتوافق مع أهداف المنهج بشكلٍ محدود جداً ولا تتناسب مع احتياجات الطلبة.
أو
لا يتم إعداد أو تنفيذ خطة للبرامج والأنشطة المصاحبة للمنهج.', NULL, ARRAY[99,100]),
  ('2.1.4', 1, 5, 'يتم تطبيق آلية وإجراءات منتظمة وواضحة لمراجعة المناهج والخطط التعليمية في جميع المواد الدراسية، وتتم الاستفادة من نتائج عملية المراجعة بشكلٍ فعال جداً لإجراء تعديلات هادفة على الخطط التعليمية والأنشطة المصاحبة للمناهج بما يتناسب مع احتياجات الطلبة، ويسهم في تحسين مخرجات العملية التعليمية.', NULL, ARRAY[100]),
  ('2.1.4', 1, 4, 'يتم تطبيق آلية وإجراءات منتظمة لمراجعة المناهج والخطط التعليمية في الغالبية العظمى من المواد الدراسية، وتتم الاستفادة من نتائج عملية المراجعة بشكلٍ فعال لإجراء تعديلات على الخطط التعليمية والأنشطة المصاحبة للمناهج بما يتناسب مع احتياجات الطلبة، ويسهم في تحسين مخرجات العملية التعليمية.', NULL, ARRAY[100]),
  ('2.1.4', 1, 3, 'يتم تطبيق آلية وإجراءات منتظمة لمراجعة المناهج والخطط التعليمية في معظم المواد الدراسية، وتتم الاستفادة من نتائج عملية المراجعة بشكلٍ مناسب لإجراء تعديلات على الخطط التعليمية والأنشطة المصاحبة للمناهج بما يتناسب مع احتياجات الطلبة.', NULL, ARRAY[100]),
  ('2.1.4', 1, 2, 'يتم تطبيق إجراءات منتظمة لمراجعة المناهج والخطط التعليمية في بعض المواد الدراسية، وتتم الاستفادة من نتائج عملية المراجعة بشكلٍ محدود لإجراء تعديلات على الخطط التعليمية والأنشطة المصاحبة للمناهج.
أو
يتم تطبيق إجراءات محدودة لمراجعة المناهج والخطط التعليمية في المواد الدراسية المختلفة.', NULL, ARRAY[100]),
  ('2.1.4', 1, 1, 'يتم تطبيق إجراءات لمراجعة المناهج والخطط التعليمية في قلة من المواد الدراسية، وتتم الاستفادة من نتائج عملية المراجعة بشكلٍ محدود جداً لإجراء تعديلات على الخطط التعليمية والأنشطة المصاحبة للمناهج.
أو
لا يتم مراجعة المناهج والخطط التعليمية.', NULL, ARRAY[100]),
  ('2.2.1', 1, 5, 'يتم تطبيق استراتيجيات وطرق تدريس متنوعة، ومتكاملة وملائمة للمرحلة العمرية، وتتمركز حول الطلبة، وتتناسب مع طبيعة المحتوى الدراسي وأهداف الدروس في جميع المواد الدراسية، مما يسهم بشكلٍ فعال جداً في دعم تعلم الطلبة.', NULL, ARRAY[101]),
  ('2.2.1', 1, 4, 'يتم تطبيق استراتيجيات وطرق تدريس متنوعة، ومتكاملة وملائمة للمرحلة العمرية، وتتمركز حول الطلبة، وتتناسب مع طبيعة المحتوى الدراسي وأهداف الدروس في الغالبية العظمى من المواد الدراسية، مما يسهم بشكلٍ فعّال في دعم تعلم الطلبة.', NULL, ARRAY[101]),
  ('2.2.1', 1, 3, 'يتم تطبيق استراتيجيات وطرق تدريس متنوعة، وملائمة للمرحلة العمرية، وتتمركز حول الطلبة، وتتناسب مع طبيعة المحتوى الدراسي وأهداف الدروس في معظم المواد الدراسية، مما يسهم بشكلٍ مناسب في دعم تعلم الطلبة.', NULL, ARRAY[101]),
  ('2.2.1', 1, 2, 'يتم تطبيق استراتيجيات وطرق تدريس متنوعة وتتمركز حول الطلبة في بعض المواد الدراسية، مما يسهم بشكلٍ محدود في دعم تعلم الطلبة.
أو
يتم تطبيق استراتيجيات وطرق تدريس متنوعة، إلا أنها تتلاءم مع المرحلة العمرية و/أو تتناسب مع طبيعة المحتوى الدراسي وأهداف الدروس في بعض المواد الدراسية، مما يسهم بشكلٍ محدود في دعم تعلم الطلبة.', NULL, ARRAY[101]),
  ('2.2.1', 1, 1, 'يتم تطبيق استراتيجيات وطرق تدريس متنوعة في قلة من المواد الدراسية، مما يسهم بشكلٍ محدود جداً في دعم تعلم الطلبة.', NULL, ARRAY[101]),
  ('2.2.2', 1, 5, 'يتم تطبيق استراتيجيات التمايز بشكلٍ فعال جداً ومستمر، وتوظيف موارد ووسائل تعليمية متنوعة تدعم التمايز داخل البيئة التعليمية، ويتم تقديم الدعم للطلبة بما يتناسب مع مستوياتهم وقدراتهم وأنماطهم التعليمية في جميع المواد الدراسية.', NULL, ARRAY[101,102]),
  ('2.2.2', 1, 4, 'يتم تطبيق استراتيجيات التمايز بشكلٍ فعال، وتوظيف موارد ووسائل تعليمية متنوعة تدعم التمايز داخل البيئة التعليمية، ويتم تقديم الدعم للطلبة بما يتناسب مع مستوياتهم وأنماطهم التعليمية في الغالبية العظمى من المواد الدراسية.', NULL, ARRAY[101,102]),
  ('2.2.2', 1, 3, 'يتم تطبيق استراتيجيات التمايز بشكلٍ مناسب، وتوظيف موارد ووسائل تعليمية متنوعة تدعم التمايز داخل البيئة التعليمية، ويتم تقديم الدعم للطلبة بما يتناسب مع مستوياتهم وأنماطهم التعليمية في معظم المواد الدراسية.', NULL, ARRAY[101,102]),
  ('2.2.2', 1, 2, 'يتم تطبيق استراتيجيات التمايز، وتقديم الدعم للطلبة بما يتناسب مع مستوياتهم في بعض المواد الدراسية.', NULL, ARRAY[101,102]),
  ('2.2.2', 1, 1, 'يتم تطبيق استراتيجيات التمايز التعليمية، وتقديم الدعم للطلبة بما يتناسب مع مستوياتهم في قلة من المواد الدراسية.
أو
لا يتم تطبيق التعليم المتمايز لمراعاة الفروق الفردية بين الطلبة.', NULL, ARRAY[101,102]),
  ('2.2.3', 1, 5, 'يتم تنمية مهارات التفكير لدى الطلبة بشكلٍ مستمر في جميع المواد الدراسية، ويُظهر الطلبة قدرة عالية على تطبيق مهارات التفكير، مما يسهم بشكلٍ فعال جداً في تعزيز تعلمهم.', NULL, ARRAY[102]),
  ('2.2.3', 1, 4, 'يتم تنمية مهارات التفكير لدى الطلبة في الغالبية العظمى من المواد الدراسية، ويُظهر الطلبة قدرة على تطبيق مهارات التفكير، مما يسهم بشكلٍ فعال في تعزيز تعلمهم.', NULL, ARRAY[102]),
  ('2.2.3', 1, 3, 'يتم تنمية مهارات التفكير لدى الطلبة في معظم المواد الدراسية، ويُظهر الطلبة قدرة مناسبة على تطبيق مهارات التفكير، مما يسهم بشكلٍ مناسب في تعزيز تعلمهم.', NULL, ARRAY[102]),
  ('2.2.3', 1, 2, 'يتم تنمية مهارات التفكير لدى الطلبة في بعض المواد الدراسية، ويُظهر الطلبة قدرة محدودة على تطبيق مهارات التفكير.
أو
يتم تنمية مهارات التفكير لدى الطلبة في المواد الدراسية المختلفة، إلا أن قدرة الطلبة على تطبيق هذه المهارات محدودة.', NULL, ARRAY[102]),
  ('2.2.3', 1, 1, 'يتم تنمية مهارات التفكير لدى الطلبة في قلة من المواد الدراسية، و/أو يُظهر الطلبة قدرة محدودة جداً على تطبيق مهارات التفكير.', NULL, ARRAY[102]),
  ('2.2.4', 1, 5, 'يتم تعزيز التعلم المستقل وتحمل المسؤولية عن التعلم لدى الطلبة بشكلٍ مستمر وفعال جداً، ويُظهر الطلبة قدرة عالية على إدارة تعلمهم، واتخاذ المبادرة، واستخدام الموارد المتاحة لتحقيق أهدافهم التعليمية في جميع المواد الدراسية.', NULL, ARRAY[102]),
  ('2.2.4', 1, 4, 'يتم تعزيز التعلم المستقل وتحمل المسؤولية عن التعلم لدى الطلبة بشكلٍ فعال، ويُظهر الطلبة قدرة على إدارة تعلمهم، واتخاذ المبادرة، واستخدام الموارد المتاحة لتحقيق أهدافهم التعليمية في الغالبية العظمى من المواد الدراسية.', NULL, ARRAY[102]),
  ('2.2.4', 1, 3, 'يتم تعزيز التعلم المستقل وتحمل المسؤولية عن التعلم لدى الطلبة بشكلٍ مناسب، ويُظهر الطلبة قدرة على إدارة تعلمهم، واستخدام الموارد المتاحة لتحقيق أهدافهم التعليمية في معظم المواد الدراسية.', NULL, ARRAY[102]),
  ('2.2.4', 1, 2, 'يتم تعزيز التعلم المستقل وتحمل المسؤولية عن التعلم لدى الطلبة بشكلٍ محدود، حيث يُظهر الطلبة قدرة على التعلم المستقل وإدارة تعلمهم في بعض المواد الدراسية.', NULL, ARRAY[102]),
  ('2.2.4', 1, 1, 'يتم تعزيز التعلم المستقل وتحمل المسؤولية عن التعلم لدى الطلبة بشكلٍ محدود جداً، حيث يُظهر الطلبة قدرة على التعلم المستقل وإدارة تعلمهم في قلة من المواد الدراسية.', NULL, ARRAY[102]),
  ('2.2.5', 1, 5, 'تطبيق أساليب وأنشطة تعليمية متنوعة ومحفزة تشجع الطلبة على المشاركة النشطة وتعزز تفاعلهم بشكلٍ مستمر، ويتم تقديم تحديات تعليمية تتناسب مع مستوياتهم وقدراتهم، وتوظيف أساليب تعزيز متنوعة بانتظام لتحفيز الطلبة على المشاركة في العملية التعليمية، مما يسهم في مشاركة جميع الطلبة ورفع دافعيتهم نحو التعلم ضمن بيئة تعليمية تفاعلية ومشجعة.', NULL, ARRAY[102,103]),
  ('2.2.5', 1, 4, 'تطبيق أساليب وأنشطة تعليمية متنوعة تشجع الطلبة على المشاركة وتعزز تفاعلهم، ويتم تقديم تحديات تعليمية تتناسب مع مستوياتهم وقدراتهم، وتوظيف أساليب تعزيز متنوعة بانتظام لتحفيز الطلبة على المشاركة في العملية التعليمية، مما يسهم في مشاركة الغالبية العظمى من الطلبة ورفع دافعيتهم نحو التعلم.', NULL, ARRAY[102,103]),
  ('2.2.5', 1, 3, 'تطبيق أساليب وأنشطة تعليمية تشجع الطلبة على المشاركة النشطة وتعزز تفاعلهم، وتوظيف أساليب تعزيز متنوعة لتحفيز الطلبة على المشاركة في العملية التعليمية، مما يسهم في مشاركة معظم الطلبة ورفع دافعيتهم نحو التعلم.', NULL, ARRAY[102,103]),
  ('2.2.5', 1, 2, 'تطبيق أساليب وأنشطة تعليمية محدودة لتشجيع الطلبة على المشاركة وتعزيز تفاعلهم، مع توظيف أساليب التعزيز بشكلٍ غير منتظم، مما أدى إلى مشاركة بعض الطلبة، وأثر على دافعيتهم نحو التعلم.
أو
تطبيق أساليب وأنشطة تعليمية لتشجيع الطلبة على المشاركة وتعزيز تفاعلهم، مع توظيف أساليب التعزيز، إلا أن ذلك أسهم بشكلٍ محدود في تعزيز مشاركة الطلبة ورفع دافعيتهم نحو التعلم.', NULL, ARRAY[102,103]),
  ('2.2.5', 1, 1, 'تطبيق أساليب وأنشطة تعليمية محدودة جداً لتشجيع الطلبة على المشاركة، مع توظيف أساليب التعزيز بشكلٍ غير منتظم، مما أدى إلى مشاركة قلة من الطلبة، وأثر سلباً على دافعيتهم نحو التعلم.', NULL, ARRAY[102,103]),
  ('2.2.6', 1, 5, 'يتم توظيف طرق وأدوات تقييم متنوعة بشكلٍ مستمر، وتتناسب مع أهداف التعلم والمحتوى الدراسي ومستويات الطلبة واحتياجاتهم في جميع المواد الدراسية، مما يسهم في قياس تقدم تعلم الطلبة ومدى تحقيق أهداف الدروس بشكلٍ فعال جداً.', NULL, ARRAY[103,104]),
  ('2.2.6', 1, 4, 'يتم توظيف طرق وأدوات تقييم متنوعة وبشكلٍ مستمر، وتتناسب مع أهداف التعلم والمحتوى الدراسي ومستويات الطلبة واحتياجاتهم التعليمية في الغالبية العظمى من المواد الدراسية، مما يسهم في قياس تقدم تعلم الطلبة ومدى تحقيق أهداف الدروس بشكلٍ فعال.', NULL, ARRAY[103,104]),
  ('2.2.6', 1, 3, 'يتم توظيف طرق وأدوات تقييم متنوعة وبشكلٍ مستمر، وتتناسب مع أهداف التعلم والمحتوى الدراسي ومستويات الطلبة في معظم المواد الدراسية، مما يسهم في قياس تقدم تعلم الطلبة ومدى تحقيق أهداف الدروس بشكلٍ مناسب.', NULL, ARRAY[103,104]),
  ('2.2.6', 1, 2, 'يتم توظيف طرق وأدوات تقييم متنوعة، وتتناسب مع أهداف التعلم ومستويات الطلبة في بعض المواد الدراسية، مما يؤدي إلى قياس تقدم تعلم الطلبة ومدى تحقيق أهداف الدروس بشكلٍ محدود.
أو
يتم توظيف طرق وأدوات تقييم محدودة لقياس وتقييم تقدم تعلم الطلبة في المواد الدراسية المختلفة، مما أثر على قياس تقدم الطلبة بدقة وفاعلية.', NULL, ARRAY[103,104]),
  ('2.2.6', 1, 1, 'يتم توظيف طرق وأدوات تقييم تتناسب مع أهداف التعلم في قلة من المواد الدراسية، مما يؤدي لقياس تقدم تعلم الطلبة ومدى تحقيق أهداف الدروس بشكلٍ محدود جداً.', NULL, ARRAY[103,104]),
  ('2.2.6', 2, 5, 'يتم تقديم تغذية راجعة بناءة، متنوعة ودقيقة، ومرتبطة بالأهداف التعليمية بشكلٍ منتظم لجميع الطلبة، مع التركيز على تلبية احتياجاتهم الفردية، مما يسهم في تحسين أدائهم وتعزيز تعلمهم، وتطوير مهاراتهم وتحقيق أهداف التعلم بشكلٍ فعال جداً.', NULL, ARRAY[104]),
  ('2.2.6', 2, 4, 'يتم تقديم تغذية راجعة بناءة، متنوعة ودقيقة، ومرتبطة بالأهداف التعليمية بشكلٍ منتظم للغالبية العظمى من الطلبة، مع التركيز على تلبية احتياجاتهم الفردية، مما يسهم في تحسين أدائهم، وتطوير مهاراتهم، وتحقيق أهداف التعلم بشكلٍ فعال.', NULL, ARRAY[104]),
  ('2.2.6', 2, 3, 'يتم تقديم تغذية راجعة بناءة، متنوعة ودقيقة، ومرتبطة بالأهداف التعليمية بشكلٍ منتظم لمعظم الطلبة، مع التركيز على تلبية احتياجاتهم الفردية، مما يسهم في تحسين أدائهم، وتحقيق أهداف التعلم بشكلٍ مناسب.', NULL, ARRAY[104]),
  ('2.2.6', 2, 2, 'يتم تقديم تغذية راجعة متنوعة ودقيقة لبعض الطلبة، بينما تفتقر التغذية الراجعة المقدمة لبقية الطلبة إلى الجودة، مما يؤدي إلى تحسين أدائهم بشكلٍ محدود.
أو
تقديم تغذية راجعة محدودة للطلبة، مما يؤثر على فاعليتها في دعم تعلمهم وتحسين أدائهم.', NULL, ARRAY[104]),
  ('2.2.6', 2, 1, 'يتم تقديم تغذية راجعة متنوعة ودقيقة لقلة من الطلبة، بينما تفتقر التغذية الراجعة المقدمة لبقية الطلبة إلى الجودة، مما يؤدي إلى تحسين أدائهم بشكلٍ محدود جداً.
أو
يتم تقديم تغذية راجعة غير دقيقة وغير واضحة للطلبة.', NULL, ARRAY[104]),
  ('2.2.7', 1, 5, 'يتم دمج استراتيجيات التعلم الرقمي ضمن خطط المنهج الدراسي بشكلٍ فعال جداً، وتوظيف أدوات التعلم الرقمي لتعزيز مشاركة الطلبة في أنشطة التعلم الرقمي في جميع المواد الدراسية.', NULL, ARRAY[104,105]),
  ('2.2.7', 1, 4, 'يتم دمج استراتيجيات التعلم الرقمي ضمن خطط المنهج الدراسي بشكلٍ فعال، ويتم توظيف أدوات التعلم الرقمي لتعزيز مشاركة الطلبة في أنشطة التعلم الرقمي في الغالبية العظمى من المواد الدراسية.', NULL, ARRAY[104,105]),
  ('2.2.7', 1, 3, 'يتم دمج استراتيجيات التعلم الرقمي ضمن خطط المنهج الدراسي بشكلٍ مناسب، ويتم توظيف أدوات التعلم الرقمي لتعزيز مشاركة الطلبة في أنشطة التعلم الرقمي في معظم المواد الدراسية.', NULL, ARRAY[104,105]),
  ('2.2.7', 1, 2, 'يتم دمج استراتيجيات التعلم الرقمي بشكلٍ محدود ضمن خطط المنهج الدراسي، ويتم توظيف أدوات التعلم الرقمي لتعزيز مشاركة الطلبة في أنشطة التعلم الرقمي في بعض المواد الدراسية.', NULL, ARRAY[104,105]),
  ('2.2.7', 1, 1, 'يتم دمج استراتيجيات التعلم الرقمي بشكلٍ محدود جداً ضمن خطط المنهج الدراسي، ويتم توظيف أدوات التعلم الرقمي لتعزيز مشاركة الطلبة في أنشطة التعلم الرقمي في قلة من المواد الدراسية.
أو
لا يتم دمج استراتيجيات التعلم الرقمي ضمن الخطط الدراسية و/أو لا يتم توظيف أدوات التعلم الرقمي لتعزيز مشاركة الطلبة في أنشطة التعلم.', NULL, ARRAY[104,105]),
  ('2.2.7', 2, 5, 'يشارك الطلبة في مشاريع تعلم رقمية في جميع المواد الدراسية، مما يسهم بشكلٍ فعال جداً ومستمر في تعزيز مهاراتهم الرقمية، وتنمية قدراتهم على تطبيق المعرفة في سياقات تعليمية متنوعة بكفاءة عالية.', NULL, ARRAY[105]),
  ('2.2.7', 2, 4, 'يشارك الطلبة في مشاريع تعلم رقمية في الغالبية العظمى من المواد الدراسية، مما يسهم في بشكلٍ فعال ومستمر في تعزيز مهاراتهم الرقمية بكفاءة.', NULL, ARRAY[105]),
  ('2.2.7', 2, 3, 'يشارك الطلبة في مشاريع تعلم رقمية في معظم المواد الدراسية، مما يسهم في تعزيز مهاراتهم الرقمية بشكلٍ مناسب.', NULL, ARRAY[105]),
  ('2.2.7', 2, 2, 'يشارك الطلبة في مشاريع تعلم رقمية في بعض المواد الدراسية، مما يسهم بشكلٍ محدود في تعزيز مهاراتهم الرقمية.', NULL, ARRAY[105]),
  ('2.2.7', 2, 1, 'يشارك الطلبة في مشاريع تعلم رقمية في قلة من المواد الدراسية، مما يسهم بشكلٍ محدود جداً في تعزيز مهاراتهم الرقمية
أو
لا يشارك الطلبة في مشاريع تعلم رقمية.', NULL, ARRAY[105]),
  ('2.2.8', 1, 5, 'يتم إعداد وتنفيذ خطة تعليمية متكاملة لدمج مهارات البحث العلمي ضمن المنهج، وتوفير بيئة تعليمية محفزة وداعمة لتعزيز هذه المهارات، ويشارك الطلبة في مسابقات ومشاريع بحثية متنوعة في جميع المواد الدراسية، مما يسهم في تنمية مهارات البحث العلمي لديهم بشكلٍ فعال جداً', NULL, ARRAY[105,106]),
  ('2.2.8', 1, 4, 'يتم إعداد وتنفيذ خطة تعليمية متكاملة لدمج مهارات البحث العلمي ضمن المنهج الدراسي، وتوفير بيئة تعليمية محفزة وداعمة لتعزيز هذه المهارات، ويشارك الطلبة في مسابقات ومشاريع بحثية متنوعة في الغالبية العظمى من المواد الدراسية، مما يسهم في تنمية مهارات البحث العلمي لديهم بشكلٍ فعال.', NULL, ARRAY[105,106]),
  ('2.2.8', 1, 3, 'يتم إعداد وتنفيذ خطة تعليمية لدمج مهارات البحث العلمي ضمن المنهج الدراسي، وتوفير بيئة تعليمية مناسبة لتعزيز هذه المهارات، ويشارك الطلبة في مسابقات ومشاريع بحثية في معظم المواد الدراسية، مما يسهم في تنمية مهارات البحث العلمي لديهم بشكلٍ مناسب.', NULL, ARRAY[105,106]),
  ('2.2.8', 1, 2, 'يتم إعداد وتنفيذ خطة تعليمية لدمج مهارات البحث العلمي ضمن المنهج الدراسي، ويتم مشاركة الطلبة في مسابقات ومشاريع بحثية في بعض المواد الدراسية، مما يسهم في تنمية مهارات البحث العلمي لديهم بشكلٍ محدود.
أو
يتم توفير بيئة تعليمية لتعزيز المهارات البحثية، إلا أنه لا يوجد خطة أو يوجد خطة ذات جودة محدودة لتنمية المهارات البحثية ويشارك الطلبة في مسابقات ومشاريع بحثية في قلة من المواد الدراسية.', NULL, ARRAY[105,106]),
  ('2.2.8', 1, 1, 'يتم إعداد وتنفيذ خطة تعليمية لدمج مهارات البحث العلمي ضمن المنهج الدراسي، ويتم مشاركة الطلبة في مسابقات ومشاريع بحثية في قلة من المواد الدراسية، مما يسهم في تنمية مهارات البحث العلمي لديهم بشكلٍ محدود جداً.
أو
لا يتم إعداد أو تنفيذ خطة تعليمية لدمج مهارات البحث العلمي ضمن المنهج الدراسي.
أو
لا يشارك الطلبة في مسابقات ومشاريع بحثية.', NULL, ARRAY[105,106]),
  ('2.2.9', 1, 5, 'يتم تطبيق استراتيجيات تعليم متنوعة تحفز الطلبة على التجريب والاستكشاف، وتوفير بيئة تعليمية داعمة ومحفزة على الإبداع والابتكار، مع توفير الفرص للطلبة للتفكير بمرونة، وتقديم أفكار جديدة وتطبيق معرفتهم في مشاريع ريادية عملية في جميع المواد الدراسية، مما يسهم بشكلٍ فعال جداً في تطوير مهارات الإبداع والابتكار لدى الطلبة.', NULL, ARRAY[106,107]),
  ('2.2.9', 1, 4, 'يتم تطبيق استراتيجيات تعليم تحفز الطلبة على التجريب والاستكشاف، وتوفير بيئة تعليمية محفزة على الإبداع والابتكار، مع توفير الفرص للطلبة لتقديم أفكار جديدة وتطبيق معرفتهم في مشاريع ريادية عملية في الغالبية العظمى من المواد الدراسية، مما يسهم بشكلٍ فعال في تطوير مهارات الإبداع والابتكار لدى الطلبة.', NULL, ARRAY[106,107]),
  ('2.2.9', 1, 3, 'يتم تطبيق استراتيجيات تعليم لتحفيز الطلبة على التجريب والاستكشاف، وتوفير بيئة تعليمية محفزة على الإبداع والابتكار، مع توفير الفرص للطلبة لتقديم أفكار جديدة وتطبيق معرفتهم في مشاريع عملية في معظم المواد الدراسية، مما يسهم بشكلٍ مناسب في تطوير مهارات الإبداع والابتكار لدى الطلبة.', NULL, ARRAY[106,107]),
  ('2.2.9', 1, 2, 'يتم تطبيق استراتيجيات تعليم تحفز الطلبة على التجريب والاستكشاف، وتوفير بيئة تعليمية محفزة على الإبداع والابتكار في بعض المواد الدراسية، مما يسهم بشكلٍ محدود في تطوير مهارات الإبداع والابتكار لدى الطلبة.
أو
يتم تطبيق استراتيجيات تعليمية محدودة لتنمية مهارات الإبداع والابتكار لدى الطلبة.', NULL, ARRAY[106,107]),
  ('2.2.9', 1, 1, 'يتم تطبيق استراتيجيات تعليم تحفز الطلبة على التجريب والاستكشاف، وتوفير بيئة تعليمية محفزة على الإبداع والابتكار في قلة من المواد الدراسية، مما يسهم بشكلٍ محدود جداً في تطوير مهارات الإبداع والابتكار لدى الطلبة.
أو
لا يتم تطبيق استراتيجيات تعليم تحفز الطلبة على التجريب والاستكشاف / لا يتم توفير بيئة تعليمية محفزة على الإبداع والابتكار.', NULL, ARRAY[106,107]),
  ('2.3.1', 1, 5, 'يتم تنظيم وترتيب جميع الصفوف والقاعات الدراسية بما يتيح ممارسة الأنشطة التعليمية المختلفة، مما يوفر بيئة تعليمية تعزز التفاعل ومشاركة الطلبة بشكلٍ فعال جداً.', NULL, ARRAY[107]),
  ('2.3.1', 1, 4, 'يتم تنظيم وترتيب الغالبية العظمى من الصفوف والقاعات الدراسية بما يتيح ممارسة الأنشطة التعليمية المختلفة، مما يوفر بيئة تعليمية تعزز التفاعل ومشاركة الطلبة بشكلٍ فعال.', NULL, ARRAY[107]),
  ('2.3.1', 1, 3, 'يتم تنظيم وترتيب معظم الصفوف والقاعات الدراسية بما يتيح ممارسة الأنشطة التعليمية المختلفة، مما يوفر بيئة تعليمية تعزز التفاعل ومشاركة الطلبة بشكلٍ مناسب.', NULL, ARRAY[107]),
  ('2.3.1', 1, 2, 'يتم تنظيم وترتيب بعض الصفوف والقاعات الدراسية بما يتيح ممارسة الأنشطة التعليمية المختلفة، مما يوفر بيئة تعليمية تعزز التفاعل ومشاركة الطلبة بشكلٍ محدود.', NULL, ARRAY[107]),
  ('2.3.1', 1, 1, 'يتم تنظيم وترتيب قلة من الصفوف والقاعات الدراسية بما يتيح ممارسة الأنشطة التعليمية المختلفة، مما يوفر بيئة تعليمية تعزز التفاعل ومشاركة الطلبة بشكلٍ محدود جداً.', NULL, ARRAY[107]),
  ('2.3.1', 2, 5, 'أثاث جميع الصفوف والمرافق التعليمية ذو جودة عالية ويتناسب مع أعمار الطلبة واحتياجاتهم، مما يسهم في توفير بيئة تعليمية مريحة تدعم تعلمهم بشكلٍ فعال جداً.', NULL, ARRAY[107]),
  ('2.3.1', 2, 4, 'أثاث الغالبية العظمى من الصفوف والمرافق التعليمية ذو جودة ويتناسب مع أعمار الطلبة واحتياجاتهم، مما يسهم في توفير بيئة تعليمية مريحة تدعم تعلمهم بشكلٍ فعال.', NULL, ARRAY[107]),
  ('2.3.1', 2, 3, 'أثاث معظم الصفوف والمرافق التعليمية ذو جودة ويتناسب مع أعمار الطلبة واحتياجاتهم، مما يسهم في توفير بيئة تعليمية تدعم تعلمهم بشكلٍ مناسب.', NULL, ARRAY[107]),
  ('2.3.1', 2, 2, 'أثاث بعض الصفوف والمرافق التعليمية ذو جودة ويتناسب مع أعمار الطلبة، مما يسهم بشكلٍ محدود في توفير بيئة تعليمية داعمة للتعلم.', NULL, ARRAY[107]),
  ('2.3.1', 2, 1, 'أثاث قلة من الصفوف والمرافق التعليمية ذو جودة ويتناسب مع أعمار الطلبة، مما يسهم بشكلٍ محدود جداً في توفير بيئة تعليمية داعمة للتعلم.', NULL, ARRAY[107]),
  ('2.3.1', 3, 5, 'يتم عرض أعمال الطلبة وإنجازاتهم بشكلٍ منتظم ومحدث في جميع الصفوف والمرافق المدرسية، بما يعكس تقدمهم وتطور أدائهم، ويسهم بشكلٍ فعال جداً في تحفيزهم وتعزيز شعورهم بالإنجاز.', NULL, ARRAY[107,108]),
  ('2.3.1', 3, 4, 'يتم عرض أعمال الطلبة وإنجازاتهم بشكلٍ منتظم ومحدث في الغالبية العظمى من الصفوف والمرافق المدرسية، بما يعكس تقدمهم وتطور أدائهم، ويسهم بشكلٍ فعال في تحفيزهم وتعزيز شعورهم بالإنجاز.', NULL, ARRAY[107,108]),
  ('2.3.1', 3, 3, 'يتم عرض أعمال الطلبة وإنجازاتهم بشكلٍ منتظم ومحدث في معظم الصفوف والمرافق المدرسية، بما يعكس تقدمهم وتطور أدائهم، ويسهم بشكلٍ مناسب في تحفيزهم وتعزيز شعورهم بالإنجاز.', NULL, ARRAY[107,108]),
  ('2.3.1', 3, 2, 'يتم عرض أعمال الطلبة وإنجازاتهم بشكلٍ منتظم ومحدث في بعض الصفوف والمرافق المدرسية، مما يسهم بشكلٍ محدود في تحفيزهم وتعزيز شعورهم بالإنجاز.
أو
يتم عرض أعمال الطلبة وإنجازاتهم، إلا أن الأعمال المعروضة لا تُحدَّث بشكل دوري، وتعكس تقدم الطلبة وتطور أدائهم بشكلٍ محدود.', NULL, ARRAY[107,108]),
  ('2.3.1', 3, 1, 'يتم عرض أعمال الطلبة وإنجازاتهم بشكلٍ منتظم في قلة من الصفوف والمرافق المدرسية، مما يسهم بشكلٍ محدود جداً في تحفيزهم وتعزيز شعورهم بالإنجاز.
أو
لا يتم عرض أعمال الطلبة وإنجازاتهم.', NULL, ARRAY[107,108]),
  ('2.3.2', 1, 5, 'توفر المدرسة مجموعة متنوعة وكافية من الموارد والوسائل التعليمية والتكنولوجية الملائمة للمرحلة العمرية في الصفوف والمرافق المدرسية، بما يلبي احتياجات جميع الطلبة ويدعم تعلمهم، ويسهم في تحقيق أهداف المنهج الدراسي المعتمد.', NULL, ARRAY[108]),
  ('2.3.2', 1, 4, 'توفر المدرسة مجموعة متنوعة من الموارد والوسائل التعليمية والتكنولوجية في الصفوف والمرافق المدرسية، بما يلبي احتياجات الغالبية العظمى من الطلبة ويدعم تعلمهم، ويسهم في تحقيق أهداف المنهج الدراسي المعتمد.', NULL, ARRAY[108]),
  ('2.3.2', 1, 3, 'توفر المدرسة مجموعة مناسبة من الموارد والوسائل التعليمية والتكنولوجية في الصفوف والمرافق المدرسية، بما يلبي احتياجات معظم الطلبة ويدعم تعلمهم، ويتوافق بشكلٍ مناسب مع المنهج الدراسي المعتمد.', NULL, ARRAY[108]),
  ('2.3.2', 1, 2, 'توفر المدرسة مجموعة محدودة من الموارد والوسائل التعليمية والتكنولوجية في الصفوف والمرافق المدرسية بما يلبي احتياجات بعض الطلبة/ أهداف المنهج.', NULL, ARRAY[108]),
  ('2.3.2', 1, 1, 'توفر المدرسة مجموعة محدودة جداً من الموارد والوسائل التعليمية والتكنولوجية في الصفوف والمرافق المدرسية بما يلبي احتياجات قلة من الطلبة/ أهداف المنهج.', NULL, ARRAY[108]),
  ('2.3.2', 2, 5, 'يتم توظيف الموارد والوسائل التعليمية بشكلٍ فعال جداً ومستمر ومتنوع، وبما يتلاءم مع أهداف الدروس ويدعم تعلم الطلبة في جميع المواد الدراسية.', NULL, ARRAY[109]),
  ('2.3.2', 2, 4, 'يتم توظيف الموارد والوسائل التعليمية بشكلٍ فعال ومستمر، وبما يتلاءم مع أهداف الدروس ويدعم تعلم الطلبة في الغالبية العظمى من المواد الدراسية.', NULL, ARRAY[109]),
  ('2.3.2', 2, 3, 'يتم توظيف الموارد والوسائل التعليمية بشكلٍ مناسب وبما يتلاءم مع أهداف الدروس ويدعم تعلم الطلبة في معظم المواد الدراسية.', NULL, ARRAY[109]),
  ('2.3.2', 2, 2, 'يتم توظيف الموارد والوسائل التعليمية بما يتلاءم مع أهداف الدروس ويدعم تعلم الطلبة في بعض المواد الدراسية.
أو
يتم توظيف الموارد والوسائل التعليمية، إلا أن أثرها في دعم تعلم الطلبة وتحقيق الأهداف التعليمية محدود.', NULL, ARRAY[109]),
  ('2.3.2', 2, 1, 'يتم توظيف الموارد والوسائل التعليمية بما يتلاءم مع أهداف الدروس ويدعم تعلم الطلبة في قلة من المواد الدراسية.
أو
لا يتم توظيف الموارد والوسائل التعليمية.', NULL, ARRAY[109]),
  ('2.3.2', 3, 5, 'يتم توظيف الموارد والوسائل التكنولوجية بشكلٍ منتظم وفعال جداً، لتوفير بيئة تعليمية تفاعلية تُسهم في تحقيق أهداف الدروس، ودعم تعلم الطلبة وتعزيز تفاعلهم في جميع المواد الدراسية.', NULL, ARRAY[109]),
  ('2.3.2', 3, 4, 'يتم توظيف الموارد والوسائل التكنولوجية بشكلٍ منتظم وفعال، لتوفير بيئة تعليمية تفاعلية تُسهم في تحقيق أهداف الدروس، ودعم تعلم الطلبة في الغالبية العظمى من المواد الدراسية.', NULL, ARRAY[109]),
  ('2.3.2', 3, 3, 'يتم توظيف الموارد والوسائل التكنولوجية بشكلٍ مناسب، لتوفير بيئة تعليمية تفاعلية تُسهم في تحقيق أهداف الدروس، ودعم تعلم الطلبة في معظم المواد الدراسية.', NULL, ARRAY[109]),
  ('2.3.2', 3, 2, 'يتم توظيف الموارد والوسائل التكنولوجية في بعض المواد الدراسية، مما ساهم بشكلٍ محدود في دعم تعلم الطلبة وتعزيز تفاعلهم.
أو
يتم توظيف الموارد والوسائل التكنولوجية، إلا أن أثرها محدود في توفير بيئة تعليمية تفاعلية تُسهم في تحقيق أهداف الدروس ودعم تعلم الطلبة.', NULL, ARRAY[109]),
  ('2.3.2', 3, 1, 'يتم توظيف الموارد والوسائل التكنولوجية في قلة من المواد الدراسية، مما ساهم بشكلٍ محدود جداً في دعم تعلم الطلبة وتعزيز تفاعلهم.
أو
لا يتم توظيف الموارد والوسائل التكنولوجية.', NULL, ARRAY[109]),
  ('2.3.3', 1, 5, 'يتم إدارة الوقت بشكلٍ فعال جداً في جميع الحصص الدراسية، بما يضمن تحقيق أهداف الدروس وتنفيذ الخطط اليومية بكفاءة عالية.', NULL, ARRAY[109,110]),
  ('2.3.3', 1, 4, 'يتم إدارة الوقت بشكلٍ فعال في الغالبية العظمى من الحصص الدراسية، بما يضمن تنفيذ الخطط اليومية وتحقيق أهداف الدروس بكفاءة.', NULL, ARRAY[109,110]),
  ('2.3.3', 1, 3, 'يتم إدارة الوقت بشكلٍ مناسب في معظم الحصص الدراسية، بما يضمن تنفيذ الخطط اليومية وتحقيق أهداف الدروس بشكلٍ مناسب', NULL, ARRAY[109,110]),
  ('2.3.3', 1, 2, 'يتم إدارة الوقت بفعالية في بعض الحصص الدراسية، مما أثر على تحقيق أهداف الدروس.', NULL, ARRAY[109,110]),
  ('2.3.3', 1, 1, 'يتم إدارة الوقت بفعالية في قلة من الحصص الدراسية، مما أثر سلباً على تحقيق أهداف الدروس.', NULL, ARRAY[109,110]),
  ('2.3.3', 2, 5, 'يتم تطبيق قواعد السلوك والقوانين الصفية بشكلٍ فعال جداً ومنتظم، مما يسهم في تعزيز إدارة صفية إيجابية وتوفير بيئة تعليمية داعمة لتعلم الطلبة في جميع الحصص الدراسية.', NULL, ARRAY[110]),
  ('2.3.3', 2, 4, 'يتم تطبيق قواعد السلوك والقوانين الصفية بشكلٍ فعال، مما يسهم في تعزيز إدارة صفية إيجابية وتوفير بيئة تعليمية داعمة لتعلم الطلبة في الغالبية العظمى من الحصص الدراسية.', NULL, ARRAY[110]),
  ('2.3.3', 2, 3, 'يتم تطبيق قواعد السلوك والقوانين الصفية بشكلٍ مناسب، مما يسهم في تعزيز إدارة صفية إيجابية وتوفير بيئة تعليمية داعمة لتعلم الطلبة في معظم الحصص الدراسية.', NULL, ARRAY[110]),
  ('2.3.3', 2, 2, 'يتم تطبيق قواعد السلوك والقوانين الصفية في بعض الحصص الدراسية، مما يؤدي إلى توفير بيئة تعليمية داعمة لتعلم الطلبة بشكلٍ محدود.', NULL, ARRAY[110]),
  ('2.3.3', 2, 1, 'يتم تطبيق قواعد السلوك والقوانين الصفية في قلة من الحصص الدراسية، مما يؤدي إلى توفير بيئة تعليمية داعمة لتعلم الطلبة-بشكلٍ محدود جداً.', NULL, ARRAY[110]),
  ('2.3.3', 3, 5, 'يقوم المعلم المساعد بدورٍ فعال جداً في تعزيز بيئة التعلم من خلال التفاعل الإيجابي والمستمر مع المعلمين والطلبة، وتقديم الدعم الملائم للطلبة ومتابعتهم أثناء الأنشطة الصفية في جميع الحصص الدراسية.
(إن وجد)', NULL, ARRAY[110]),
  ('2.3.3', 3, 4, 'يقوم المعلم المساعد بدورٍ فعال في تعزيز بيئة التعلم من خلال التفاعل الإيجابي مع المعلمين والطلبة، وتقديم الدعم الملائم للطلبة ومتابعتهم أثناء الأنشطة الصفية في الغالبية العظمى من الحصص الدراسية.
(إن وجد)', NULL, ARRAY[110]),
  ('2.3.3', 3, 3, 'يقوم المعلم المساعد بدورٍ مناسب في تعزيز بيئة التعلم، وتقديم الدعم للطلبة ومتابعتهم أثناء الأنشطة الصفية في معظم الحصص الدراسية.
(إن وجد)', NULL, ARRAY[110]),
  ('2.3.3', 3, 2, 'يقوم المعلم المساعد بتعزيز بيئة التعلم، وتقديم الدعم للطلبة ومتابعتهم أثناء الأنشطة الصفية في بعض الحصص الدراسية.
(إن وجد)', NULL, ARRAY[110]),
  ('2.3.3', 3, 1, 'يقوم المعلم المساعد بتقديم الدعم للطلبة ومتابعتهم أثناء الأنشطة الصفية في قلة من الحصص الدراسية.
(إن وجد).
أو
لا يقوم المعلم المساعد بتعزيز بيئة التعلم، وتقديم الدعم للطلبة ومتابعتهم أثناء الأنشطة الصفية.', NULL, ARRAY[110]),
  ('3.1.1', 1, 5, 'يتم إعداد وتنفيذ سياسة تقييم ذات جودة عالية واضحة وشاملة ومعلنة وتتوافق مع أهداف المنهج الدراسي، ويتم توظيف طرق وأدوات تقييم متنوعة تلبي احتياجات التعلم المختلفة، وتُقيم جوانب متعددة من أداء الطلبة، بشكلٍ منتظم في جميع المواد والصفوف الدراسية.', NULL, ARRAY[127]),
  ('3.1.1', 1, 4, 'يتم إعداد وتنفيذ سياسة تقييم ذات جودة واضحة ومعلنة وتتوافق مع أهداف المنهج الدراسي، ويتم توظيف طرق وأدوات تقييم متنوعة تلبي احتياجات التعلم المختلفة، وتُقيم جوانب متعددة من أداء الطلبة، بشكلٍ منتظم في الغالبية العظمى من المواد والصفوف الدراسية.', NULL, ARRAY[127]),
  ('3.1.1', 1, 3, 'يتم إعداد وتنفيذ سياسة تقييم ذات جودة مناسبة ومعلنة وتتوافق مع أهداف المنهج الدراسي، ويتم توظيف طرق وأدوات تقييم متنوعة تُقيم جوانب متعددة من أداء الطلبة، بشكلٍ منتظم في معظم المواد والصفوف الدراسية.', NULL, ARRAY[127]),
  ('3.1.1', 1, 2, 'يتم إعداد وتنفيذ سياسة تقييم معلنة إلا أن جودتها محدودة، ويتم توظيف طرق وأدوات تقييم متنوعة لتقييم أداء الطلبة، بشكلٍ منتظم في بعض المواد والصفوف الدراسية.
أو
سياسة التقييم ذات جودة وواضحة ومعلنة إلا أنه يتم الالتزام بها وتوظيف طرق وأدوات تقييم محدودة، مما أثر على تقييم أداء الطلبة والتعرف على مستوى أدائهم وتحقيق أهداف المنهج.', NULL, ARRAY[127]),
  ('3.1.1', 1, 1, 'يتم إعداد وتنفيذ سياسة تقييم معلنة ذات جودة محدودة جداً، ويتم توظيف طرق وأدوات تقييم متنوعة في قلة من المواد والصفوف الدراسية.
أو
سياسة التقييم غير واضحة ولا تتوافق مع أهداف المنهج الدراسي.', NULL, ARRAY[127]),
  ('3.1.1', 2, 5, 'يتم إعداد تقارير واضحة وشاملة ودقيقة، تعكس مستوى أداء الطلبة في جميع جوانب الأداء عبر المواد والصفوف الدراسية المختلفة، ويتم إرسالها ومناقشتها بشكلٍ منتظم مع أولياء الأمور.', NULL, ARRAY[128]),
  ('3.1.1', 2, 4, 'يتم إعداد تقارير واضحة ودقيقة، تعكس مستوى أداء الطلبة في الغالبية العظمى من جوانب الأداء عبر المواد والصفوف الدراسية المختلفة، ويتم إرسالها ومناقشتها بشكلٍ منتظم مع أولياء الأمور.', NULL, ARRAY[128]),
  ('3.1.1', 2, 3, 'يتم إعداد تقارير واضحة ودقيقة، وتعكس مستوى أداء الطلبة في معظم جوانب الأداء عبر المواد والصفوف الدراسية المختلفة، ويتم إرسالها ومناقشتها بشكلٍ منتظم مع أولياء الأمور.', NULL, ARRAY[128]),
  ('3.1.1', 2, 2, 'يتم إعداد تقارير ذات جودة محدودة، تعكس مستوى أداء الطلبة في بعض جوانب الأداء عبر المواد والصفوف الدراسية المختلفة، ويتم إرسالها لأولياء الأمور.
أو
يتم إعداد تقارير واضحة تعكس مستوى أداء الطلبة في مختلف جوانب الأداء، لكن في بعض المواد والصفوف الدراسية، ويتم إرسالها لأولياء الأمور.', NULL, ARRAY[128]),
  ('3.1.1', 2, 1, 'تقارير أداء الطلبة غير واضحة و/أو لا تعكس بدقة مستوى أداء الطلبة.
أو
تقارير أداء الطلبة تعكس مستوى الأداء بشكل واضح في قلة من الجوانب.', NULL, ARRAY[128]),
  ('3.1.2', 1, 5, 'يتم تطبيق إجراءات واضحة وعادلة ودقيقة لقبول الطلبة، تتناسب مع طبيعة المرحلة التعليمية المستهدفة ومعاييرها، كما يتم إجراء اختبارات تشخيصية لتحديد مستوى معارف الطلبة ومهاراتهم، ويتم تحليل نتائجها بدقة، ويستفاد منها بشكلٍ فعال جداً في توجيه عملية التعليم والتعلم.، مما يسهم في تحسين نواتج التعلم وتلبية احتياجات جميع الطلبة المختلفة.', NULL, ARRAY[129]),
  ('3.1.2', 1, 4, 'يتم تطبيق إجراءات واضحة وعادلة لقبول الطلبة، تتناسب مع طبيعة المرحلة التعليمية المستهدفة ومعاييرها، كما يتم إجراء اختبارات تشخيصية لتحديد مستوى معارف الطلبة ومهاراتهم، ويتم تحليل نتائجها، ويستفاد منها بشكلٍ فعال في توجيه عملية التعليم والتعلم.، مما يسهم في تحسين نواتج التعلم وتلبية احتياجات الغالبية العظمى من الطلبة المختلفة.', NULL, ARRAY[129]),
  ('3.1.2', 1, 3, 'يتم تطبيق إجراءات مناسبة لقبول الطلبة، تتناسب مع طبيعة المرحلة التعليمية المستهدفة ومعاييرها، كما يتم إجراء اختبارات تشخيصية لتحديد مستوى معارف الطلبة ومهاراتهم، ويتم تحليل نتائجها، والاستفادة منها بشكلٍ مناسب في توجيه عملية التعليم والتعلم.، مما يسهم في تحسين نواتج التعلم وتلبية احتياجات معظم الطلبة.', NULL, ARRAY[129]),
  ('3.1.2', 1, 2, 'يتم تطبيق إجراءات لقبول الطلبة، كما يتم إجراء اختبارات تشخيصية لتحديد مستوى معارف الطلبة ومهاراتهم، إلا أن الاستفادة من نتائجها محدودة، ويقتصر أثرها على تلبية احتياجات بعض الطلبة.
أو
يتم إجراء اختبارات تشخيصية لتحديد مستوى معارف ومهارات الطلبة، ويتم تحليل نتائجها والاستفادة منها، لكن لا يتم تطبيق إجراءات واضحة وعادلة لقبول الطلبة.', NULL, ARRAY[129]),
  ('3.1.2', 1, 1, 'يتم تطبيق إجراءات لقبول الطلبة، كما يتم إجراء اختبارات تشخيصية لتحديد مستوى معارف الطلبة ومهاراتهم، إلا أن الاستفادة من نتائجها محدودة جداً، ويقتصر أثرها على تلبية احتياجات قلة من الطلبة.
أو
لا يتم إجراء اختبارات تشخيصية للطلبة.
أو
يتم إجراء اختبارات تشخيصية و/ أو إجراءات قبول للطلبة لتحديد مستوى معارفهم ومهاراتهم، لكن لا يتم تحليل نتائج هذه الاختبارات. والاستفادة منها.', NULL, ARRAY[129]),
  ('3.1.2', 2, 5, 'جميع التقييمات الداخلية ذات جودة عالية، ومواصفات ومعايير محددة وواضحة، وتتوافق بشكلٍ فعال جداً مع المنهج المطبق في المدرسة.', NULL, ARRAY[129,130]),
  ('3.1.2', 2, 4, 'الغالبية العظمى من التقييمات الداخلية ذات جودة، ومواصفات ومعايير محددة وواضحة، وتتوافق بشكلٍ فعال مع المنهج المطبق في المدرسة.', NULL, ARRAY[129,130]),
  ('3.1.2', 2, 3, 'معظم التقييمات الداخلية ذات مواصفات ومعايير محددة وواضحة، وتتوافق بشكلٍ مناسب مع المنهج المطبق في المدرسة.', NULL, ARRAY[129,130]),
  ('3.1.2', 2, 2, 'بعض التقييمات الداخلية ذات مواصفات ومعايير واضحة ومحددة، وتتوافق مع المنهج المطبق في المدرسة.', NULL, ARRAY[129,130]),
  ('3.1.2', 2, 1, 'قلة من التقييمات الداخلية ذات مواصفات ومعايير وواضحة، وتتوافق مع المنهج المطبق في المدرسة.
أو
لا تعتمد المدرسة على مواصفات ومعايير محددة وواضحة لإعداد التقييمات الداخلية.', NULL, ARRAY[129,130]),
  ('3.1.2', 3, 5, 'يتم تقديم تغذية راجعة منتظمة وفعالة جداً لجميع الطلبة بعد كافة التقييمات، مما يساعدهم على تحديد نقاط القوة والتحسين بوضوح، وتوفر التغذية الراجعة للطلبة توجيهات واضحة ومحددة لتحسين أدائهم وتعزيز تعلمهم.', NULL, ARRAY[130]),
  ('3.1.2', 3, 4, 'يتم تقديم تغذية راجعة منتظمة وفعالة للغالبية العظمى من الطلبة بعد كافة التقييمات، مما يساعدهم على تحديد نقاط القوة والتحسين، وتوفر التغذية الراجعة للطلبة توجيهات لتحسين أدائهم وتعزيز تعلمهم.', NULL, ARRAY[130]),
  ('3.1.2', 3, 3, 'يتم تقديم تغذية راجعة مناسبة لمعظم الطلبة بعد التقييمات، مما يساعدهم على تحديد نقاط القوة والتحسين لتحسين أدائهم.', NULL, ARRAY[130]),
  ('3.1.2', 3, 2, 'يتم تقديم تغذية راجعة لبعض الطلبة بعد التقييمات، مما يوفر توجيهات محدودة لتحسين الأداء.
أو
يتم تقديم تغذية راجعة للطلبة بعد التقييمات، إلا أنها توفر توجيهات محدودة لتحسين أدائهم.', NULL, ARRAY[130]),
  ('3.1.2', 3, 1, 'يتم تقديم تغذية راجعة لقلة من الطلبة بعد التقييمات، مما يوفر توجيهات محدودة جداً لتحسين الأداء.
أو
لا يتم تقديم تغذية راجعة منتظمة للطلبة لتحسين أدائهم.', NULL, ARRAY[130]),
  ('3.1.3', 1, 5, 'يتم تدريب وتهيئة الطلبة بصورة شاملة ومنتظمة، ومبنية على تحليل دقيق لاحتياجاتهم، لجميع الاختبارات الخارجية، بما ينعكس بشكلٍ فعال جداً على نتائج الطلبة في تلك الاختبارات.', NULL, ARRAY[130,131]),
  ('3.1.3', 1, 4, 'يتم تدريب وتهيئة الطلبة بصورة شاملة ومنتظمة، ومبنية على تحليل دقيق لاحتياجاتهم، للغالبية العظمى من الاختبارات الخارجية، بما ينعكس بشكلٍ فعال على نتائج الطلبة في تلك الاختبارات.', NULL, ARRAY[130,131]),
  ('3.1.3', 1, 3, 'يتم تدريب وتهيئة الطلبة بصورة شاملة ومنتظمة، ومبنية على تحليل دقيق لاحتياجاتهم، لمعظم الاختبارات الخارجية، بما ينعكس بشكلٍ مناسب على نتائج الطلبة في تلك الاختبارات.', NULL, ARRAY[130,131]),
  ('3.1.3', 1, 2, 'يتم تدريب وتهيئة الطلبة بصورة شاملة ومنتظمة، ومبنية على تحليل دقيق لاحتياجاتهم، لبعض الاختبارات الخارجية، بما ينعكس بشكلٍ محدود على نتائج الطلبة في تلك الاختبارات.
أو
يتم تهيئة وتدريب الطلبة بشكل شامل ومنتظم لمختلف الاختبارات الخارجية إلا أنها انعكست بشكلٍ محدود على نتائج الطلبة في الاختبارات المختلفة.', NULL, ARRAY[130,131]),
  ('3.1.3', 1, 1, 'يتم تدريب وتهيئة الطلبة بصورة شاملة ومنتظمة، ومبنية على تحليل دقيق لاحتياجاتهم، لقلة من الاختبارات الخارجية بما ينعكس بشكلٍ فعال جداً على نتائج الطلبة في تلك الاختبارات.
أو
لا يتم تدريب وتهيئة الطلبة للاختبارات الخارجية.', NULL, ARRAY[130,131]),
  ('3.1.4', 1, 5, 'يظهر أداء الطلبة في التقييمات الداخلية تقدماً واضحاً ومستمراً / ثباتاً عبر فترات زمنية متعاقبة، ويحققون مستويات أداء مرتفعة في جميع المواد الدراسية.', NULL, ARRAY[131]),
  ('3.1.4', 1, 4, 'يظهر أداء الطلبة في التقييمات الداخلية تقدماً واضحاً / ثباتاً عبر فترات زمنية متعاقبة، ويحققون مستويات أداء مرتفعة في الغالبية العظمى من المواد الدراسية.', NULL, ARRAY[131]),
  ('3.1.4', 1, 3, 'يظهر أداء الطلبة في التقييمات الداخلية تقدماً واضحاً / ثباتاً عبر فترات زمنية متعاقبة، ويحققون مستويات أداء مرتفعة في معظم المواد الدراسية.', NULL, ARRAY[131]),
  ('3.1.4', 1, 2, 'يظهر أداء الطلبة في التقييمات الداخلية تقدماً / ثباتاً عبر فترات زمنية متعاقبة، ويحققون مستويات أداء مرتفعة في بعض المواد الدراسية، ويحققون مستويات أداء متوسطة في باقي المواد الدراسية.', NULL, ARRAY[131]),
  ('3.1.4', 1, 1, 'يظهر أداء الطلبة في التقييمات الداخلية تقدماً / ثباتاً عبر فترات زمنية متعاقبة، ويحققون مستوى أداء مرتفع في قلة من المواد الدراسية، ويحققون مستويات أداء منخفضة في باقي المواد الدراسية.', NULL, ARRAY[131]),
  ('3.1.4', 2, 5, 'تتوافق جميع نتائج الطلبة في الاختبارات الداخلية بشكلٍ مستمر مع نتائجهم في الاختبارات الخارجية.', NULL, ARRAY[131]),
  ('3.1.4', 2, 4, 'تتوافق الغالبية العظمى من نتائج الطلبة في الاختبارات الداخلية بشكلٍ مستمر مع نتائجهم في الاختبارات الخارجية.', NULL, ARRAY[131]),
  ('3.1.4', 2, 3, 'تتوافق معظم نتائج الطلبة في الاختبارات الداخلية بشكلٍ مستمر مع نتائجهم في الاختبارات الخارجية.', NULL, ARRAY[131]),
  ('3.1.4', 2, 2, 'تتوافق بعض نتائج الطلبة في الاختبارات الداخلية مع نتائجهم في الاختبارات الخارجية.', NULL, ARRAY[131]),
  ('3.1.4', 2, 1, 'تتوافق قلة من نتائج الطلبة في الاختبارات الداخلية مع نتائجهم في الاختبارات الخارجية.
أو
لا تتوافق نتائج الطلبة في الاختبارات الداخلية مع نتائجهم في الاختبارات الخارجية', NULL, ARRAY[131]),
  ('3.1.5', 1, 5, 'يتم تطبيق اختبارات معيارية متوافقة مع المنهج المعتمد في المدرسة بشكلٍ منتظم ودوري على جميع الطلبة في المراحل المستهدفة، بهدف توفير تقييم موضوعي ودقيق لمستوى تحصيلهم، ومقارنته بالمعدلات المرجعية.', NULL, ARRAY[132]),
  ('3.1.5', 1, 4, 'يتم تطبيق اختبارات معيارية متوافقة مع المنهج المعتمد في المدرسة بشكلٍ منتظم ودوري على الغالبية العظمى من الطلبة في المراحل المستهدفة، بهدف توفير تقييم موضوعي لمستوى تحصيلهم، ومقارنته بالمعدلات المرجعية.', NULL, ARRAY[132]),
  ('3.1.5', 1, 3, 'يتم تطبيق اختبارات معيارية متوافقة مع المنهج المعتمد في المدرسة بشكلٍ منتظم ودوري على معظم الطلبة في المراحل المستهدفة، بهدف توفير تقييم موضوعي لمستوى تحصيلهم، ومقارنته بالمعدلات المرجعية.', NULL, ARRAY[132]),
  ('3.1.5', 1, 2, 'يتم تطبيق اختبارات معيارية متوافقة مع المنهج المعتمد في المدرسة بشكلٍ منتظم على بعض الطلبة في المراحل المستهدفة.
أو
يتم تطبيق اختبارات معيارية متوافقة مع المنهج المعتمد في المدرسة، لكن بشكلٍ غير منتظم دوري، مما أدى إلى توفير تقييم محدود لمستوى تحصيل الطلبة.', NULL, ARRAY[132]),
  ('3.1.5', 1, 1, 'يتم تطبيق اختبارات معيارية متوافقة مع المنهج المعتمد في المدرسة على قلة من الطلبة في المراحل المستهدفة..
أو
لا تطبق المدرسة اختبارات معيارية.
أو
