  ('3.1.9', 1, 5, 'يتم إجراء تحليل شامل ومنتظم ودقيق لنتائج الطلبة في التقييمات الداخلية في جميع المواد والصفوف الدراسية عبر فترات زمنية متعاقبة لقياس مدى التقدم، ويتم توثيق هذه التحليلات بدقة ووضوح في سجلات منظمة، كما توظف نتائج التحليل بشكلٍ فعال جداً في اتخاذ قرارات تهدف إلى تحسين أداء الطلبة وتعزيز جودة العملية التعليمية.', NULL, ARRAY[136,137]),
  ('3.1.9', 1, 4, 'يتم إجراء تحليل منتظم ودقيق لنتائج الطلبة في التقييمات الداخلية في الغالبية العظمى من المواد والصفوف الدراسية عبر فترات زمنية متعاقبة لقياس مدى التقدم، ويتم توثيق هذه التحليلات بدقة ووضوح في سجلات منظمة، كما توظف نتائج التحليل بشكلٍ فعال في اتخاذ قرارات تهدف إلى تحسين أداء الطلبة.', NULL, ARRAY[136,137]),
  ('3.1.9', 1, 3, 'يتم إجراء تحليل منتظم لنتائج الطلبة في التقييمات الداخلية في معظم المواد والصفوف الدراسية عبر فترات زمنية متعاقبة لقياس مدى التقدم، ويتم توثيق هذه التحليلات في سجلات منظمة، كما توظف نتائج التحليل بشكلٍ مناسب في اتخاذ قرارات تهدف إلى تحسين أداء الطلبة.', NULL, ARRAY[136,137]),
  ('3.1.9', 1, 2, 'يتم إجراء تحليل لنتائج الطلبة في التقييمات الداخلية في بعض المواد والصفوف الدراسية لقياس مدى التقدم، ويتم توثيق هذه التحليلات، كما يتم توظيف نتائج التحليل بشكلٍ محدود في اتخاذ قرارات تهدف إلى تحسين الأداء.
أو
يتم إجراء تحليل محدود لنتائج الطلبة في التقييمات الداخلية في المواد والصفوف الدراسية، مما أثر على الاستفادة من توظيف نتائج التحليل في اتخاذ قرارات تهدف إلى تحسين الأداء.
أو
يتم إجراء تحليل لنتائج الطلبة في التقييمات الداخلية في المواد والصفوف الدراسية لقياس مدى التقدم، إلا أن توظيف نتائج التحليل في اتخاذ قرارات لتحسين أداء الطلبة يتم بشكلٍ محدود.', NULL, ARRAY[136,137]),
  ('3.1.9', 1, 1, 'يتم إجراء تحليل لنتائج الطلبة في التقييمات الداخلية في قلة من المواد والصفوف الدراسية لقياس مدى التقدم، ويتم الاستفادة من نتائج التحليل بشكلٍ محدود جداً في اتخاذ قرارات تهدف إلى تحسين الأداء.
أو
لا يتم إجراء تحليل لنتائج الطلبة في التقييمات الداخلية، أو التحليل غير واضح وغير دقيق.', NULL, ARRAY[136,137]),
  ('3.1.9', 2, 5, 'يتم إجراء تحليل شامل ومنتظم ودقيق لنتائج جميع التقييمات الخارجية عبر فترات زمنية متعاقبة لقياس مدى التقدم وتحديد جوانب القوة والضعف، ويتم توثيق هذه التحليلات بدقة ووضوح في سجلات منظمة، كما توظف نتائج التحليل بشكلٍ فعال جداً في اتخاذ قرارات تهدف إلى تحسين أداء الطلبة. وتعزيز جودة العملية التعليمية.', NULL, ARRAY[137,138]),
  ('3.1.9', 2, 4, 'يتم إجراء تحليل منتظم ودقيق لنتائج الغالبية العظمى من التقييمات الخارجية عبر فترات زمنية متعاقبة لقياس مدى التقدم وتحديد جوانب القوة والضعف، ويتم توثيق هذه التحليلات بدقة ووضوح في سجلات منظمة، كما توظف نتائج التحليل بشكلٍ فعال في اتخاذ قرارات تهدف إلى تحسين أداء الطلبة.', NULL, ARRAY[137,138]),
  ('3.1.9', 2, 3, 'يتم إجراء تحليل منتظم لنتائج الطلبة معظم التقييمات الخارجية عبر فترات زمنية متعاقبة لقياس مدى التقدم وتحديد جوانب القوة والضعف، ويتم توثيق هذه التحليلات في سجلات منظمة، ويتم توظف نتائج التحليل بشكلٍ مناسب في اتخاذ قرارات تهدف إلى تحسين أداء الطلبة.', NULL, ARRAY[137,138]),
  ('3.1.9', 2, 2, 'يتم إجراء تحليل لنتائج الطلبة في بعض التقييمات الخارجية عبر فترات زمنية متعاقبة لقياس مدى التقدم، ويتم توثيق هذه التحليلات، ويتم توظيف نتائج التحليل بشكلٍ محدود في اتخاذ قرارات تهدف إلى تحسين الأداء.
أو
يتم إجراء تحليل محدود لنتائج الطلبة في التقييمات الخارجية في المواد والمراحل الدراسية، مما أثر على الاستفادة من توظيف نتائج التحليل في اتخاذ قرارات تهدف إلى تحسين الأداء.
أو
يتم إجراء تحليل لنتائج الطلبة في التقييمات الخارجية لقياس مدى التقدم، إلا أن توظيف نتائج التحليل في اتخاذ قرارات لتحسين أداء الطلبة يكون بشكلٍ محدود.', NULL, ARRAY[137,138]),
  ('3.1.9', 2, 1, 'يتم إجراء تحليل لنتائج الطلبة في قلة من التقييمات الخارجية في قلة من المواد والمراحل الدراسية لقياس مدى التقدم، ويتم الاستفادة من نتائج التحليل بشكلٍ محدود جداً في اتخاذ قرارات تهدف إلى تحسين الأداء.
أو
لا يتم إجراء تحليل لنتائج الطلبة في التقييمات الداخلية، أو أن التحليل غير واضح وغير دقيق.', NULL, ARRAY[137,138]),
  ('3.2.1', 1, 5, 'يتم تطبيق إجراءات واضحة ومحددة ودقيقة لتحديد الطلبة الموهوبين، وإعداد خطط ذات جودة عالية تشتمل على برامج وأنشطة مخصصة ومتنوعة تتناسب مع احتياجات جميع الطلبة الموهوبين.', NULL, ARRAY[138,139]),
  ('3.2.1', 1, 4, 'يتم تطبيق إجراءات واضحة ومحددة لتحديد الطلبة الموهوبين، وإعداد خطط ذات جودة تشتمل على برامج وأنشطة متنوعة تتناسب مع احتياجات الغالبية العظمى من الطلبة الموهوبين.', NULL, ARRAY[138,139]),
  ('3.2.1', 1, 3, 'يتم تطبيق إجراءات واضحة لتحديد الطلبة الموهوبين، وإعداد خطط مناسبة تشتمل على برامج وأنشطة تتناسب مع احتياجات معظم الطلبة الموهوبين.', NULL, ARRAY[138,139]),
  ('3.2.1', 1, 2, 'يتم تطبيق إجراءات لتحديد الطلبة الموهوبين، إلا أنه يتم إعداد خطط جودتها محدودة تشتمل على أنشطة تتناسب مع احتياجات بعض الطلبة الموهوبين.
أو
يتم تطبيق إجراءات واضحة لتحديد الطلبة الموهوبين، ويتم إعداد خطط و/ أو برامج لتنمية مهاراتهم، إلا أنها تتناسب بشكلٍ محدود مع احتياجات الطلبة الموهوبين.', NULL, ARRAY[138,139]),
  ('3.2.1', 1, 1, 'يتم تطبيق إجراءات غير واضحة لتحديد الطلبة الموهوبين، كما أن الخطط جودتها محدودة جداً وتشتمل على أنشطة تتناسب مع احتياجات قلة من الطلبة الموهوبين.
أو
لا يوجد إجراءات لتحديد الطلبة الموهوبين.
أو
لا يتم إعداد خطط و/أو برامج لرعاية الطلبة الموهوبين.', NULL, ARRAY[138,139]),
  ('3.2.1', 2, 5, 'يتم تنفيذ ومتابعة وتقييم أثر الخطط والبرامج والأنشطة على تعزيز مهارات وقدرات الطلبة الموهوبين بشكل فعال جداً ومستمر والتعديل عليها بناءً على نتائج المتابعة، مما أدى إلى تحقيق تطوراً واضحاً في مهارات جميع الطلبة الموهوبين.', NULL, ARRAY[139]),
  ('3.2.1', 2, 4, 'يتم تنفيذ ومتابعة وتقييم أثر الخطط والبرامج والأنشطة على تعزيز مهارات وقدرات الطلبة الموهوبين بشكل فعال، والتعديل عليها بناءً على نتائج المتابعة، مما أدى إلى تحقيق تطوراً واضحاً في مهارات الغالبية العظمى من الطلبة الموهوبين.', NULL, ARRAY[139]),
  ('3.2.1', 2, 3, 'يتم تنفيذ ومتابعة وتقييم أثر الخطط والبرامج الموجهة للطلبة الموهوبين بشكل مناسب، والتعديل عليها بناءً على نتائج المتابعة، مما أدى إلى تحقيق تطوراً في مهارات معظم الطلبة الموهوبين.', NULL, ARRAY[139]),
  ('3.2.1', 2, 2, 'يتم تنفيذ ومتابعة الخطط والبرامج الموجهة للطلبة الموهوبين بشكلٍ محدود، مما أدى إلى تطور في مهارات بعض الطلبة الموهوبين.
أو
يتم تنفيذ الخطط والبرامج، لكن لا يتم متابعة التنفيذ وتقييم الأثر مما أدى إلى تطور محدود في مهارات الطلبة.', NULL, ARRAY[139]),
  ('3.2.1', 2, 1, 'يتم تنفيذ الخطط بشكلٍ محدود جداً، مما أدى إلى تطور في مهارات قلة من الطلبة الموهوبين.', NULL, ARRAY[139]),
  ('3.2.2', 1, 5, 'يتم إعداد وتنفيذ خطط دعم فعالة جداً وشاملة، تتناسب مع احتياجات الطلبة ذوي الأداء الأكاديمي المنخفض، ويتم متابعة أداء الطلبة، وتقييم فعالية الخطط والتعديل عليها لضمان تحقيق التقدم، مما ساهم في تحقيق تحسناً ملحوظاً في مستوى أداء جميع الطلبة ذوي الأداء الأكاديمي المنخفض.', NULL, ARRAY[140]),
  ('3.2.2', 1, 4, 'يتم إعداد وتنفيذ خطط دعم فعالة تتناسب مع احتياجات الطلبة ذوي الأداء الأكاديمي المنخفض، ويتم متابعة أداء الطلبة، وتقييم فعالية الخطط والتعديل عليها مما ساهم في تحقيق تحسناً ملحوظاً في مستوى أداء الغالبية العظمى من الطلبة ذوي الأداء الأكاديمي المنخفض.', NULL, ARRAY[140]),
  ('3.2.2', 1, 3, 'يتم إعداد وتنفيذ خطط دعم تتناسب مع احتياجات الطلبة ذوي الأداء الأكاديمي المنخفض بشكلٍ مناسب، ويتم متابعة أداء الطلبة، وتقييم فعالية الخطط والتعديل عليها مما ساهم في تحقيق تحسناً ملحوظاً في مستوى أداء معظم الطلبة ذوي الأداء الأكاديمي المنخفض.', NULL, ARRAY[140]),
  ('3.2.2', 1, 2, 'يتم إعداد وتنفيذ خطط دعم تتناسب بشكلٍ محدود مع احتياجات الطلبة ذوي الأداء الأكاديمي المنخفض، ويتم متابعة أدائهم، إلا أن ذلك أدى إلى تحقيق تحسن في مستوى أداء بعض الطلبة ذوي الأداء الأكاديمي المنخفض.', NULL, ARRAY[140]),
  ('3.2.2', 1, 1, 'يتم إعداد وتنفيذ خطط دعم تتناسب بشكل محدود جداً مع احتياجات الطلبة ذوي الأداء الأكاديمي المنخفض، مما أدى إلى تحقيق تحسن في مستوى أداء قلة من الطلبة ذوي الأداء الأكاديمي المنخفض.
أو
يتم إعداد خطط لدعم الطلبة ذوي الأداء المنخفض، لكن تفتقر للجودة، و/أو لا يتم متابعة الأداء، أو تقييم الخطط والتعديل عليها.
أو
لا توجد خطط دعم للطلبة ذوي الأداء الأكاديمي المنخفض.', NULL, ARRAY[140]),
  ('3.2.3', 1, 5, 'يتم إجراء تقييمات دقيقة وشاملة لتحديد نوع وشدة الإعاقة واحتياجات الطلبة الفردية، باستخدام أدوات تقييم متنوعة ومتخصصة وموثوقة، مما أدى إلى تشخيص وحصر شامل ودقيق لجميع حالات وأنواع الإعاقات.', NULL, ARRAY[140,141]),
  ('3.2.3', 1, 4, 'يتم إجراء تقييمات دقيقة لتحديد نوع وشدة الإعاقة واحتياجات الطلبة الفردية، باستخدام أدوات تقييم متخصصة وموثوقة، مما أدى إلى تشخيص وحصر للغالبية العظمى من حالات وأنواع الإعاقات.', NULL, ARRAY[140,141]),
  ('3.2.3', 1, 3, 'يتم إجراء تقييمات مناسبة لتحديد نوع وشدة الإعاقة واحتياجات الطلبة الفردية، باستخدام أدوات تقييم موثوقة، مما أدى إلى تشخيص وحصر لمعظم حالات وأنواع الإعاقات.', NULL, ARRAY[140,141]),
  ('3.2.3', 1, 2, 'يتم إجراء تقييمات لتحديد نوع الإعاقة باستخدام أدوات تقييم محدودة، مما أدى إلى تشخيص وحصر بعض حالات وأنواع الإعاقات.', NULL, ARRAY[140,141]),
  ('3.2.3', 1, 1, 'يتم إجراء تقييمات لتحديد نوع الإعاقة باستخدام أدوات تقييم محدودة جداً، مما أدى إلى حصر قلة من حالات وأنواع الإعاقات.
أو
لا يتم إجراء تقييمات لتحديد نوع وحالات الإعاقة.', NULL, ARRAY[140,141]),
  ('3.2.3', 2, 5, 'يتم إعداد وتنفيذ خطط تعليمية فردية شاملة وذات جودة عالية، تتضمن أهداف تعليمية تتناسب مع احتياجات جميع الطلبة بناءً على نوع الإعاقة، ويتم تقديم الدعم المتخصص من خلال توفير تعديلات بيئية وتعليمية متناسبة مع الحالات، وتوفير موارد بشرية مؤهلة تأهيلاً عالياً وأدوات تعليمية مخصصة تتناسب مع حالات الإعاقة.', NULL, ARRAY[141]),
  ('3.2.3', 2, 4, 'يتم إعداد وتنفيذ خطط تعليمية فردية شاملة وذات جودة، تتضمن أهداف تعليمية تتناسب مع احتياجات الغالبية العظمى من الطلبة بناءً على نوع الإعاقة، ويتم تقديم الدعم للطلبة من خلال توفير تعديلات بيئية وتعليمية متناسبة مع الحالات، وتوفير موارد بشرية مؤهلة وأدوات تعليمية تتناسب مع حالات الإعاقة.', NULL, ARRAY[141]),
  ('3.2.3', 2, 3, 'يتم إعداد وتنفيذ خطط تعليمية فردية مناسبة، تتضمن أهداف تعليمية تتناسب مع احتياجات معظم الطلبة بناءً على نوع الإعاقة، ويتم تقديم الدعم للطلبة من خلال توفير تعديلات بيئية وتعليمية مناسبة، وتوفير أدوات تعليمية وموارد بشرية مؤهلة.', NULL, ARRAY[141]),
  ('3.2.3', 2, 2, 'يتم إعداد وتنفيذ خطط تعليمية تتناسب مع احتياجات بعض الطلبة بناءً على نوع الإعاقة، ويتم تقديم الدعم للطلبة بشكلٍ محدود.', NULL, ARRAY[141]),
  ('3.2.3', 2, 1, 'يتم إعداد وتنفيذ خطط تعليمية تتناسب مع احتياجات قلة من الطلبة من ذوي الإعاقة، ويتم تقديم الدعم للطلبة بشكلٍ محدود جداً.
أو
لا يتم إعداد خطط تعليمية للطلبة من ذوي الإعاقة.', NULL, ARRAY[141]),
  ('3.2.3', 3, 5, 'يتم متابعة وتحليل تقدم الطلبة ذوي الإعاقة بشكلٍ منتظم وفعال جداً لتقييم مدى فعالية التدخلات والدعم المقدم، ويتم إجراء التعديلات اللازمة على الخطط بناءً على نتائج التقييم والمتابعة، مما أسهم في تحقيق تحسناً ملحوظاً في مستوى أداء جميع الطلبة.', NULL, ARRAY[141,142]),
  ('3.2.3', 3, 4, 'يتم متابعة وتحليل تقدم الطلبة ذوي الإعاقة بشكلٍ فعال لتقييم مدى فعالية الدعم المقدم، ويتم إجراء التعديلات اللازمة على الخطط بناءً على نتائج التقييم والمتابعة، مما أسهم في تحقيق تحسناً ملحوظاً في مستوى أداء الغالبية العظمى من الطلبة.', NULL, ARRAY[141,142]),
  ('3.2.3', 3, 3, 'يتم متابعة وتحليل تقدم الطلبة ذوي الإعاقة بشكلٍ مناسب لتقييم مدى فعالية الدعم المقدم، ويتم إجراء التعديلات على الخطط بناءً على نتائج التقييم والمتابعة، مما أسهم في تحقيق تحسناً في مستوى أداء معظم الطلبة.', NULL, ARRAY[141,142]),
  ('3.2.3', 3, 2, 'يتم متابعة تقدم الطلبة ذوي الإعاقة بشكلٍ محدود لتقييم مدى فعالية الدعم المقدم، وتظهر نتائج المتابعة تحسناً في مستوى أداء بعض الطلبة.', NULL, ARRAY[141,142]),
  ('3.2.3', 3, 1, 'يتم متابعة تقدم الطلبة ذوي الإعاقة بشكلٍ محدود جداً لتقييم مدى فعالية الدعم المقدم، وتظهر نتائج المتابعة تحسناً في مستوى أداء قلة من الطلبة.
أو
لا تتم متابعة وتحليل تقدم الطلبة ذوي الإعاقة.', NULL, ARRAY[141,142]),
  ('3.2.4', 1, 5, 'تطبيق تقييمات شاملة وفعالة جداً لتحديد نوع وشدة صعوبات التعلم واحتياجات الطلبة الفردية باستخدام أدوات تقييم متنوعة ودقيقة، مما أدى إلى تشخيص وحصر شامل ودقيق لجميع حالات صعوبات التعلم.', NULL, ARRAY[142]),
  ('3.2.4', 1, 4, 'تطبيق تقييمات فعالة لتحديد نوع وشدة صعوبات التعلم واحتياجات الطلبة الفردية باستخدام أدوات تقييم متنوعة، مما أدى إلى تشخيص وحصر للغالبية العظمى من حالات صعوبات التعلم.', NULL, ARRAY[142]),
  ('3.2.4', 1, 3, 'تطبيق تقييمات لتحديد نوع وشدة صعوبات التعلم باستخدام أدوات تقييم متنوعة، مما أدى إلى تشخيص وحصر معظم حالات صعوبات التعلم.', NULL, ARRAY[142]),
  ('3.2.4', 1, 2, 'تطبيق تقييمات لتحديد حالات صعوبات التعلم باستخدام أدوات تقييم محدودة، مما أدى إلى تشخيص وحصر بعض الحالات.', NULL, ARRAY[142]),
  ('3.2.4', 1, 1, 'تطبيق تقييمات لتحديد حالات صعوبات التعلم باستخدام أدوات تقييم محدودة جداً، مما أدى إلى حصر قلة من الحالات.
أو
لا يتم تطبيق تقييمات لتحديد حالات الطلبة ذوي صعوبات التعلم.', NULL, ARRAY[142]),
  ('3.2.4', 2, 5, 'يتم إعداد وتنفيذ خطط تعليمية فردية شاملة وذات جودة عالية، تتضمن أهداف تعليمية واضحة، وتتناسب مع احتياجات جميع الطلبة ذوي صعوبات التعلم، ويتم تقديم الدعم من خلال توفير موارد بشرية مؤهلة تأهيلاً عالياً وأدوات تعليمية مخصصة تتناسب مع حالات الصعوبات.', NULL, ARRAY[142]),
  ('3.2.4', 2, 4, 'يتم إعداد وتنفيذ خطط تعليمية فردية ذات جودة، تتضمن أهداف تعليمية تتناسب مع احتياجات الغالبية العظمى من الطلبة ذوي صعوبات التعلم، ويتم تقديم الدعم من خلال توفير موارد بشرية مؤهلة وموارد تعليمية تتناسب مع حالات الصعوبات.', NULL, ARRAY[142]),
  ('3.2.4', 2, 3, 'يتم إعداد وتنفيذ خطط تعليمية فردية مناسبة، تتضمن أهداف تعليمية تتناسب مع احتياجات معظم الطلبة ذوي صعوبات التعلم، ويتم تقديم الدعم للطلبة من خلال توفير موارد بشرية مؤهلة وموارد تعليمية تتناسب مع حالات الصعوبات.', NULL, ARRAY[142]),
  ('3.2.4', 2, 2, 'يتم إعداد وتنفيذ خطط تعليمية تتناسب مع احتياجات بعض الطلبة ذوي صعوبات التعلم، ويتم تقديم الدعم للطلبة بشكلٍ محدود من حيث الشمول أو الفاعلية.', NULL, ARRAY[142]),
  ('3.2.4', 2, 1, 'يتم إعداد وتنفيذ خطط تعليمية تتناسب مع احتياجات قلة من الطلبة ذوي صعوبات التعلم، ويتم تقديم الدعم للطلبة بشكلٍ محدود جداً من حيث الشمول أو الفاعلية.
أو
لا يتم إعداد خطط تعليمية للطلبة ذوي صعوبات التعلم.', NULL, ARRAY[142]),
  ('3.2.4', 3, 5, 'يتم متابعة وتحليل تقدم الطلبة ذوي صعوبات التعلم بشكلٍ منتظم وفعال جداً لتقييم مدى فعالية الدعم المقدم، وتحديد التغيرات في الاحتياجات التعليمية، ويتم إجراء التعديلات اللازمة على الخطط بناءً على نتائج التقييم والمتابعة، مما أسهم في تحقيق تحسناً ملحوظاً في مستوى أداء جميع الطلبة.', NULL, ARRAY[143]),
  ('3.2.4', 3, 4, 'يتم متابعة وتحليل تقدم الطلبة ذوي صعوبات التعلم بشكلٍ فعال لتقييم مدى فعالية الدعم المقدم، ويتم إجراء التعديلات اللازمة على الخطط بناءً على نتائج التقييم والمتابعة، مما أسهم في تحقيق تحسناً ملحوظاً في مستوى أداء الغالبية العظمى من الطلبة.', NULL, ARRAY[143]),
  ('3.2.4', 3, 3, 'يتم متابعة وتحليل تقدم الطلبة ذوي صعوبات التعلم بشكلٍ مناسب لتقييم مدى فعالية الدعم المقدم، ويتم إجراء تعديلات مناسبة على الخطط بناءً على نتائج التقييم والمتابعة، مما أسهم في تحقيق تحسناً ملحوظاً في مستوى أداء معظم الطلبة.', NULL, ARRAY[143]),
  ('3.2.4', 3, 2, 'يتم متابعة تقدم الطلبة ذوي صعوبات التعلم بشكلٍ محدود لتقييم مدى فعالية الدعم المقدم، وتظهر نتائج المتابعة تحسناً في مستوى أداء بعض الطلبة.', NULL, ARRAY[143]),
  ('3.2.4', 3, 1, 'يتم متابعة تقدم الطلبة ذوي صعوبات التعلم بشكلٍ محدود جداً، وتظهر نتائج المتابعة تحسناً في مستوى أداء قلة من الطلبة.
أو
لا يتم متابعة وتحليل تقدم الطلبة ذوي صعوبات التعلم.', NULL, ARRAY[143]),
  ('3.2.5', 1, 5, 'يتم إجراء تقييم دقيق لقياس مهارات الطلبة اللغوية، وإعداد وتنفيذ خطط تعليمية شاملة ذات جودة عالية، مع توظيف تقنيات وموارد تعليمية متخصصة ومتنوعة، وتقديم الدعم بشكلٍ فعال جداً لجميع الطلبة وفقاً لاحتياجاتهم ومستوياتهم، وبما يسهم في تحسين تحصيلهم في اللغات.', NULL, ARRAY[144]),
  ('3.2.5', 1, 4, 'يتم إجراء تقييم دقيق لقياس مهارات الطلبة اللغوية، وإعداد وتنفيذ خطط تعليمية ذات جودة، مع توظيف تقنيات وموارد تعليمية متخصصة، وتقديم الدعم بشكلٍ فعال للغالبية العظمى من الطلبة وفقاً لاحتياجاتهم ومستوياتهم، وبما يسهم في تحسين تحصيلهم في اللغات.', NULL, ARRAY[144]),
  ('3.2.5', 1, 3, 'يتم إجراء تقييم لقياس مهارات الطلبة اللغوية، وإعداد وتنفيذ خطط تعليمية، مع توظيف تقنيات وموارد تعليمية متخصصة، وتقديم الدعم بشكلٍ مناسب لمعظم الطلبة وفقاً لاحتياجاتهم ومستوياتهم، وبما يسهم في تحسين تحصيلهم في اللغات.', NULL, ARRAY[144]),
  ('3.2.5', 1, 2, 'يتم إجراء تقييم لقياس مهارات الطلبة اللغوية، وإعداد خطط تعليمية، إلا أن تنفيذها محدود، حيث يقتصر تقديم الدعم على بعض الطلبة، مما يؤثر على تحسين تحصيل الطلبة في اللغات.
أو
يتم إجراء تقييم لقياس مهارات الطلبة اللغوية، إلا أن تقديم الدعم للطلبة يتم من خلال خطة تراعي احتياجاتهم ومستوياتهم بشكلٍ محدود، مما يؤثر على تحسين تحصيلهم في اللغات.', NULL, ARRAY[144]),
  ('3.2.5', 1, 1, 'يتم قياس مهارات الطلبة اللغوية، وإعداد خطط تعليمية، إلا أن تنفيذها محدود جداً، حيث يقتصر تقديم الدعم على قلة من الطلبة، مما يؤثر سلباً على تحسين تحصيل الطلبة في اللغات.
أو
لا يتم إجراء تقييم لقياس مهارات الطلبة اللغوية، مما أثر سلباً على تقديم الدعم للطلبة لتحسين تحصيلهم في اللغات.
أو
لا يتم إعداد خطط تعليمية لتحسين مهارات الطلبة اللغوية.', NULL, ARRAY[144]),
  ('3.2.5', 2, 5, 'يتم متابعة تطور مهارات الطلبة اللغوية وتحديد مدى تقدمهم باستخدام أدوات تقييم متنوعة ودقيقة، ويتم تحليل البيانات بشكلٍ شامل ودقيق، والاستفادة منها في تقييم فعالية الخطط والتعديل عليها، وتظهر نتائج التقييم والمتابعة تحسناً ملحوظاً في مستوى المهارات اللغوية لدى جميع الطلبة.', NULL, ARRAY[144,145]),
  ('3.2.5', 2, 4, 'يتم متابعة تطور مهارات الطلبة اللغوية باستخدام أدوات تقييم متنوعة، ويتم تحليل البيانات بشكلٍ دقيق، والاستفادة منها في تقييم فعالية الخطط والتعديل عليها، وتظهر نتائج التقييم والمتابعة تحسناً ملحوظاً في مستوى المهارات اللغوية لدى الغالبية العظمى من الطلبة.', NULL, ARRAY[144,145]),
  ('3.2.5', 2, 3, 'يتم متابعة تطور مهارات الطلبة اللغوية باستخدام أدوات تقييم متنوعة، ويتم تحليل البيانات بشكلٍ دقيق، والاستفادة منها في تقييم فعالية الخطط والتعديل عليها، وتظهر نتائج التقييم والمتابعة تحسناً في مستوى المهارات اللغوية لدى معظم الطلبة.', NULL, ARRAY[144,145]),
  ('3.2.5', 2, 2, 'يتم متابعة تطور مهارات الطلبة اللغوية، وتظهر نتائج التقييم والمتابعة تحسناً في مستوى المهارات اللغوية لدى بعض الطلبة.', NULL, ARRAY[144,145]),
  ('3.2.5', 2, 1, 'يتم متابعة تطور مهارات الطلبة اللغوية، وتظهر نتائج التقييم والمتابعة تحسناً في مستوى المهارات اللغوية لدى قلة من الطلبة.
أو
لا يتم متابعة تطور المهارات اللغوية لدى الطلبة.', NULL, ARRAY[144,145]),
  ('3.2.6', 1, 5, 'يتم إعداد وتنفيذ خطة إرشاد أكاديمي ومهني واضحة وشاملة ومعلنة، تشتمل على برامج إرشاد متنوعة تلبي احتياجات جميع الطلبة، وتسهم بشكلٍ فعال جداً في تمكينهم من تخطيط مساراتهم الأكاديمية والمهنية المستقبلية، وتعزيز قدراتهم لضمان جاهزيتهم للالتحاق بالجامعات وسوق العمل.', NULL, ARRAY[145]),
  ('3.2.6', 1, 4, 'يتم إعداد وتنفيذ خطة إرشاد أكاديمي ومهني واضحة ومعلنة، تشتمل على برامج إرشاد متنوعة تلبي احتياجات الغالبية العظمى من الطلبة، وتسهم بشكلٍ فعال في تمكينهم من تخطيط مساراتهم الأكاديمية والمهنية المستقبلية، وتعزيز قدراتهم للالتحاق بالجامعات وسوق العمل.', NULL, ARRAY[145]),
  ('3.2.6', 1, 3, 'يتم إعداد وتنفيذ خطة إرشاد أكاديمي ومهني مناسبة، تشتمل على برامج إرشاد تلبي احتياجات معظم الطلبة، وتسهم بشكلٍ مناسب في تمكينهم من تخطيط مساراتهم الأكاديمية والمهنية المستقبلية.', NULL, ARRAY[145]),
  ('3.2.6', 1, 2, 'يتم إعداد وتنفيذ خطة للإرشاد الأكاديمي والمهني تلبي احتياجات بعض الطلبة، مما يسهم بشكلٍ محدود في تمكينهم من تخطيط مساراتهم الأكاديمية والمهنية المستقبلية.', NULL, ARRAY[145]),
  ('3.2.6', 1, 1, 'يتم إعداد وتنفيذ خطة للإرشاد الأكاديمي والمهني تلبي احتياجات قلة من الطلبة، مما يسهم بشكلٍ محدود جداً في تمكينهم من تخطيط مساراتهم الأكاديمية والمهنية المستقبلية.
أو
لا يتم إعداد خطة للإرشاد الأكاديمي والمهني.
أو
لا يتم تنفيذ برامج للإرشاد الأكاديمي والمهني للطلبة.', NULL, ARRAY[145]),
  ('3.2.6', 2, 5, 'يتم توفير خيارات متنوعة من المواد الدراسية تتماشى بشكلٍ كامل مع الاهتمامات الأكاديمية والمهنية لجميع الطلبة، ويتم تحديثها بشكلٍ منتظم لضمان توافقها مع اهتمامات الطلبة، مما يسهم في تأهيلهم للالتحاق بالجامعات بشكلٍ فعال جداً.', NULL, ARRAY[145,146]),
  ('3.2.6', 2, 4, 'يتم توفير خيارات متنوعة من المواد الدراسية تتماشى مع الاهتمامات الأكاديمية والمهنية للغالبية العظمى من الطلبة، مما يسهم في تأهيلهم للالتحاق بالجامعات بشكلٍ فعال.', NULL, ARRAY[145,146]),
  ('3.2.6', 2, 3, 'يتم توفير خيارات من المواد الدراسية تتماشى مع الاهتمامات الأكاديمية والمهنية لمعظم الطلبة، مما يسهم في تأهيلهم للالتحاق بالجامعات بشكلٍ مناسب.', NULL, ARRAY[145,146]),
  ('3.2.6', 2, 2, 'يتم توفير خيارات من المواد الدراسية تتماشى مع اهتمامات بعض الطلبة، مما يسهم في تأهيلهم للالتحاق بالجامعات بشكلٍ محدود.', NULL, ARRAY[145,146]),
  ('3.2.6', 2, 1, 'يتم توفير خيارات من المواد الدراسية تتماشى مع اهتمامات قلة من الطلبة، مما يسهم في تأهيلهم للالتحاق بالجامعات بشكلٍ محدود جداً.', NULL, ARRAY[145,146]),
  ('3.2.7', 1, 5, 'تُطبق المدرسة إجراءات تشخيص وإحالة واضحة وشاملة ودقيقة، تضمن تحديد وإحالة جميع الطلبة الذين بحاجة إلى خدمات الإرشاد النفسي بناءً على احتياجاتهم الفردية.', NULL, ARRAY[146]),
  ('3.2.7', 1, 4, 'تُطبق المدرسة إجراءات تشخيص وإحالة واضحة، تضمن تحديد وإحالة الغالبية العظمى من الطلبة الذين بحاجة إلى خدمات الإرشاد النفسي.', NULL, ARRAY[146]),
  ('3.2.7', 1, 3, 'تُطبق المدرسة إجراءات تشخيص وإحالة مناسبة تضمن تحديد وإحالة معظم الطلبة الذين بحاجة إلى خدمات الإرشاد النفسي.', NULL, ARRAY[146]),
  ('3.2.7', 1, 2, 'تُطبق المدرسة إجراءات محدودة لتشخيص وإحالة الطلبة الذين بحاجة إلى خدمات الإرشاد النفسي، مما أدى إلى تحديد وإحالة بعض الطلبة الذين بحاجة إلى خدمات الإرشاد النفسي.', NULL, ARRAY[146]),
  ('3.2.7', 1, 1, 'تُطبق المدرسة إجراءات محدودة جداً لتشخيص وإحالة الطلبة الذين بحاجة إلى خدمات الإرشاد النفسي، مما أدى إلى تحديد وإحالة قلة من الطلبة الذين بحاجة إلى خدمات الإرشاد النفسي.
أو
إجراءات التشخيص والإحالة للطلبة غير واضحة، ولا تضمن تحديد الطلبة الذين بحاجة إلى خدمات الإرشاد والدعم النفسي.', NULL, ARRAY[146]),
  ('3.2.7', 2, 5, 'تقوم المدرسة بإعداد وتنفيذ خطط وبرامج وأنشطة شاملة وفعالة جداً ومستمرة، لتقديم الدعم النفسي لجميع الطلبة الذين بحاجة إلى خدمات الدعم النفسي بناءً على احتياجاتهم الفردية، وذلك من خلال موظفين متخصصين ومؤهلين، ويتم التعاون مع أولياء الأمور والمؤسسات المختصة لتوفير الدعم المتكامل والمستدام، كما يتم تقييم فعالية الخطط والبرامج وتحديثها بشكلٍ شامل ومستمر.', NULL, ARRAY[146,147]),
  ('3.2.7', 2, 4, 'تقوم المدرسة بإعداد وتنفيذ خطط وبرامج وأنشطة فعالة ومستمرة، لتقديم الدعم النفسي للغالبية العظمى من الطلبة الذين بحاجة إلى خدمات الدعم النفسي، وذلك من خلال موظفين متخصصين ومؤهلين، ويتم التعاون مع أولياء الأمور والمؤسسات المختصة لتوفير الدعم المتكامل، كما يتم تقييم فعالية الخطط والبرامج وتحديثها بشكلٍ مستمر.', NULL, ARRAY[146,147]),
  ('3.2.7', 2, 3, 'تقوم المدرسة بإعداد وتنفيذ خطط وبرامج وأنشطة مناسبة، لتقديم الدعم النفسي لمعظم الطلبة الذين بحاجة إلى خدمات الدعم النفسي، وذلك من خلال موظفين متخصصين ومؤهلين، ويتم التعاون مع أولياء الأمور / المؤسسات المختصة لتوفير الدعم، ويتم مراجعة الخطط والبرامج وتحديثها بشكل مناسب.', NULL, ARRAY[146,147]),
  ('3.2.7', 2, 2, 'تقوم المدرسة بإعداد وتنفيذ خطط / برامج لتقديم الدعم النفسي لبعض الطلبة الذين بحاجة إلى خدمات الدعم النفسي.
أو
تقوم المدرسة بإعداد وتنفيذ خطط وبرامج محدودة لتقديم الدعم النفسي للطلبة.', NULL, ARRAY[146,147]),
  ('3.2.7', 2, 1, 'تقوم المدرسة بتنفيذ خطط / برامج لتقديم الدعم النفسي لقلة من الطلبة الذين بحاجة إلى خدمات الدعم النفسي.
أو
لا تقوم المدرسة بإعداد خطط وبرامج لتقديم الدعم النفسي للطلبة.
أو
لا يتم تقديم الدعم للطلبة من خلال موظفين متخصصين ومؤهلين.', NULL, ARRAY[146,147]),
  ('3.2.7', 3, 5, 'يتم تقديم برامج وورش توعوية ووقائية شاملة وفعالة جداً ومستمرة للطلبة، لتعزيز الصحة النفسية والوقاية من المشكلات النفسية المحتملة، في جميع الصفوف / المراحل الدراسية، ويتم التعاون مع جهات مجتمعية متخصصة لضمان تقديم الدعم الفعال وتوفير البيئة التعليمية الداعمة.', NULL, ARRAY[147]),
  ('3.2.7', 3, 4, 'يتم تقديم برامج وورش توعوية فعالة ومستمرة للطلبة، لتعزيز الصحة النفسية والوقاية من المشكلات النفسية المحتملة، في الغالبية العظمى من الصفوف / المراحل الدراسية، ويتم التعاون مع جهات مجتمعية لضمان تقديم الدعم وتوفير البيئة التعليمية الداعمة.', NULL, ARRAY[147]),
  ('3.2.7', 3, 3, 'يتم تقديم برامج وورش توعوية للطلبة لتعزيز الصحة النفسية والوقاية من المشكلات النفسية المحتملة في معظم الصفوف / المراحل الدراسية.', NULL, ARRAY[147]),
  ('3.2.7', 3, 2, 'يتم تقديم برامج وورش توعوية للطلبة لتعزيز الصحة النفسية والوقاية من المشكلات النفسية المحتملة في بعض الصفوف / المراحل الدراسية.', NULL, ARRAY[147]),
  ('3.2.7', 3, 1, 'يتم تقديم ورش توعوية للطلبة لتعزيز الصحة النفسية والوقاية من المشكلات النفسية المحتملة في قلة من الصفوف / المراحل الدراسية.
أو
لا يتم تقديم برامج وورش توعوية للطلبة لتعزيز الصحة النفسية والوقاية من المشكلات النفسية المحتملة.', NULL, ARRAY[147]),
  ('3.2.8', 1, 5, 'يتم تطبيق إجراءات تشخيص شاملة وواضحة ودقيقة، لتحديد وإحالة جميع الطلبة الذين بحاجة إلى خدمات الدعم والإرشاد الاجتماعي بناءً على احتياجاتهم الفردية.', NULL, ARRAY[148]),
  ('3.2.8', 1, 4, 'يتم تطبيق إجراءات تشخيص واضحة ودقيقة، لتحديد وإحالة الغالبية العظمى من الطلبة الذين بحاجة إلى خدمات الدعم والإرشاد الاجتماعي.', NULL, ARRAY[148]),
  ('3.2.8', 1, 3, 'يتم تطبيق إجراءات تشخيص واضحة لتحديد وإحالة معظم الطلبة الذين بحاجة إلى خدمات الدعم والإرشاد الاجتماعي.', NULL, ARRAY[148]),
  ('3.2.8', 1, 2, 'يتم تطبيق إجراءات محدودة لتحديد الطلبة الذين بحاجة إلى خدمات الدعم والإرشاد الاجتماعي، ويتم تحديد وإحالة بعض الطلبة الذين بحاجة إلى دعم.', NULL, ARRAY[148]),
  ('3.2.8', 1, 1, 'يتم تطبيق إجراءات محدودة جداً لتحديد الطلبة الذين بحاجة إلى خدمات الدعم والإرشاد الاجتماعي، ويتم تحديد وإحالة قلة من الطلبة الذين بحاجة إلى دعم.
أو
لا يتم تطبيق إجراءات واضحة لتحديد وإحالة الطلبة الذين بحاجة إلى خدمات الدعم والإرشاد الاجتماعي.', NULL, ARRAY[148]),
  ('3.2.8', 2, 5, 'يتم إعداد وتنفيذ خطط وبرامج دعم اجتماعي شاملة وفعالة جداً ومستمرة، لتقديم الدعم والإرشاد الاجتماعي لجميع الطلبة بناءً على احتياجاتهم الفردية، من قبل موظفين مؤهلين وبالتعاون مع أولياء الأمور والجهات المختصة، لتوفير الدعم الاجتماعي المتكامل، ويتم تقييم الخطط والبرامج بشكلٍ شامل ومستمر لقياس أثرها والتعديل عليها لضمان فعاليتها.', NULL, ARRAY[148,149]),
  ('3.2.8', 2, 4, 'يتم إعداد وتنفيذ خطط وبرامج دعم اجتماعي فعالة ومستمرة، لتقديم الدعم والإرشاد الاجتماعي للغالبية العظمى من الطلبة بناءً على احتياجاتهم الفردية، من قبل موظفين مؤهلين وبالتعاون مع أولياء الأمور والجهات المختصة، لتوفير الدعم الاجتماعي المتكامل، ويتم تقييم الخطط والبرامج بشكلٍ مستمر لقياس أثرها والتعديل عليها لضمان فعاليتها.', NULL, ARRAY[148,149]),
  ('3.2.8', 2, 3, 'يتم إعداد وتنفيذ خطط وبرامج دعم اجتماعي مناسبة، لتقديم الدعم والإرشاد الاجتماعي لمعظم الطلبة بناءً على احتياجاتهم الفردية، من قبل موظفين مؤهلين وبالتعاون مع أولياء الأمور / الجهات المختصة، لتوفير الدعم الاجتماعي، ويتم مراجعة الخطط والبرامج والتعديل عليها بشكلٍ مناسب.', NULL, ARRAY[148,149]),
  ('3.2.8', 2, 2, 'يتم إعداد وتنفيذ خطط وبرامج لتقديم الدعم والإرشاد الاجتماعي لبعض الطلبة.
أو
يتم إعداد وتنفيذ خطط وبرامج محدودة لتقديم الدعم والإرشاد الاجتماعي للطلبة.', NULL, ARRAY[148,149]),
  ('3.2.8', 2, 1, 'يتم إعداد وتنفيذ خطط وبرامج لتقديم الدعم والإرشاد الاجتماعي لقلة من الطلبة.
أو
لا يتم إعداد وتنفيذ خطط وبرامج لتقديم الدعم والإرشاد الاجتماعي للطلبة.', NULL, ARRAY[148,149]),
  ('3.2.8', 3, 5, 'يتم تنظيم ورش وحملات توعية للطلبة بشكلٍ منتظم في جميع المراحل / الصفوف الدراسية، لتعزيز الوعي الاجتماعي وتغطية قضايا اجتماعية متنوعة، مما يسهم بشكلٍ فعال جداً في تطوير مهارات التفاعل الإيجابي بين الطلبة.', NULL, ARRAY[149]),
  ('3.2.8', 3, 4, 'يتم تنظيم ورش وحملات توعية للطلبة بشكلٍ منتظم في الغالبية العظمى من المراحل / الصفوف الدراسية، لتعزيز الوعي الاجتماعي وتغطية قضايا اجتماعية متنوعة، مما يسهم بشكلٍ فعال في تطوير مهارات التفاعل الإيجابي بين الطلبة.', NULL, ARRAY[149]),
  ('3.2.8', 3, 3, 'يتم تنظيم ورش وحملات توعية للطلبة في معظم المراحل / الصفوف الدراسية، لتعزيز الوعي الاجتماعي لديهم، مما يسهم بشكلٍ مناسب في تطوير مهارات التفاعل الإيجابي بين الطلبة.', NULL, ARRAY[149]),
  ('3.2.8', 3, 2, 'يتم تنظيم ورش وحملات توعية للطلبة في بعض المراحل / الصفوف الدراسية، لتعزيز الوعي الاجتماعي لديهم، مما يسهم بشكلٍ محدود في تطوير مهارات التفاعل الإيجابي بين الطلبة.', NULL, ARRAY[149]),
  ('3.2.8', 3, 1, 'يتم تنظيم ورش وحملات توعية للطلبة في قلة من المراحل / الصفوف الدراسية، لتعزيز الوعي الاجتماعي لديهم، مما يسهم بشكلٍ محدود جداً في تطوير مهارات التفاعل الإيجابي بين الطلبة.
أو
لا يتم تنظيم ورش وحملات توعية للطلبة لتعزيز الوعي الاجتماعي لديهم.', NULL, ARRAY[149]),
  ('4.1.1', 1, 5, 'يتم إعداد سياسة سلوك شاملة وواضحة تتضمن قواعد سلوك محددة، وتغطي جميع جوانب السلوك المدرسي، بما في ذلك السلوك داخل الصفوف الدراسية والمرافق المدرسية المختلفة، وتتناسب إجراءات السياسة مع المراحل العمرية المختلفة، وتتوافق مع القيم الإسلامية والوطنية.', NULL, ARRAY[159]),
  ('4.1.1', 1, 4, 'يتم إعداد سياسة سلوك واضحة تتضمن قواعد سلوك محددة، وتغطي الغالبية العظمى من جوانب السلوك المدرسي، بما في ذلك السلوك داخل الصفوف الدراسية والمرافق المدرسية المختلفة، وتتوافق السياسة مع القيم الإسلامية والوطنية.', NULL, ARRAY[159]),
  ('4.1.1', 1, 3, 'يتم إعداد سياسة سلوك واضحة تتضمن قواعد سلوك محددة، وتغطي معظم جوانب السلوك المدرسي، وتتوافق السياسة مع القيم الإسلامية والوطنية.', NULL, ARRAY[159]),
  ('4.1.1', 1, 2, 'يتم إعداد سياسة سلوك تفتقر إلى الشمولية، حيث تغطي بعض جوانب السلوك المدرسي.', NULL, ARRAY[159]),
  ('4.1.1', 1, 1, 'يتم إعداد سياسة سلوك غير واضحة، تتضمن قواعد سلوك محدودة جداً، وتغطي قلة من جوانب السلوك المدرسي.
أو
لا يتم إعداد سياسة سلوك.', NULL, ARRAY[159]),
  ('4.1.1', 2, 5, 'يتم تنفيذ سياسة السلوك بشكلٍ فعال جداً وبعدالة ومساواة كاملة بين الطلبة، مما يسهم في توفير بيئة تعليمية آمنة ومحفزة في جميع الصفوف الدراسية والمرافق المدرسية.', NULL, ARRAY[159]),
  ('4.1.1', 2, 4, 'يتم تنفيذ سياسة السلوك بشكلٍ فعال وبعدالة بين الطلبة، مما يسهم في توفير بيئة تعليمية آمنة ومحفزة في الغالبية العظمى من الصفوف الدراسية والمرافق المدرسية.', NULL, ARRAY[159]),
  ('4.1.1', 2, 3, 'يتم تنفيذ سياسة السلوك بشكلٍ مناسب بين الطلبة، مما يسهم في توفير بيئة تعليمية آمنة ومحفزة في معظم الصفوف الدراسية والمرافق المدرسية.', NULL, ARRAY[159]),
  ('4.1.1', 2, 2, 'يتم تنفيذ سياسة السلوك بشكلٍ محدود أو غير متسق، مما أدى إلى توفير بيئة تعليمية آمنة ومحفزة في بعض الصفوف الدراسية والمرافق المدرسية.', NULL, ARRAY[159]),
  ('4.1.1', 2, 1, 'يتم الالتزام بتنفيذ سياسة السلوك بشكل محدود جداً، مما أدى إلى توفير بيئة تعليمية آمنة ومحفزة في قلة من الصفوف الدراسية والمرافق المدرسية.', NULL, ARRAY[159]),
  ('4.1.1', 3, 5, 'يتم إعداد وتنفيذ برامج وأنشطة سلوكية شاملة ومتنوعة وفعالة جداً تعزز السلوك الإيجابي وتحد من السلوك السلبي، مع متابعة التنفيذ وتقييم دوري لمدى فاعليتها، مما يسهم في التزام جميع الطلبة بالسلوك الإيجابي داخل المدرسة، واحترامهم للقوانين المدرسية، وانضباطهم العام.', NULL, ARRAY[159,160]),
  ('4.1.1', 3, 4, 'يتم إعداد وتنفيذ برامج وأنشطة متنوعة وفعالة تعزز السلوك الإيجابي وتحد من السلوك السلبي، مع متابعة التنفيذ وتقييم لمدى فاعليتها، مما يسهم في التزام الغالبية العظمى من الطلبة بالسلوك الإيجابي داخل المدرسة، واحترامهم للقوانين المدرسية.', NULL, ARRAY[159,160]),
  ('4.1.1', 3, 3, 'يتم إعداد وتنفيذ برامج وأنشطة مناسبة تعزز السلوك الإيجابي وتحد من السلوك السلبي، مع متابعة التنفيذ، مما يسهم في التزام معظم الطلبة بالسلوك الإيجابي داخل المدرسة.', NULL, ARRAY[159,160]),
  ('4.1.1', 3, 2, 'يتم إعداد وتنفيذ برامج وأنشطة محدودة لتعزيز السلوك الإيجابي والحد من السلوك السلبي، مما أدى إلى التزام بعض الطلبة بالسلوك الإيجابي داخل المدرسة.
أو
يلتزم الطلبة بالسلوك الإيجابي داخل المدرسة بدرجة مقبولة، إلا أن دور المدرسة في تعزيز هذا السلوك لا يزال محدودًا؛ حيث يتم إعداد وتنفيذ برامج وأنشطة محدودة وغير منتظمة تهدف إلى تعزيز السلوك الإيجابي والحد من السلوك السلبي، مما يؤدي إلى تأثير جزئي وغير مستدام على سلوك الطلبة داخل البيئة المدرسية.', NULL, ARRAY[159,160]),
  ('4.1.1', 3, 1, 'يتم إعداد وتنفيذ أنشطة محدودة جداً لتعزيز السلوك الإيجابي والحد من السلوك السلبي، مما أدى إلى التزام قلة من الطلبة بالسلوك الإيجابي داخل المدرسة.
أو
لا يتم إعداد وتنفيذ أنشطة وبرامج لتعزيز السلوك الإيجابي والحد من السلوك السلبي، مما أثر سلباً على سلوك الطلبة داخل المدرسة.', NULL, ARRAY[159,160]),
  ('4.1.1', 4, 5, 'تُطبق المدرسة إجراءات واضحة ومحددة لحصر ومتابعة الحالات والمشاكل السلوكية، ووضع وتنفيذ حلول فعالة جداً، ومُتابعتها بشكلٍ مستمر، مما ساهم في معالجة وتحسن جميع الحالات السلوكية داخل المدرسة.', NULL, ARRAY[160,161]),
  ('4.1.1', 4, 4, 'تُطبق المدرسة إجراءات واضحة ومحددة لحصر ومتابعة الحالات والمشاكل السلوكية، ووضع وتنفيذ حلول فعالة، ومُتابعتها، مما ساهم في تحسين الغالبية العظمى من الحالات السلوكية داخل المدرسة.', NULL, ARRAY[160,161]),
  ('4.1.1', 4, 3, 'تُطبق المدرسة إجراءات واضحة لحصر ومتابعة الحالات والمشاكل السلوكية، ووضع وتنفيذ حلول مناسبة لها، ومُتابعتها مما ساهم في تحسين معظم الحالات السلوكية داخل المدرسة.', NULL, ARRAY[160,161]),
  ('4.1.1', 4, 2, 'تُطبق المدرسة إجراءات محدودة لحصر ومتابعة الحالات والمشاكل السلوكية، ووضع وتنفيذ حلول ساهمت في معالجة بعض هذه الحالات.
أو
تُطبق المدرسة إجراءات لحصر ومتابعة الحالات والمشاكل السلوكية، إلا أنه يتم وضع وتنفيذ حلول محدودة لهذه الحالات.', NULL, ARRAY[160,161]),
  ('4.1.1', 4, 1, 'تُطبق المدرسة إجراءات محدودة جداً لحصر ومتابعة الحالات والمشاكل السلوكية، ووضع وتنفيذ حلول محدودة جداً ساهمت في معالجة قلة من هذه الحالات.
أو
لا يتم حصر ومتابعة الحالات والمشاكل السلوكية.
أو
يتم حصر الحالات السلوكية ولكن لا تتم معالجتها.', NULL, ARRAY[160,161]),
  ('4.1.1', 5, 5, 'تضع المدرسة وتنفذ سياسة لحماية الأطفال شاملة ومتكاملة، مدعومة بإجراءات واضحة ومفصلة، مع تطبيق مستمر وفعال جداً للسياسة، كما تتم مراجعة الإجراءات بشكلٍ دوري لضمان فاعليتها وتحديثها، وتوجد آليات لرصد المواقف التي قد تهدد سلامة الطلبة، مع التعامل معها بسرعة وكفاءة عالية، مما يضمن توفير بيئة آمنة تدعم رفاه جميع الطلبة.', NULL, ARRAY[161]),
  ('4.1.1', 5, 4, 'تضع المدرسة وتنفذ سياسة لحماية الأطفال شاملة، مدعومة بإجراءات واضحة، مع تطبيق مستمر وفعال للسياسة، كما تتم مراجعة الإجراءات بشكلٍ دوري لضمان فاعليتها وتحديثها، وتوجد آليات لرصد المواقف التي قد تهدد سلامة الطلبة، مع التعامل معها بسرعة، مما يضمن توفير بيئة آمنة تدعم رفاه الغالبية العظمى من الطلبة.', NULL, ARRAY[161]),
  ('4.1.1', 5, 3, 'تضع المدرسة وتنفذ سياسة لحماية الأطفال، مدعومة بإجراءات واضحة، مع تطبيق مناسب للسياسة، كما تتم مراجعة الإجراءات وتحديثها، وتوجد آليات لرصد المواقف التي قد تهدد سلامة الطلبة، مع التعامل معها بشكل مناسب مما يضمن توفير بيئة آمنة تدعم رفاه معظم الطلبة.', NULL, ARRAY[161]),
  ('4.1.1', 5, 2, 'تضع المدرسة سياسة لحماية الأطفال، إلا أن تنفيذها يتم بشكلٍ محدود، مما يؤثر على فاعلية توفير بيئة آمنة تدعم رفاه الطلبة بشكل أدى إلى توفير بيئة تدعم أمن ورفاه بعض الطلبة بشكل أدى إلى توفير بيئة تدعم أمن ورفاه بعض الطلبة.', NULL, ARRAY[161]),
  ('4.1.1', 5, 1, 'تضع المدرسة سياسة لحماية الأطفال، إلا أن تنفيذها يتم بشكل يدعم توفير بيئة أمنة لقلة من الطلبة.
أو
لا يوجد لدى المدرسة سياسة لحماية الأطفال.
أو
تضع المدرسة سياسة لحماية الأطفال، إلا أن إجراءات تنفيذ السياسة غير محددة أو غير واضحة.', NULL, ARRAY[161]),
  ('4.1.2', 1, 5, 'يُظهر جميع الموظفين السلوك الإيجابي والقدوة الحسنة، وتُحترم الثقافات المتنوعة في المدرسة، مما يسهم في بناء علاقات إيجابية بين الموظفين والطلبة، وبين الطلبة وبعضهم البعض بشكلٍ فعال جداً ومستمر.', NULL, ARRAY[161,162]),
  ('4.1.2', 1, 4, 'يُظهر الغالبية العظمى من الموظفين السلوك الإيجابي والقدوة الحسنة، وتُحترم الثقافات المتنوعة في المدرسة، مما يسهم في بناء علاقات إيجابية بين الموظفين والطلبة، وبين الطلبة وبعضهم البعض بشكلٍ فعال ومستمر.', NULL, ARRAY[161,162]),
  ('4.1.2', 1, 3, 'يُظهر معظم الموظفين السلوك الإيجابي والقدوة الحسنة، وتُحترم الثقافات المتنوعة في المدرسة، مما يسهم في بناء علاقات إيجابية بين الموظفين والطلبة، وبين الطلبة وبعضهم البعض بشكلٍ مناسب.', NULL, ARRAY[161,162]),
  ('4.1.2', 1, 2, 'يُظهر بعض الموظفين السلوك الإيجابي والقدوة الحسنة، مما أثر على بناء علاقات إيجابية بين الموظفين والطلبة.
أو
يُظهر الموظفون السلوك الإيجابي، إلا أنه يراعى احترام الثقافات المتنوعة في المدرسة بشكلٍ محدود، مما أثر على بناء علاقات إيجابية بين الموظفين والطلبة، وبين الطلبة وبعضهم البعض.', NULL, ARRAY[161,162]),
  ('4.1.2', 1, 1, 'يُظهر قلة من الموظفين سلوكاً إيجابياً وقدوة حسنة، مما أثر سلباً على بناء علاقات إيجابية بين الموظفين والطلبة.', NULL, ARRAY[161,162]),
  ('4.1.3', 1, 5, 'تتم متابعة حالات الغياب والتأخير لدى الطلبة بشكلٍ منتظم ودقيق، مع اتخاذ إجراءات وحلول فورية وفعالة جداً لمعالجة الأسباب وتحسين مستوى الحضور والانضباط، مما أدى إلى التزام جميع الطلبة بالحضور المنتظم والانضباط الكامل طوال اليوم الدراسي، وساهم في توفير بيئة تعليمية منظمة ومستقرة.', NULL, ARRAY[162,163]),
  ('4.1.3', 1, 4, 'تتم متابعة حالات الغياب والتأخير لدى الطلبة بشكلٍ منتظم، مع اتخاذ إجراءات وحلول فورية وفعالة لمعالجة الأسباب وتحسين مستوى الحضور والانضباط، مما أدى إلى التزام الغالبية العظمى من الطلبة بالحضور المنتظم والانضباط طوال اليوم الدراسي، مما يسهم في توفير بيئة تعليمية منظمة.', NULL, ARRAY[162,163]),
  ('4.1.3', 1, 3, 'تتم متابعة حالات الغياب والتأخير لدى الطلبة، مع اتخاذ إجراءات وحلول مناسبة لمعالجة الأسباب وتحسين مستوى الحضور والانضباط، مما أدى إلى التزام معظم الطلبة بالحضور المنتظم والانضباط طوال اليوم الدراسي.', NULL, ARRAY[162,163]),
  ('4.1.3', 1, 2, 'تتم متابعة حالات الغياب والتأخير لدى الطلبة، لكن يتم اتخاذ إجراءات محدودة لمعالجة الأسباب وتحسين مستوى الحضور والانضباط، مما أدى إلى التزام بعض الطلبة بالحضور المنتظم.
أو
تتم متابعة حالات الغياب والتأخير لدى الطلبة، واتخاذ إجراءات لتحسين الحضور والانضباط، إلا أن الالتزام بالحضور المنتظم لا يزال محدوداً، ويقتصر على بعض الطلبة.', NULL, ARRAY[162,163]),
  ('4.1.3', 1, 1, 'تتم متابعة حالات الغياب / التأخير لدى الطلبة، لكن يتم اتخاذ إجراءات محدودة جداً لمعالجة الأسباب وتحسين مستوى الحضور والانضباط، مما أدى إلى التزام قلة من الطلبة بالحضور المنتظم.
أو
لا تتم متابعة حالات الغياب والتأخير لدى الطلبة.', NULL, ARRAY[162,163]),
  ('4.1.4', 1, 5, 'تنفيذ برامج وأنشطة شاملة ومتنوعة تهدف إلى تعزيز نمو شخصية الطلبة وتطوير مهاراتهم القيادية، مع توفير بيئة تعليمية داعمة تسهم في بناء الثقة بالنفس، ويتم مشاركة جميع الطلبة بشكلٍ مستمر في هذه الأنشطة، مما يحقق أثراً فعالاً جداً في تنمية شخصياتهم وصقل مهاراتهم القيادية.', NULL, ARRAY[163]),
  ('4.1.4', 1, 4, 'تنفيذ برامج وأنشطة متنوعة تهدف إلى تعزيز نمو شخصية الطلبة وتطوير مهاراتهم القيادية، مع توفير بيئة تعليمية تسهم في بناء الثقة بالنفس، ويتم مشاركة الغالبية العظمى من الطلبة بشكلٍ مستمر في هذه الأنشطة، مما يحقق أثراً فعالاً في تنمية شخصياتهم وصقل مهاراتهم القيادية.', NULL, ARRAY[163]),
  ('4.1.4', 1, 3, 'تنفيذ برامج وأنشطة مناسبة تهدف إلى تعزيز نمو شخصية الطلبة وتطوير مهاراتهم القيادية، مع توفير بيئة تعليمية تسهم في بناء الثقة بالنفس، ويتم مشاركة معظم الطلبة في هذه الأنشطة، مما يحقق أثراً مناسباً في تنمية شخصية طلبة المدرسة ومهاراتهم القيادية.', NULL, ARRAY[163]),
  ('4.1.4', 1, 2, 'تنفيذ برامج وأنشطة لتعزيز نمو شخصية الطلبة وتطوير مهاراتهم القيادية، لكن يتم مشاركة بعض الطلبة في هذه الأنشطة مما يحقق أثراً محدوداً في تنمية الشخصية وصقل المهارات القيادية لدى طلبة المدرسة.
أو
تنفيذ برامج وأنشطة محدودة لتعزيز نمو شخصية الطلبة وتطوير مهاراتهم القيادية، مما أثر على تطوير هذه المهارات لديهم.
أو
يتم مشاركة كافة الطلبة في المدرسة في الأنشطة والبرامج الداعمة للشخصية والمهارات القيادية إلا أن أثرها انعكس بشكل محدود على الطلبة.', NULL, ARRAY[163]),
  ('4.1.4', 1, 1, 'تنفيذ برامج وأنشطة تهدف إلى تعزيز نمو شخصية الطلبة وتطوير مهاراتهم القيادية، لكن يتم مشاركة قلة من الطلبة في هذه الأنشطة، مما يحقق أثراً محدوداً جداً في تنمية الشخصية والمهارات القيادية لدى طلبة المدرسة..
أو
لا يتم تنفيذ برامج وأنشطة تهدف إلى تعزيز نمو شخصية الطلبة وتطوير مهاراتهم القيادية، مما أثر سلباً على تطوير هذه المهارات لديهم.', NULL, ARRAY[163]),
  ('4.1.4', 2, 5, 'يتم الاحتفاء بجميع إنجازات الطلبة بشكلٍ منتظم ومستمر، مع تقديم مكافآت تحفيزية متنوعة، وتنظيم فعاليات تكريمية لهم، مما يسهم بشكلٍ فعال جداً في تحفيزهم لتحقيق المزيد من التفوق والإنجازات.', NULL, ARRAY[164]),
  ('4.1.4', 2, 4, 'يتم الاحتفاء بالغالبية العظمى من إنجازات الطلبة بشكلٍ منتظم، مع تقديم مكافآت تحفيزية، وتنظيم فعاليات تكريمية لهم، مما يسهم بشكلٍ فعال في تحفيزهم على تحقيق المزيد من الإنجازات والتفوق.', NULL, ARRAY[164]),
  ('4.1.4', 2, 3, 'يتم الاحتفاء بمعظم إنجازات الطلبة بشكلٍ منتظم، مع تقديم مكافآت تحفيزية لهم، مما يسهم بشكلٍ مناسب في تحفيزهم على تحقيق المزيد من الإنجازات والتفوق.', NULL, ARRAY[164]),
  ('4.1.4', 2, 2, 'يتم الاحتفاء ببعض إنجازات الطلبة، وتقديم مكافآت تحفيزية لهم بشكلٍ غير منتظم، مما يسهم بشكلٍ محدود في تشجيعهم على تحقيق المزيد من الإنجاز.
أو
يتم الاحتفاء بإنجازات الطلبة، لكن يتم تقديم مكافآت تحفيزية محدودة وغير متنوعة، مما أثر على تحفيزهم على تحقيق المزيد من الإنجازات والتفوق.', NULL, ARRAY[164]),
  ('4.1.4', 2, 1, 'يتم الاحتفاء بقلة من إنجازات الطلبة، مما يسهم بشكلٍ محدود جداً في تشجيعهم على تحقيق المزيد من الإنجاز.
أو
لا يتم الاحتفاء بإنجازات الطلبة، أو تقديم مكافآت تحفيزية لهم.', NULL, ARRAY[164]),
  ('4.2.1', 1, 5, 'يتم إعداد وتنفيذ خطة شاملة تتضمن برامج وأنشطة وفعاليات مبتكرة ومتنوعة، لتعزيز القيم الإسلامية والهوية الوطنية والثقافة القطرية، وتشمل جميع الصفوف / المراحل الدراسية، مما يسهم بشكلٍ فعال جداً في ترسيخ القيم وتعزيز الهوية الوطنية والثقافة القطرية لدى الطلبة.', NULL, ARRAY[164,165]),
  ('4.2.1', 1, 4, 'يتم إعداد وتنفيذ خطة تتضمن برامج وأنشطة وفعاليات متنوعة، لتعزيز القيم الإسلامية والهوية الوطنية والثقافة القطرية، وتشمل الغالبية العظمى من الصفوف / المراحل الدراسية، مما يسهم بشكلٍ فعال في ترسيخ القيم وتعزيز الهوية الوطنية والثقافة القطرية لدى الطلبة.', NULL, ARRAY[164,165]),
  ('4.2.1', 1, 3, 'يتم إعداد وتنفيذ خطة تتضمن برامج وأنشطة وفعاليات لتعزيز القيم الإسلامية والهوية الوطنية والثقافة القطرية، تشمل معظم الصفوف / المراحل الدراسية، مما يسهم بشكلٍ مناسب في ترسيخ القيم وتعزيز الهوية الوطنية والثقافة القطرية.', NULL, ARRAY[164,165]),
  ('4.2.1', 1, 2, 'يتم تنفيذ خطة تتضمن أنشطة لتعزيز القيم الإسلامية والهوية الوطنية والثقافة القطرية، لكن يقتصر التنفيذ على بعض الصفوف / المراحل الدراسية، مما يؤثر على ترسيخ القيم وتعزيز الهوية الوطنية والثقافة القطرية.
أو
يتم تنفيذ خطة تتضمن برامج وأنشطة محدودة لتعزيز القيم والهوية الوطنية والثقافة القطرية.', NULL, ARRAY[164,165]),
  ('4.2.1', 1, 1, 'يتم تنفيذ خطة تتضمن أنشطة لتعزيز القيم الإسلامية والهوية الوطنية والثقافة القطرية، لكن يقتصر التنفيذ على قلة من الصفوف / المراحل التعليمية، مما يؤثر سلباً على ترسيخ القيم وتعزيز الهوية الوطنية والثقافة القطرية.
أو
لا يتم إعداد أو تنفيذ خطة لتعزيز القيم والهوية الوطنية والثقافة القطرية.', NULL, ARRAY[164,165]),
  ('4.2.1', 2, 5, 'تقوم المدرسة بدعم المبادرات الوطنية وعقد شراكات نوعية مع المؤسسات المجتمعية لتعزيز الهوية الوطنية، وبمشاركة من جميع الصفوف / المراحل الدراسية، مما يسهم بشكلٍ فعال جداً ومستمر في تعزيز روح المواطنة والانتماء.', NULL, ARRAY[165]),
  ('4.2.1', 2, 4, 'تقوم المدرسة بدعم المبادرات الوطنية وعقد شراكات مع المؤسسات المجتمعية لتعزيز الهوية الوطنية، وبمشاركة الغالبية العظمى من الصفوف / المراحل الدراسية، مما يسهم بشكلٍ فعال في تعزيز روح المواطنة والانتماء.', NULL, ARRAY[165]),
  ('4.2.1', 2, 3, 'تقوم المدرسة بدعم المبادرات الوطنية وعقد شراكات مع المؤسسات المجتمعية لتعزيز الهوية الوطنية، وبمشاركة معظم الصفوف / المراحل الدراسية، مما يسهم بشكلٍ مناسب في تعزيز روح المواطنة والانتماء.', NULL, ARRAY[165]),
  ('4.2.1', 2, 2, 'تقوم المدرسة بدعم المبادرات الوطنية وعقد شراكات مع المؤسسات المجتمعية لتعزيز الهوية الوطنية بشكلٍ محدود، وبمشاركة بعض الصفوف / المراحل الدراسية.', NULL, ARRAY[165]),
  ('4.2.1', 2, 1, 'تقوم المدرسة بدعم المبادرات الوطنية وعقد شراكات مع المؤسسات المجتمعية لتعزيز الهوية الوطنية بشكلٍ محدود جداً، وبمشاركة قلة من الصفوف / المراحل الدراسية.
أو
لا تقوم المدرسة بدعم المبادرات الوطنية و / أو عقد شراكات مع المؤسسات المجتمعية لتعزيز الهوية الوطنية.', NULL, ARRAY[165]),
  ('4.2.2', 1, 5, 'يلتزم جميع الموظفين والطلبة بالزي المحتشم الذي يعكس الاحترام للقيم الإسلامية والثقافة القطرية.', NULL, ARRAY[165]),
  ('4.2.2', 1, 4, 'يلتزم الغالبية العظمى من الموظفين والطلبة بالزي المحتشم الذي يعكس الاحترام للقيم الإسلامية والثقافة القطرية.', NULL, ARRAY[165]),
  ('4.2.2', 1, 3, 'يلتزم معظم الموظفين والطلبة بالزي المحتشم الذي يعكس الاحترام للقيم الإسلامية والثقافة القطرية.', NULL, ARRAY[165]),
  ('4.2.2', 1, 2, 'يلتزم بعض الموظفين والطلبة بالزي المحتشم الذي يعكس الاحترام للقيم الإسلامية والثقافة القطرية.', NULL, ARRAY[165]),
  ('4.2.2', 1, 1, 'يلتزم قلة من الموظفين والطلبة بالزي المحتشم الذي يعكس الاحترام للقيم الإسلامية والثقافة القطرية.', NULL, ARRAY[165]),
  ('4.2.2', 2, 5, 'تعكس بيئة المدرسة التزاماً تاماً وواضحاً بتعزيز الهوية الوطنية والقيم الإسلامية في جميع جوانب الحياة المدرسية.', NULL, ARRAY[165,166]),
  ('4.2.2', 2, 4, 'تعكس بيئة المدرسة التزاماً واضحاً بتعزيز الهوية الوطنية والقيم الإسلامية في الغالبية العظمى من جوانب الحياة المدرسية..', NULL, ARRAY[165,166]),
  ('4.2.2', 2, 3, 'تعكس بيئة المدرسة التزاماً مناسباً بتعزيز الهوية الوطنية والقيم الإسلامية في معظم جوانب الحياة المدرسية.', NULL, ARRAY[165,166]),
  ('4.2.2', 2, 2, 'تعكس بيئة المدرسة التزاماً بتعزيز الهوية الوطنية والقيم الإسلامية في بعض جوانب الحياة المدرسية.', NULL, ARRAY[165,166]),
  ('4.2.2', 2, 1, 'تعكس بيئة المدرسة التزاماً بتعزيز الهوية الوطنية والقيم الإسلامية في قلة من جوانب الحياة المدرسية.', NULL, ARRAY[165,166]),
  ('4.2.3', 1, 5, 'يتم دمج الهوية الوطنية والثقافة القطرية بشكلٍ شامل ومتكامل في المنهج المدرسي في جميع المواد الدراسية، ويتم تطبيق أنشطة تعليمية متنوعة ومنتظمة، ومشاريع طلابية مبتكرة ترتبط بشكلٍ فعال جداً بالهوية الوطنية والثقافة المحلية.', NULL, ARRAY[166]),
  ('4.2.3', 1, 4, 'يتم دمج الهوية الوطنية والثقافة القطرية في المنهج المدرسي في الغالبية العظمى من المواد الدراسية، ويتم تطبيق أنشطة تعليمية متنوعة، ومشاريع طلابية ترتبط بشكلٍ فعال بالهوية الوطنية والثقافة المحلية.', NULL, ARRAY[166]),
  ('4.2.3', 1, 3, 'يتم دمج الهوية الوطنية والثقافة القطرية في المنهج المدرسي في معظم المواد الدراسية، ويتم تطبيق أنشطة تعليمية ومشاريع طلابية ترتبط بالهوية الوطنية والثقافة المحلية.', NULL, ARRAY[166]),
  ('4.2.3', 1, 2, 'يتم دمج الهوية الوطنية والثقافة القطرية في المنهج المدرسي في بعض المواد الدراسية.
أو
يتم دمج الهوية الوطنية والثقافة القطرية في المنهج المدرسي في المواد الدراسية بشكلٍ محدود، حيث أن الأنشطة التعليمية والمشاريع الطلابية المرتبطة بالهوية الوطنية غير كافية.', NULL, ARRAY[166]),
  ('4.2.3', 1, 1, 'يتم دمج الهوية الوطنية والثقافة القطرية في قلة من المواد الدراسية.
أو
لا يتم دمج الهوية الوطنية والثقافة القطرية في المنهج المدرسي، وتفتقر الأنشطة التعليمية إلى الارتباط بالهوية الوطنية والثقافة المحلية.', NULL, ARRAY[166]),
  ('4.2.3', 2, 5, 'يتم مراجعة المصادر التعليمية بشكلٍ فعال جداً ومنتظم ودقيق، لضمان توافقها مع القيم الوطنية والدينية مما أدى إلى خلو جميع المصادر التعليمية من أي محتوى يتعارض مع التعاليم الدينية والثقافة القطرية.', NULL, ARRAY[166]),
  ('4.2.3', 2, 4, 'يتم مراجعة المصادر التعليمية بشكلٍ فعال ومنتظم لضمان توافقها مع القيم الوطنية والدينية، مما أدى إلى خلو الغالبية العظمى من المصادر التعليمية من أي محتوى يتعارض مع التعاليم الدينية والثقافة القطرية.', NULL, ARRAY[166]),
  ('4.2.3', 2, 3, 'يتم مراجعة المصادر التعليمية بشكلٍ مناسب لضمان توافقها مع القيم الوطنية والدينية. مما أدى إلى خلو معظم المصادر التعليمية مما يتعارض مع التعاليم الدينية والثقافة القطرية.', NULL, ARRAY[166]),
  ('4.2.3', 2, 2, 'بعض المصادر التعليمية خالية مما يتعارض مع التعاليم الدينية والثقافة القطرية، حيث يتم مراجعتها بشكلٍ محدود.', NULL, ARRAY[166]),
  ('4.2.3', 2, 1, 'قلة من المصادر التعليمية خالية مما يتعارض مع التعاليم الدينية والثقافة القطرية، حيث يتم مراجعتها بشكلٍ محدود جداً.
أو
لا يتم مراجعة المصادر لضمان توافقها مع القيم الوطنية والدينية.', NULL, ARRAY[166]),
  ('4.2.4', 1, 5, 'تتسم ممارسات التعليم والتعلّم في مواد (اللغة العربية، والتربية الإسلامية، والتاريخ القطري والمواطنة) بالجودة العالية، مما انعكس بشكلٍ إيجابي على مخرجات تعلم جميع الطلبة في هذه المواد.', NULL, ARRAY[167]),
  ('4.2.4', 1, 4, 'تتسم ممارسات التعليم والتعلّم في مواد (اللغة العربية، والتربية الإسلامية، والتاريخ القطري والمواطنة) بالجودة، مما انعكس بشكلٍ إيجابي على مخرجات تعلم الغالبية العظمى من الطلبة في هذه المواد.', NULL, ARRAY[167]),
  ('4.2.4', 1, 3, 'تتسم ممارسات التعليم والتعلّم في مواد (اللغة العربية، والتربية الإسلامية، والتاريخ القطري والمواطنة) بجودة مناسبة، مما انعكس بشكلٍ إيجابي على مخرجات تعلم معظم الطلبة في هذه المواد.', NULL, ARRAY[167]),
  ('4.2.4', 1, 2, 'تتسم ممارسات التعليم والتعلّم في مواد (اللغة العربية، والتربية الإسلامية، والتاريخ القطري والمواطنة) بجودة محدودة، مما انعكس بشكلٍ إيجابي على مخرجات تعلم بعض الطلبة في هذه المواد.
أو
تتسم ممارسات التعليم والتعلّم في مواد (اللغة العربية، والتربية الإسلامية، والتاريخ القطري والمواطنة) بالجودة، إلا أنها انعكست بشكلٍ محدود على مخرجات تعلم الطلبة في هذه المواد.', NULL, ARRAY[167]),
  ('4.2.4', 1, 1, 'تتسم ممارسات التعليم والتعلّم في مواد (اللغة العربية، والتربية الإسلامية، والتاريخ القطري والمواطنة) بجودة محدودة جداً، مما انعكس بشكلٍ إيجابي على مخرجات تعلم قلة الطلبة في هذه المواد.', NULL, ARRAY[167]),
  ('5.1.1', 1, 5, 'يتم تطبيق سياسة توظيف تتضمن إجراءات ومعايير واضحة ومحددة تسهم في توظيف الكوادر التعليمية والإدارية بما يتوافق مع رؤية المدرسة ورسالتها وأهدافها، وتتوافق جميع الوظائف التي يشغلها الموظفون مع مؤهلاتهم وخبراتهم، مما يضمن تحقيق كفاءة عالية في الأداء وجودة في العمل.', NULL, ARRAY[186]),
  ('5.1.1', 1, 4, 'يتم تطبيق سياسة توظيف تتضمن إجراءات ومعايير واضحة ومحددة تسهم في توظيف الكوادر التعليمية والإدارية بما يتوافق مع رؤية المدرسة ورسالتها وأهدافها، وتتوافق الغالبية العظمى من الوظائف التي يشغلها الموظفون مع مؤهلاتهم وخبراتهم، مما يضمن تحقيق كفاءة في الأداء وجودة العمل.', NULL, ARRAY[186]),
  ('5.1.1', 1, 3, 'يتم تطبيق سياسة توظيف تتضمن إجراءات ومعايير واضحة تسهم في توظيف الكوادر التعليمية والإدارية بما يتوافق مع رؤية المدرسة ورسالتها وأهدافها، وتتوافق معظم الوظائف التي يشغلها الموظفون مع مؤهلاتهم وخبراتهم، مما يضمن تحقيق جودة العمل بشكلٍ مناسب.', NULL, ARRAY[186]),
  ('5.1.1', 1, 2, 'تتضمن سياسة التوظيف إجراءات ومعايير واضحة لتوظيف الكوادر بما يتوافق مع رؤية ورسالة المدرسة، إلا أن تطبيقها يتم بشكلٍ محدود، مما يؤدى إلى توافق بعض الوظائف التي يشغلها الموظفون مع مؤهلاتهم وخبراتهم، مما يؤدي إلى تحقيق جودة محدودة في العمل.', NULL, ARRAY[186]),
  ('5.1.1', 1, 1, 'تتضمن سياسة التوظيف إجراءات ومعايير واضحة لتوظيف الكوادر، إلا أن تطبيقها يتم بشكلٍ محدود جداً، مما يؤدى إلى توافق قلة من الوظائف التي يشغلها الموظفون مع مؤهلاتهم وخبراتهم، مما يؤدي إلى تحقيق جودة محدودة جداً في العمل.
أو
لا تتضمن سياسة التوظيف إجراءات ومعايير واضحة، مما يؤدى إلى تعيين كوادر لا تتوافق وظائفهم مع مؤهلاتهم وخبراتهم، ويؤثر سلباً على كفاءة الأداء وجودة العمل في المدرسة.', NULL, ARRAY[186]),
  ('5.1.1', 2, 5, 'يتناسب عدد الموظفين مع عدد الطلبة واحتياجاتهم في جميع الصفوف / المراحل التعليمية، حيث يتم توزيع الموظفين بكفاءة وفاعلية عالية لضمان توفير خدمات تعليمية وإدارية عالية الجودة.', NULL, ARRAY[186,187]),
  ('5.1.1', 2, 4, 'يتناسب عدد الموظفين مع عدد الطلبة واحتياجاتهم في الغالبية العظمى من الصفوف / المراحل التعليمية، حيث يتم توزيع الموظفين بفاعلية لضمان توفير خدمات تعليمية وإدارية ذات جودة.', NULL, ARRAY[186,187]),
  ('5.1.1', 2, 3, 'يتناسب عدد الموظفين مع عدد الطلبة واحتياجاتهم في معظم الصفوف / المراحل التعليمية، ويتم توزيع الموظفين بشكلٍ مناسب لضمان توفير خدمات تعليمية وإدارية مناسبة.', NULL, ARRAY[186,187]),
  ('5.1.1', 2, 2, 'يتناسب عدد الموظفين مع عدد الطلبة واحتياجاتهم في بعض الصفوف / المراحل التعليمية، مما يؤدي إلى توفير خدمات تعليمية و/أو إدارية بجودة محدودة.
أو
يتناسب عدد الموظفين مع عدد الطلبة، ولكن يتم توزيع الموظفين بشكلٍ غير مناسب أو غير فعال، مما أدى إلى توفير خدمات تعليمية و/أو إدارية محدودة.', NULL, ARRAY[186,187]),
  ('5.1.1', 2, 1, 'يتناسب عدد الموظفين مع عدد الطلبة واحتياجاتهم في قلة من الصفوف / المراحل التعليمية، مما يؤدى إلى توفير خدمات تعليمية و/أو إدارية محدودة جداً.
أو
لا يتناسب عدد الموظفين مع عدد الطلبة واحتياجاتهم، ويتم توزيع الموظفين بشكلٍ غير مناسب مما أدى إلى تقديم خدمات تعليمية و/أو إدارية محدودة جداً.', NULL, ARRAY[186,187]),
  ('5.1.2', 1, 5, 'يتم إعداد وتنفيذ خطة لتدريب وتأهيل الموظفين الجدد، تتضمن برامج تدريبية شاملة ومتنوعة وتستهدف جميع الموظفين الجدد، وتلبي الاحتياجات الخاصة بكل وظيفة، بهدف تزويدهم بالمعرفة والمهارات اللازمة لأداء مهامهم بكفاءة عالية.', NULL, ARRAY[187,188]),
  ('5.1.2', 1, 4, 'يتم إعداد وتنفيذ خطة لتدريب وتأهيل الموظفين الجدد، تتضمن برامج تدريبية متنوعة وتستهدف الغالبية العظمى من الموظفين الجدد، بهدف تزويدهم بالمعرفة والمهارات اللازمة لأداء مهامهم بكفاءة.', NULL, ARRAY[187,188]),
  ('5.1.2', 1, 3, 'يتم إعداد وتنفيذ خطة لتدريب وتأهيل الموظفين الجدد، تتضمن برامج تدريبية مناسبة وتستهدف معظم الموظفين الجدد، بهدف تزويدهم بالمعرفة والمهارات اللازمة لأداء مهامهم.', NULL, ARRAY[187,188]),
  ('5.1.2', 1, 2, 'يتم إعداد وتنفيذ خطة لتدريب وتأهيل الموظفين الجدد، تتضمن برامج تدريبية، إلا أنها تستهدف بعض الموظفين الجدد، مما يؤثر على فعاليتها في تزويدهم بالمعرفة والمهارات اللازمة لأداء مهامهم.
أو
يتم إعداد وتنفيذ خطة لتدريب وتأهيل الموظفين الجدد، إلا أنها تتضمن برامج تدريبية محدودة، مما يؤثر على فعاليتها في تزويدهم بالمعرفة والمهارات اللازمة لأداء مهامهم.', NULL, ARRAY[187,188]),
  ('5.1.2', 1, 1, 'يتم إعداد وتنفيذ خطة لتدريب وتأهيل الموظفين الجدد، تتضمن برامج تدريبية، إلا أنها تستهدف قلة من الموظفين الجدد، مما يؤثر سلباً على فعاليتها في تزويدهم بالمعرفة والمهارات اللازمة لأداء مهامهم.
أو
لا يتم إعداد خطة لتدريب وتأهيل الموظفين الجدد.
أو
البرامج المقدمة للموظفين الجدد محدودة جداً وعشوائية، ولا تستند إلى احتياجات الوظائف، مما يؤدي إلى ضعف في تزويدهم بالمعرفة والمهارات اللازمة، ويعيق تكيفهم واندماجهم في بيئة العمل في المدرسة.', NULL, ARRAY[187,188]),
  ('5.1.2', 2, 5, 'يتم تقييم فعالية برامج التدريب والتأهيل المقدمة للموظفين الجدد بانتظام وفق آلية وإجراءات واضحة ومحددة وفعالة جداً، بما يُسهم في رصد جوانب القوة وتحديد مجالات التحسين، كما يتم تقديم دعم مستمر لهم من خلال إشراف مباشر ومتابعة مستمرة لأدائهم، مما يسهم في تطور أداء جميع الموظفين الجدد واندماجهم في بيئة العمل', NULL, ARRAY[188]),
  ('5.1.2', 2, 4, 'يتم تقييم فعالية برامج التدريب والتأهيل المقدمة للموظفين الجدد بانتظام وفق آلية وإجراءات واضحة وفعالة، بما يُسهم في رصد جوانب القوة وتحديد مجالات التحسين، كما يتم تقديم دعم لهم من خلال إشراف ومتابعة دورية لأدائهم، مما يسهم في تطور أداء الغالبية العظمى من الموظفين الجدد واندماجهم في بيئة العمل.', NULL, ARRAY[188]),
  ('5.1.2', 2, 3, 'يتم تقييم فعالية برامج التدريب والتأهيل المقدمة للموظفين الجدد وفق آلية وإجراءات مناسبة، كما يتم تقديم دعم لهم من خلال إشراف ومتابعة لأدائهم، مما يسهم في تطور أداء معظم الموظفين الجدد واندماجهم في بيئة العمل.', NULL, ARRAY[188]),
  ('5.1.2', 2, 2, 'يتم تقييم فعالية برامج التدريب والتأهيل المقدمة للموظفين الجدد، إلا أنه يتم تقديم دعم محدود لهم من حيث المتابعة والإشراف، مما يسهم في تطور أداء بعض الموظفين الجدد واندماجهم في بيئة العمل.
أو
يتم تقييم فعالية برامج التدريب والتأهيل المقدمة للموظفين الجدد وفق آلية وإجراءات محدودة، مما يسهم في تطور أداء بعض الموظفين الجدد واندماجهم في بيئة العمل.', NULL, ARRAY[188]),
  ('5.1.2', 2, 1, 'يتم تقييم فعالية برامج التدريب والتأهيل المقدمة للموظفين الجدد، إلا أنه يتم تقديم دعم محدود جداً لهم، مما يسهم في تطور أداء قلة من الموظفين الجدد واندماجهم في بيئة العمل.
أو
لا يتم تقييم فعالية برامج التدريب والتأهيل المقدمة للموظفين الجدد، .', NULL, ARRAY[188]),
  ('5.1.3', 1, 5, 'يتم إعداد وتنفيذ خطة تطوير مهني ذات جودة عالية بناءً على تحليل دقيق وشامل لاحتياجات الموظفين المهنية وتقييمات أدائهم، وبما يتماشى مع رسالة المدرسة وأهدافها، وتتضمن الخطة برامج تدريبية متنوعة ومنتظمة وشاملة تُلبّي الاحتياجات المهنية للموظفين بشكلٍ فعال جداً، ويظهر جميع الموظفين التزاماً في تطبيق المهارات والمعارف المكتسبة في أدائهم لمهامهم.', NULL, ARRAY[188,189]),
  ('5.1.3', 1, 4, 'يتم إعداد وتنفيذ خطة تطوير مهني ذات جودة بناءً على تحليل لاحتياجات الموظفين المهنية وتقييمات أدائهم، وبما يتماشى مع رسالة المدرسة وأهدافها، وتتضمن برامج تدريبية متنوعة ومنتظمة تُلبّي الاحتياجات المهنية للموظفين بشكلٍ فعال، ويظهر الغالبية العظمى من الموظفين التزاماً في تطبيق المهارات والمعارف المكتسبة في أدائهم لمهامهم.', NULL, ARRAY[188,189]),
  ('5.1.3', 1, 3, 'يتم إعداد وتنفيذ خطة تطوير مهني بناءً على تحليل لاحتياجات الموظفين المهنية وتقييمات أدائهم، وبما يتماشى مع رسالة المدرسة وأهدافها، وتتضمن الخطة برامج تدريبية تُلبّي الاحتياجات المهنية الموظفين بشكل مناسب، ويظهر معظم الموظفين التزاماً في تطبيق المهارات والمعارف المكتسبة في أدائهم لمهامهم..', NULL, ARRAY[188,189]),
  ('5.1.3', 1, 2, 'يتم إعداد وتنفيذ خطة تطوير مهني ذات جودة محدودة، ويظهر بعض الموظفين التزاماً في تطبيق المهارات والمعارف المكتسبة في أدائهم لمهامهم.
أو
يتم إعداد خطة تطوير مهني ذات جودة إلا أنها تنعكس بشكلٍ محدود على أداء الموظفين.', NULL, ARRAY[188,189]),
  ('5.1.3', 1, 1, 'يتم إعداد وتنفيذ خطة تطوير مهني ذات جودة محدودة جداً، ويظهر قلة من الموظفين التزاماً في تطبيق المهارات والمعارف المكتسبة في أدائهم لمهامهم.
أو
لا يتم إعداد خطة تطوير مهني للموظفين، وتُقدم ورش التدريب بشكلٍ غير منتظم وعشوائي، دون استناد واضح إلى احتياجات الموظفين المهنية، مما يفتقر إلى التخطيط والفعالية المطلوبة.', NULL, ARRAY[188,189]),
  ('5.1.3', 2, 5, 'يتم متابعة وتقييم فعالية برامج التطوير المهني من خلال تقييمات دورية ومنهجية، يتم فيها تحليل دقيق وشامل لأثر التدريب على أداء الموظفين، ويتم بناءً عليه التعديل على الخطط والبرامج، بما يضمن التحسين الفعال جداً في أداء جميع الموظفين.', NULL, ARRAY[189]),
  ('5.1.3', 2, 4, 'يتم متابعة وتقييم فعالية برامج التطوير المهني من خلال تقييمات دورية، يتم فيها تحليل دقيق لأثر التدريب على أداء الموظفين، ويتم بناءً عليه التعديل على الخطط والبرامج، بما يضمن التحسين الفعال في أداء الغالبية العظمى من الموظفين.', NULL, ARRAY[189]),
  ('5.1.3', 2, 3, 'يتم متابعة وتقييم فعالية برامج التطوير المهني من خلال تحليل أثر التدريب على أداء الموظفين، ويتم بناءً عليه التعديل على الخطط والبرامج، بما يضمن التحسين المناسب في أداء معظم الموظفين.', NULL, ARRAY[189]),
  ('5.1.3', 2, 2, 'يتم متابعة وتقييم فعالية برامج التطوير المهني بشكلٍ محدود، وبما يسهم في تحسن أداء بعض الموظفين.
أو
يتم متابعة وتقييم فعالية برامج التطوير المهني، إلا أن التعديل عليها يتم بشكلٍ محدود، مما يؤثر على تحسين أداء الموظفين.', NULL, ARRAY[189]),
  ('5.1.3', 2, 1, 'يتم متابعة وتقييم فعالية برامج التطوير المهني بشكلٍ محدود جداً، وبما يسهم في تحسن أداء قلة من الموظفين.
أو
لا تتم متابعة فعالية برامج التطوير المهني، ولا تُراجع الخطط والبرامج التدريبية، مما يؤثر سلباً على تحسين أداء الموظفين.', NULL, ARRAY[189]),
  ('5.2.1', 1, 5, 'تتناسب مساحة المبنى المدرسي والصفوف والمرافق مع أعداد الطلبة وتلبي احتياجاتهم المختلفة، وتتوفر جميع المرافق المدرسية المتوافقة مع متطلبات العملية التعليمية، والمزودة بخدمة الإنترنت عالية السرعة والآمنة، ويتم مراعاة معايير الاستدامة البيئية في تصميم المبنى والمرافق المدرسية، مما يوفر بيئة تعليمية ذات جودة عالية تدعم تعلم الطلبة.', NULL, ARRAY[190]),
  ('5.2.1', 1, 4, 'تتناسب مساحة المبنى المدرسي والصفوف والمرافق مع أعداد الطلبة وتلبي احتياجاتهم المختلفة، وتتوفر الغالبية العظمى من المرافق المدرسية المتوافقة مع متطلبات العملية التعليمية، والمزودة بخدمة الإنترنت عالية السرعة والآمنة، ويتم مراعاة معايير الاستدامة البيئية في تصميم المبنى والمرافق المدرسية، مما يوفر بيئة تعليمية ذات جودة تدعم تعلم الطلبة.', NULL, ARRAY[190]),
  ('5.2.1', 1, 3, 'تتناسب مساحة المبنى المدرسي والصفوف والمرافق مع أعداد الطلبة، وتتوفر معظم المرافق المدرسية المتوافقة مع متطلبات العملية التعليمية، والمزودة بخدمة الإنترنت الآمنة وعالية السرعة.', NULL, ARRAY[190]),
  ('5.2.1', 1, 2, 'تتناسب مساحة المبنى المدرسي والصفوف والمرافق مع أعداد الطلبة، وتتوفر خدمة الإنترنت الآمنة، إلا أنه تم توفير بعض المرافق المدرسية التي تلبي متطلبات العملية التعليمية.
أو
تتناسب مساحة المبنى المدرسي والمرافق مع أعداد الطلبة، كما أن المرافق المدرسية متوافقة مع العملية التعليمية، إلا أن خدمة الإنترنت الآمنة وعالية السرعة تتوفر في بعض المرافق فقط.
أو
تتوفر المرافق المدرسية المتوافقة مع العملية التعليمية، والمزودة بخدمة الإنترنت الآمنة، إلا أن مساحة المبنى المدرسي والمرافق تتناسب بشكلٍ محدود مع أعداد الطلبة.', NULL, ARRAY[190]),
  ('5.2.1', 1, 1, 'تتناسب مساحة المبنى المدرسي والصفوف والمرافق مع أعداد الطلبة، إلا أنه تتوفر قلة من المرافق المدرسية التي تتوافق مع متطلبات العملية التعليمية.
أو
لا تتناسب مساحة المبنى المدرسي والصفوف والمرافق مع أعداد الطلبة و / أو لا تتوافق مع متطلبات العملية التعليمية.', NULL, ARRAY[190]),
  ('5.2.1', 2, 5, 'جميع الصفوف والقاعات الدراسية والمرافق مجهزة بشكلٍ يتناسب تماماً مع احتياجات الطلبة، ويدعم تنفيذ أنشطة التعليم والتعلم بفعالية وكفاءة عالية.', NULL, ARRAY[190,191]),
  ('5.2.1', 2, 4, 'الغالبية العظمى من الصفوف والقاعات الدراسية والمرافق مجهزة بشكلٍ يتناسب مع احتياجات الطلبة، ويدعم تنفيذ أنشطة التعليم والتعلم بكفاءة.', NULL, ARRAY[190,191]),
  ('5.2.1', 2, 3, 'معظم الصفوف والقاعات الدراسية والمرافق مجهزة بشكلٍ يتناسب مع احتياجات الطلبة، ويدعم تنفيذ أنشطة التعليم والتعلم بشكل مناسب.', NULL, ARRAY[190,191]),
  ('5.2.1', 2, 2, 'بعض الصفوف والقاعات الدراسية والمرافق مجهزة بشكلٍ يتناسب مع احتياجات الطلبة، مما يسهم بشكلٍ محدود في دعم تنفيذ أنشطة التعليم والتعلم.', NULL, ARRAY[190,191]),
  ('5.2.1', 2, 1, 'قلة من الصفوف والقاعات الدراسية والمرافق مجهزة بشكلٍ يتناسب مع احتياجات الطلبة، مما يسهم بشكلٍ محدود جداً في دعم تنفيذ أنشطة التعليم والتعلم..', NULL, ARRAY[190,191]),
  ('5.2.1', 3, 5, 'الإضاءة والتهوية مناسبة في جميع الصفوف والمرافق المدرسية.', NULL, ARRAY[191]),
  ('5.2.1', 3, 4, 'الإضاءة والتهوية مناسبة في الغالبية العظمى من الصفوف والمرافق المدرسية.', NULL, ARRAY[191]),
  ('5.2.1', 3, 3, 'الإضاءة والتهوية مناسبة في معظم الصفوف والمرافق المدرسية.', NULL, ARRAY[191]),
  ('5.2.1', 3, 2, 'الإضاءة والتهوية مناسبة في بعض الصفوف والمرافق المدرسية.', NULL, ARRAY[191]),
  ('5.2.1', 3, 1, 'الإضاءة والتهوية مناسبة في قلة من الصفوف والمرافق المدرسية.', NULL, ARRAY[191]),
  ('5.2.1', 4, 5, 'يتم تهيئة وتكييف المبنى والمرافق بما يتناسب مع احتياجات جميع الطلبة ذوي الإعاقة، مما يضمن توفير بيئة مدرسية تدعم تعلمهم، وتطورهم بشكلٍ فعال جداً. (إن وجدوا)', NULL, ARRAY[191]),
  ('5.2.1', 4, 4, 'يتم تهيئة وتكييف المبنى والمرافق بما يتناسب مع احتياجات الغالبية العظمى من الطلبة ذوي الإعاقة، مما يضمن توفير بيئة مدرسية تدعم تعلمهم وتطورهم بشكلٍ فعال. (إن وجدوا)', NULL, ARRAY[191]),
  ('5.2.1', 4, 3, 'يتم تهيئة وتكييف المبنى والمرافق بما يتناسب مع احتياجات معظم الطلبة ذوي الإعاقة، مما يضمن توفير بيئة مدرسية تدعم تعلمهم وتطورهم بشكلٍ مناسب. (إن وجدوا)', NULL, ARRAY[191]),
  ('5.2.1', 4, 2, 'يتم تهيئة وتكييف المبنى والمرافق بما يتناسب مع احتياجات بعض الطلبة ذوي الإعاقة، مما يسهم بشكلٍ محدود في توفير بيئة مدرسية تدعم تعلمهم وتطورهم. (إن وجدوا)', NULL, ARRAY[191]),
  ('5.2.1', 4, 1, 'يتم تهيئة وتكييف المبنى والمرافق بما يتناسب مع احتياجات قلة من الطلبة ذوي الإعاقة، مما يسهم بشكلٍ محدود جداً في توفير بيئة مدرسية تدعم تعلمهم وتطورهم.
أو
لا يتم تهيئة وتكييف المبنى والمرافق بما يتناسب مع احتياجات الطلبة ذوي الإعاقة. (إن وجدوا)', NULL, ARRAY[191]),
  ('5.2.1', 5, 5, 'يتم توفير غرف مناسبة ومجهزة لجميع العاملين في المدرسة من إداريين وأكاديميين، مما يعزز بشكلٍ فعال جداً كفاءة بيئة العمل المدرسية.', NULL, ARRAY[191]),
  ('5.2.1', 5, 4, 'يتم توفير غرف مناسبة ومجهزة للغالبية العظمى من العاملين في المدرسة من إداريين وأكاديميين، مما يعزز بشكلٍ فعال كفاءة بيئة العمل المدرسية.', NULL, ARRAY[191]),
  ('5.2.1', 5, 3, 'يتم توفير غرف مناسبة ومجهزة لمعظم العاملين في المدرسة من إداريين وأكاديميين، مما يعزز بشكلٍ مناسب كفاءة بيئة العمل المدرسية.', NULL, ARRAY[191]),
  ('5.2.1', 5, 2, 'يتم توفير غرف مناسبة لبعض العاملين في المدرسة، مما أثر على كفاءة بيئة العمل المدرسية.', NULL, ARRAY[191]),
  ('5.2.1', 5, 1, 'يتم توفير غرف مناسبة لقلة من العاملين في المدرسة، مما أثر سلباً على كفاءة بيئة العمل المدرسية.', NULL, ARRAY[191]),
  ('5.2.2', 1, 5, 'يتناسب حجم المكتبة والأثاث مع أعداد الطلبة وأعمارهم، مما يوفر بيئة تعليمية مريحة وملائمة، وتحتوي على مجموعة متنوعة وحديثة من المصادر التعليمية والموارد الرقمية التي تناسب احتياجات جميع الطلبة، كما يتم توفير عددٍ كافٍ من الأجهزة الرقمية المتصلة بالإنترنت.', NULL, ARRAY[192]),
  ('5.2.2', 1, 4, 'يتناسب حجم المكتبة والأثاث مع أعداد الطلبة وأعمارهم، مما يوفر بيئة تعليمية مريحة وملائمة، وتحتوي المكتبة على مجموعة متنوعة من المصادر التعليمية والموارد الرقمية التي تناسب احتياجات الغالبية العظمى من الطلبة، كما يتم توفير عددٍ من الأجهزة الرقمية المتصلة بالإنترنت.', NULL, ARRAY[192]),
  ('5.2.2', 1, 3, 'يتناسب حجم المكتبة والأثاث مع أعداد الطلبة وأعمارهم، مما يوفر بيئة تعليمية ملائمة، وتحتوي المكتبة على مجموعة مناسبة من المصادر التعليمية والموارد الرقمية التي تناسب احتياجات معظم الطلبة، كما يتم توفير عددٍ من الأجهزة الرقمية المتصلة بالإنترنت.', NULL, ARRAY[192]),
  ('5.2.2', 1, 2, 'يتناسب حجم المكتبة والأثاث مع أعداد الطلبة وأعمارهم، إلا أن المكتبة تحتوي على مجموعة محدودة من المصادر التعليمية والموارد الرقمية والتي تناسب احتياجات بعض الطلبة.
أو
تحتوي المكتبة على مجموعة من المصادر التعليمية والموارد والأجهزة الرقمية التي تناسب احتياجات الطلبة، إلا أن حجم المكتبة والأثاث يتناسب بشكلٍ محدود مع أعداد الطلبة وأعمارهم، مما يؤثر على توفير بيئة تعليمية مريحة وملائمة.
أو
يتناسب حجم المكتبة والأثاث مع أعداد الطلبة وأعمارهم، وتحتوي المكتبة على مجموعة من المصادر التعليمية، إلا أن عددٍ الأجهزة الرقمية المتصلة بالإنترنت محدود.', NULL, ARRAY[192]),
  ('5.2.2', 1, 1, 'يتناسب حجم المكتبة والأثاث مع أعداد الطلبة وأعمارهم، إلا أن المكتبة تحتوي على مجموعة محدودة جداً من المصادر التعليمية والموارد الرقمية والتي تناسب احتياجات قلة من الطلبة، مما أثر سلباً على دعم تعلم الطلبة وتنمية مهاراتهم.
أو
تحتوي المكتبة على مجموعة من المصادر التعليمية والموارد والأجهزة الرقمية، إلا أن حجم المكتبة والأثاث لا يتناسب مع أعداد الطلبة وأعمارهم، مما يؤثر سلباً على توفير بيئة تعليمية مريحة وملائمة تعزز تجربة التعلم.
أو
لم يتم توفير مكتبة مدرسية، مما يؤثر سلباً على دعم تعلم الطلبة وتنمية مهاراتهم.', NULL, ARRAY[192]),
  ('5.2.2', 2, 5, 'يتوفر موظف مؤهل لإدارة وتنظيم المكتبة، ويطبق نظام استعارة متقدم يُسهل وصول الطلبة والمعلمين إلى الموارد المكتبية، ويتم تفعيل استخدام موارد المكتبة من قِبل المعلمين والطلبة في جميع الصفوف الدراسية، مما يسهم بشكلٍ فعال جداً ومستمر في دعم تعلم الطلبة وتنمية مهاراتهم.', NULL, ARRAY[193]),
  ('5.2.2', 2, 4, 'يتوفر موظف مؤهل لإدارة وتنظيم المكتبة، ويطبق نظام استعارة يُسهل وصول الطلبة والمعلمين إلى الموارد المكتبية، ويتم تفعيل استخدام موارد المكتبة من قبل المعلمين والطلبة في الغالبية العظمى من الصفوف الدراسية، مما يسهم بشكلٍ فعال في دعم تعلم الطلبة وتنمية مهاراتهم.', NULL, ARRAY[193]),
  ('5.2.2', 2, 3, 'يتوفر موظف مؤهل لإدارة وتنظيم المكتبة، ويطبق نظام استعارة يُسهل وصول الطلبة والمعلمين إلى الموارد المكتبية، ويتم تفعيل استخدام موارد المكتبة من قِبل المعلمين والطلبة في معظم الصفوف الدراسية، مما يسهم بشكلٍ مناسب في دعم تعلم الطلبة.', NULL, ARRAY[193]),
  ('5.2.2', 2, 2, 'يتوفر موظف مؤهل لإدارة المكتبة، ويتم تطبيق نظام استعارة، لكن يتم تفعيل استخدام موارد المكتبة من قِبل المعلمين والطلبة في بعض الصفوف الدراسية، مما أدى إلى دعم تعلم الطلبة بشكلٍ محدود.', NULL, ARRAY[193]),
  ('5.2.2', 2, 1, 'يتوفر موظف لإدارة المكتبة، ويتم تطبيق نظام استعارة، ويتم تفعيل استخدام موارد المكتبة من قِبل المعلمين والطلبة في قلة من الصفوف الدراسية، مما أدى إلى دعم تعلم الطلبة بشكلٍ محدود جداً.
أو
لا يتوفر موظف مؤهل لإدارة وتنظيم المكتبة، الأمر الذي أثر سلباً على تفعيل استخدام موارد المكتبة.', NULL, ARRAY[193]),
  ('5.2.3', 1, 5, 'توفر المدرسة معامل علوم متنوعة تتناسب مع أعداد الطلبة وتلبي احتياجات المنهج بشكلٍ فعال جداً، ويتم تجهيزها بالموارد والمعدات والوسائل التعليمية اللازمة والمتنوعة، وتحديثها بشكلٍ دوري، كما يتوفر موظف مختص مسؤول عن المعامل لإدارة وتنظيم العمل وتقديم الدعم. ويتم توظيف المعامل بشكلٍ مستمر وداعم للعملية التعليمية في جميع حصص مواد العلوم.', NULL, ARRAY[193,194]),
  ('5.2.3', 1, 4, 'توفر المدرسة معامل علوم متنوعة تتناسب مع أعداد الطلبة وتلبي احتياجات المنهج بشكلٍ فعال، ويتم تجهيزها بالموارد والمعدات والوسائل التعليمية اللازمة، وتحديثها بشكلٍ دوري، كما يتوفر موظف مسؤول عن المعامل لإدارة وتنظيم العمل. ويتم توظيف المعامل بشكلٍ مستمر وداعم للعملية التعليمية في الغالبية العظمى من حصص مواد العلوم.', NULL, ARRAY[193,194]),
  ('5.2.3', 1, 3, 'توفر المدرسة معامل علوم متنوعة تتناسب مع أعداد الطلبة وتلبي احتياجات المنهج، ويتم تجهيزها بالموارد والمعدات والوسائل التعليمية بشكلٍ مناسب، ويتم تحديثها بشكلٍ دوري، كما يتوفر موظف مسؤول عن المعامل لإدارة وتنظيم العمل، ويتم توظيف المعامل بشكلٍ داعم للعملية التعليمية في معظم حصص مواد العلوم.', NULL, ARRAY[193,194]),
  ('5.2.3', 1, 2, 'توفر المدرسة معامل علوم تتناسب مع أعداد الطلبة، ويتم تجهيزها بالموارد والمعدات والوسائل التعليمية، لكن يتم توظيفها في بعض حصص مواد العلوم.
أو
توفر المدرسة معامل علوم تم تجهيزها بموارد ومعدات ووسائل تعليمية محدودة، مما أثر على تلبية احتياجات المنهج ودعم تعلم الطلبة.', NULL, ARRAY[193,194]),
  ('5.2.3', 1, 1, 'توفر المدرسة معامل علوم ويتم تجهيزها بالموارد والمعدات والوسائل التعليمية، لكن يتم توظيفها في قلة من حصص مواد العلوم.
أو
لا توفر المدرسة معامل علوم متنوعة بما يلبي احتياجات المنهج.', NULL, ARRAY[193,194]),
  ('5.2.3', 2, 5, 'يتم تصميم وتجهيز معامل العلوم وفقاً لمعايير الأمن والسلامة، كما يتم توفير إرشادات السلامة فيها، وتزويدها بأجهزة وأدوات الأمن والسلامة اللازمة، ويتم توظيف هذه الأجهزة والأدوات في جميع الحصص الدراسية المنفذة داخل المعامل، بما يضمن حماية الطلبة والموظفين بشكلٍ فعال جداً.', NULL, ARRAY[194]),
  ('5.2.3', 2, 4, 'يتم تصميم وتجهيز معامل العلوم وفقاً لمعايير الأمن والسلامة، كما يتم توفير إرشادات السلامة فيها، وتزويدها بأجهزة وأدوات الأمن والسلامة اللازمة، ويتم توظيف هذه الأجهزة والأدوات في الغالبية العظمى من الحصص الدراسية المنفذة داخل المعامل، بما يضمن حماية الطلبة والموظفين بشكلٍ فعال.', NULL, ARRAY[194]),
  ('5.2.3', 2, 3, 'يتم تصميم وتجهيز معامل العلوم وفقاً لمعايير الأمن والسلامة، كما يتم توفير إرشادات السلامة فيها، وتزويدها بأجهزة وأدوات الأمن والسلامة اللازمة، ويتم توظيف هذه الأجهزة والأدوات في معظم الحصص الدراسية المنفذة داخل المعامل بما يضمن حماية الطلبة والموظفين بشكلٍ مناسب.', NULL, ARRAY[194]),
  ('5.2.3', 2, 2, 'يتم تصميم وتجهيز معامل العلوم وفقاً لمعايير الأمن والسلامة، وتزويدها بأجهزة وأدوات الأمن والسلامة اللازمة، إلا أنه يتم توظيف هذه الأجهزة والأدوات في بعض الحصص الدراسية المنفذة داخل المعامل، مما يؤثر على سلامة الطلبة والموظفين أثناء إجراء التجارب.
أو
يتم تصميم وتجهيز معامل العلوم وفقاً لمعايير الأمن والسلامة، ويتم توفير إرشادات السلامة، إلا أنه تم تزويدها بأجهزة وأدوات محدودة لضمان السلامة أثناء إجراء التجارب العلمية، مما يؤثر على سلامة الطلبة في المعمل.', NULL, ARRAY[194]),
  ('5.2.3', 2, 1, 'يتم تصميم وتجهيز معامل العلوم وفقاً لمعايير الأمن والسلامة، وتزويدها بأجهزة وأدوات الأمن والسلامة اللازمة، إلا أنه يتم توظيف هذه الأجهزة والأدوات في قلة من الحصص الدراسية المنفذة داخل المعامل، مما يؤثر سلباً على سلامة الطلبة والموظفين أثناء إجراء التجارب.
أو
لا يتم تصميم وتجهيز معامل العلوم وفقاً لمعايير الأمن والسلامة، و/أو لا يتم تزويدها بالأجهزة والأدوات التي تضمن السلامة أثناء إجراء التجارب العلمية.', NULL, ARRAY[194]),
  ('5.2.4', 1, 5, 'توفر المدرسة معامل حاسب تتناسب مع أعداد الطلبة، ومجهزة بالأجهزة والبرمجيات التعليمية التي تتناسب مع احتياجات المنهج الدراسي، وتقوم بتحديثها وصيانتها بشكلٍ دوري، ويتم توظيف المعامل بشكلٍ فعال جداً ومستمر بما يدعم تعلم جميع الطلبة وتنمية مهاراتهم الرقمية، مع توفير موظف مختص لتشغيل المعامل وتوفير الدعم الفني المستمر.', NULL, ARRAY[195]),
  ('5.2.4', 1, 4, 'توفر المدرسة معامل حاسب تتناسب مع أعداد الطلبة، ومجهزة بالأجهزة والبرمجيات التعليمية التي تتناسب مع احتياجات المنهج الدراسي، وتقوم بتحديثها وصيانتها، ويتم توظيف المعامل بشكلٍ فعال بما يدعم تعلم الغالبية العظمى من الطلبة وتنمية مهاراتهم الرقمية، مع توفير موظف مختص لتشغيل المعامل وتوفير الدعم الفني.', NULL, ARRAY[195]),
  ('5.2.4', 1, 3, 'توفر المدرسة معامل حاسب تتناسب مع أعداد الطلبة، ومجهزة بالأجهزة والبرمجيات التعليمية التي تتناسب مع احتياجات المنهج الدراسي، وتقوم بتحديثها وصيانتها، ويتم توظيف المعامل بشكلٍ مناسب بما يدعم تعلم معظم الطلبة وتنمية مهاراتهم الرقمية، مع توفير موظف مختص لتشغيل المعامل وتوفير الدعم الفني.', NULL, ARRAY[195]),
  ('5.2.4', 1, 2, 'توفر المدرسة معامل حاسب تتناسب مع أعداد الطلبة، ومجهزة بالأجهزة والبرمجيات التعليمية، لكن يتم توظيفها بشكلٍ محدود، مما أدى إلى دعم تعلم بعض الطلبة وتنمية مهاراتهم الرقمية.
أو
توفر المدرسة معامل حاسب تم تجهيزها بأجهزة وبرمجيات تعليمية محدودة، مما أثر على دعم تعلم الطلبة وتنمية مهاراتهم التقنية.', NULL, ARRAY[195]),
  ('5.2.4', 1, 1, 'توفر المدرسة معامل حاسب مجهزة بالأجهزة والبرمجيات التعليمية، لكن يتم توظيفها بشكلٍ محدود جداً، مما أدى إلى دعم تعلم قلة من الطلبة وتنمية مهاراتهم الرقمية.
أو
لا توفر المدرسة معامل حاسب مجهزة للطلبة.', NULL, ARRAY[195]),
  ('5.2.5', 1, 5, 'توفر المدرسة مجموعة متنوعة من القاعات والملاعب الرياضية بما يتوافق مع متطلبات المنهج ويتناسب مع أعداد الطلبة، ويتم تجهيزها بأحدث المعدات والأجهزة المتنوعة، وتصميمها وفقاً لمعايير الأمن والسلامة، وتوظيفها بشكلٍ فعال جداً ومستمر، مما يعزز التعلم الرياضي ويتيح لجميع الطلبة ممارسة الأنشطة الرياضية.', NULL, ARRAY[195,196]),
  ('5.2.5', 1, 4, 'توفر المدرسة مجموعة متنوعة من القاعات والملاعب الرياضية بما يتوافق مع متطلبات المنهج ويتناسب مع أعداد الطلبة، ويتم تجهيزها بالمعدات والأجهزة، وتصميمها وفقاً لمعايير الأمن والسلامة، وتوظيفها بشكلٍ فعال، مما يعزز التعلم الرياضي ويتيح للغالبية العظمى من الطلبة ممارسة الأنشطة الرياضية.', NULL, ARRAY[195,196]),
  ('5.2.5', 1, 3, 'توفر المدرسة مجموعة متنوعة من القاعات والملاعب الرياضية بما يتوافق مع متطلبات المنهج ويتناسب مع أعداد الطلبة، ويتم تجهيزها بالمعدات والأجهزة، وتصميمها وفقاً لمعايير الأمن والسلامة، وتوظيفها بشكلٍ مناسب، مما يعزز تجربة التعلم الرياضي ويتيح لمعظم الطلبة ممارسة الأنشطة الرياضية.', NULL, ARRAY[195,196]),
  ('5.2.5', 1, 2, 'توفر المدرسة قاعات وملاعب رياضية بما يتوافق مع متطلبات المنهج ويتناسب مع أعداد الطلبة، ويتم تجهيزها بالمعدات والأجهزة، وتصميمها وفقاً لمعايير الأمن والسلامة، إلا أن توظيفها يتم بشكلٍ محدود مما يتيح لبعض الطلبة ممارسة الأنشطة الرياضية.
أو
توفر المدرسة قاعات وملاعب رياضية تم تجهيزها بمعدات وأجهزة محدودة، مما أثر على ممارسة الأنشطة الرياضية وتلبية متطلبات المنهج.
أو
توفر المدرسة مجموعة من القاعات والملاعب الرياضية، ويتم تجهيزها بالمعدات والأجهزة وتوظيفها، إلا أن تصميمها يتوافق بشكلٍ محدود مع معايير الأمن والسلامة.', NULL, ARRAY[195,196]),
  ('5.2.5', 1, 1, 'توفر المدرسة قاعات وملاعب رياضية بما يتوافق مع متطلبات المنهج ويتناسب مع أعداد الطلبة، ويتم تجهيزها بالمعدات والأجهزة، إلا أن توظيفها يتم بشكلٍ محدود جداً، مما يتيح لقلة من الطلبة ممارسة الأنشطة الرياضية.
أو
لا توفر المدرسة قاعات وملاعب رياضية بما يتوافق مع متطلبات المنهج ويتناسب مع أعداد الطلبة.
أو
توفر المدرسة قاعات وملاعب رياضية تم تصميمها بطريقةٍ غير آمنة.', NULL, ARRAY[195,196]),
  ('5.2.5', 2, 5, 'يتم توفير مناطق لعب داخلية وخارجية للأطفال في مرحلة الروضة (إن وجدت)، ملائمة ومجهزة بألعاب آمنة ومناسبة ومتنوعة، ويتم توظيفها من قِبل جميع الأطفال، بما يعزز تجربتهم التعليمية والترفيهية في بيئة آمنة ومحفزة على التعلم والنمو بشكلٍ فعال جداً.', NULL, ARRAY[196,197]),
  ('5.2.5', 2, 4, 'يتم توفير مناطق لعب داخلية وخارجية للأطفال في مرحلة الروضة (إن وجدت)، ملائمة ومجهزة بالألعاب الآمنة والمناسبة، ويتم توظيفها من قِبل الغالبية العظمى من الأطفال بما يعزز تجربتهم التعليمية والترفيهية بشكل فعال.', NULL, ARRAY[196,197]),
  ('5.2.5', 2, 3, 'يتم توفير مناطق لعب داخلية وخارجية للأطفال في مرحلة الروضة (إن وجدت)، مجهزة بالألعاب الآمنة والمناسبة، ويتم توظيفها من قِبل معظم الأطفال بما يعزز تجربتهم التعليمية والترفيهية بشكلٍ مناسب.', NULL, ARRAY[196,197]),
  ('5.2.5', 2, 2, 'يتم توفير مناطق لعب داخلية وخارجية للأطفال في مرحلة الروضة (إن وجدت)، مجهزة بألعاب آمنة ومناسبة، إلا أنه يتم توظيفها من قِبل بعض الأطفال، مما يحقق أثراً محدوداً في تجربتهم التعليمية والترفيهية.
أو
يتم توفير مناطق لعب داخلية أو خارجية للأطفال في مرحلة الروضة (إن وجدت)، مجهزة بألعاب آمنة ومناسبة، ويتم توظيفها من قِبل الأطفال، مما يحقق أثراً محدوداً في تجربتهم التعليمية والترفيهية نتيجة توفر نوع واحد فقط من مناطق اللعب.', NULL, ARRAY[196,197]),
  ('5.2.5', 2, 1, 'يتم توفير مناطق لعب داخلية وخارجية للأطفال في مرحلة الروضة (إن وجدت)، مجهزة بألعاب آمنة ومناسبة، إلا أنه يتم توظيفها من قِبل قلة من الأطفال، مما يحدّ من استفادة الأطفال منها ويؤدي إلى أثر محدود جداً في تجربتهم التعليمية والترفيهية.
أو
لا توفر المدرسة مناطق لعب داخلية وخارجية للأطفال في مرحلة الروضة (إن وجدت).
أو
يتم توفير مناطق لعب داخلية و/ أو خارجية للأطفال في مرحلة الروضة (إن وجدت)، مجهزة بالألعاب، ويتم توظيفها من قِبل الأطفال، إلا أن الألعاب أو مناطق اللعب غير ملائمة أو غير آمنة للأطفال.', NULL, ARRAY[196,197]),
  ('5.2.6', 1, 5, 'تتناسب مساحة قاعات الطعام وتجهيزاتها مع أعداد الطلبة وأعمارهم في جميع الصفوف / المراحل الدراسية، ويتم توفير عاملين مرخصين لتقديم الخدمات للطلبة (إن وجدوا)، وتطبيق اشتراطات الصحة والسلامة والنظافة بكفاءة عالية، مما يسهم بشكلٍ فعال جداً في توفير بيئة صحية وآمنة ومريحة للطلبة.', NULL, ARRAY[197,198]),
  ('5.2.6', 1, 4, 'تتناسب مساحة قاعات الطعام وتجهيزاتها مع أعداد الطلبة وأعمارهم في الغالبية العظمى من الصفوف / المراحل الدراسية، ويتم توفير عاملين مرخصين لتقديم الخدمات للطلبة (إن وجدوا)، وتطبيق اشتراطات الصحة والسلامة والنظافة، مما يسهم بشكلٍ فعال في توفير بيئة صحية وآمنة للطلبة.', NULL, ARRAY[197,198]),
  ('5.2.6', 1, 3, 'تتناسب مساحة قاعات الطعام وتجهيزاتها مع أعداد الطلبة وأعمارهم في معظم الصفوف / المراحل الدراسية، ويتم توفير عاملين مرخصين لتقديم الخدمات للطلبة (إن وجدوا)، وتطبيق اشتراطات الصحة والسلامة والنظافة، مما يسهم بشكلٍ مناسب في توفير بيئة صحية وآمنة.', NULL, ARRAY[197,198]),
  ('5.2.6', 1, 2, 'تتناسب مساحة قاعات الطعام وتجهيزاتها مع أعداد الطلبة وأعمارهم بشكلٍ محدود في بعض الصفوف / المراحل الدراسية، مما أثر على توفير بيئة صحية وآمنة للطلبة.
أو
تتناسب مساحة قاعات الطعام وتجهيزاتها مع أعداد الطلبة وأعمارهم، ويتم توفير عاملين مرخصين لتقديم الخدمات للطلبة (إن وجدوا)، إلا أنه يتم تطبيق اشتراطات الصحة والسلامة والنظافة بشكلٍ محدود.', NULL, ARRAY[197,198]),
  ('5.2.6', 1, 1, 'تتناسب مساحة قاعات الطعام وتجهيزاتها مع أعداد الطلبة وأعمارهم بشكلٍ محدود جداً في قلة من الصفوف / المراحل الدراسية، مما أثر سلباً على توفير بيئة صحية وآمنة للطلبة.
أو
لا يتم توفير عاملين مرخصين لتقديم الخدمات في قاعة الطعام. (إن وجدوا)
أو
لا يتم تطبيق اشتراطات الصحة والسلامة والنظافة في قاعات الطعام / المقصف المدرسي.', NULL, ARRAY[197,198]),
  ('5.2.6', 2, 5, 'يتم توفير خيارات غذائية متنوعة ومتوازنة تلبي احتياجات جميع الطلبة، وتعزز اتباع النمط الغذائي الصحي، وتراعي صحة الطلبة بشكلٍ فعال جداً. (إن وجد)', NULL, ARRAY[198]),
  ('5.2.6', 2, 4, 'يتم توفير خيارات غذائية متنوعة تلبي احتياجات الغالبية العظمى من الطلبة، وتعزز اتباع النمط الغذائي الصحي بشكلٍ فعال. (إن وجد)', NULL, ARRAY[198]),
  ('5.2.6', 2, 3, 'يتم توفير خيارات غذائية تلبي احتياجات معظم الطلبة، وتعزز اتباع النمط الغذائي الصحي بشكلٍ مناسب. (إن وجد)', NULL, ARRAY[198]),
  ('5.2.6', 2, 2, 'يتم توفير خيارات غذائية تلبي احتياجات بعض الطلبة، مما يسهم بشكلٍ محدود في تعزيز اتباع النمط الغذائي الصحي. (إن وجد)', NULL, ARRAY[198]),
  ('5.2.6', 2, 1, 'لا يتم توفير خيارات غذائية تلبي احتياجات الطلبة المختلفة، أو تعزز اتباع النمط الغذائي الصحي. (إن وجد)', NULL, ARRAY[198]),
  ('5.2.7', 1, 5, 'يتم توفير جميع المرافق التخصصية التي تتوافق مع طبيعة منهج المدرسة، وتجهيزها بالموارد والأدوات اللازمة والمناسبة، ويتم استخدام هذه المرافق بانتظام وفعالية، وبما يدعم تعلم الطلبة، ويسهم في تحقيق الأهداف التعليمية والتربوية بكفاءة عالية.', NULL, ARRAY[198,199]),
  ('5.2.7', 1, 4, 'يتم توفير الغالبية العظمى من المرافق التخصصية التي تتوافق مع طبيعة منهج المدرسة، وتجهيزها بالموارد والأدوات اللازمة، ويتم استخدام هذه المرافق بانتظام، وبما يدعم تعلم الطلبة، ويسهم في تحقيق الأهداف التعليمية والتربوية بكفاءة.', NULL, ARRAY[198,199]),
  ('5.2.7', 1, 3, 'يتم توفير معظم المرافق التخصصية التي تتوافق مع طبيعة منهج المدرسة، وتجهيزها بالموارد والأدوات اللازمة، ويتم استخدام هذه المرافق بما يدعم تعلم الطلبة، ويسهم في تحقيق الأهداف التعليمية والتربوية.', NULL, ARRAY[198,199]),
  ('5.2.7', 1, 2, 'يتم توفير بعض المرافق التخصصية المجهزة التي تتوافق مع طبيعة منهج المدرسة، مما يسهم بشكلٍ محدود في دعم تحقيق الأهداف التعليمية والتربوية.
أو
توفر المدرسة مرافق تخصصية تتوافق مع طبيعة منهج المدرسة، ويتم تجهيزها بالموارد والأدوات اللازمة، إلا أن تفعيلها والاستفادة منها في تنفيذ المنهج يتم بشكلٍ محدود، مما يؤثر على تحقيق الأهداف التعليمية والتربوية.', NULL, ARRAY[198,199]),
  ('5.2.7', 1, 1, 'يتم توفير قلة من المرافق التخصصية التي تتوافق مع طبيعة منهج المدرسة، مما يدعم تحقيق الأهداف التعليمية والتربوية بشكلٍ محدود جداً.
أو
لا توفر المدرسة مرافق تخصصية بما يتوافق مع طبيعة منهج المدرسة ويدعم تحقيق أهدافه التعليمية والتربوية.', NULL, ARRAY[198,199]),
  ('5.2.8', 1, 5, 'تتوفر مرافق تخصصية مجهزة بموارد ووسائل متنوعة ومحدثة تتناسب مع احتياجات الطلبة ذوي الإعاقة، ضمن بيئة تعليمية داعمة تعزز التفاعل والمشاركة، ويتم تفعيل هذه المرافق بشكلٍ فعال جداً بما يضمن استفادة جميع الطلبة ذوي الإعاقة منها ودعم تعلمهم.', NULL, ARRAY[199]),
  ('5.2.8', 1, 4, 'تتوفر مرافق تخصصية مجهزة بموارد ووسائل متنوعة تتناسب مع احتياجات الطلبة ذوي الإعاقة، ضمن بيئة تعليمية تعزز التفاعل والمشاركة، ويتم تفعيل هذه المرافق بشكلٍ فعال بما يضمن استفادة الغالبية العظمى من الطلبة ذوي الإعاقة منها ودعم تعلمهم.', NULL, ARRAY[199]),
  ('5.2.8', 1, 3, 'تتوفر مرافق تخصصية مجهزة بموارد ووسائل تتناسب مع احتياجات الطلبة ذوي الإعاقة، ضمن بيئة تعليمية تعزز التفاعل والمشاركة، ويتم تفعيل هذه المرافق بشكلٍ مناسب بما يضمن استفادة معظم الطلبة ذوي الإعاقة منها ودعم تعلمهم.', NULL, ARRAY[199]),
  ('5.2.8', 1, 2, 'تتوفر مرافق تخصصية مجهزة بموارد ووسائل تتناسب مع احتياجات الطلبة ذوي الإعاقة، إلا أن تفعيلها يتم بشكلٍ محدود، بما يضمن استفادة بعض الطلبة ذوي الإعاقة منها.
أو
تتوفر مرافق تخصصية للطلبة ذوي الإعاقة، إلا أنها مجهزة بموارد ووسائل محدودة، مما يؤثر على مدى استفادة الطلبة ذوي الإعاقة منها، ويقلل من فعاليتها في دعم تعلمهم وتلبية احتياجاتهم.', NULL, ARRAY[199]),
  ('5.2.8', 1, 1, 'تتوفر مرافق تخصصية مجهزة بموارد ووسائل تتناسب مع احتياجات الطلبة ذوي الإعاقة، إلا أن تفعيلها يتم بشكلٍ محدود جداً، مما يؤدي إلى استفادة قلة من الطلبة ذوي الإعاقة منها.
أو
لا توفر المدرسة مرافق تخصصية تلبي احتياجات الطلبة ذوي الإعاقة.', NULL, ARRAY[199]),
  ('5.3.1', 1, 5, 'إعداد وتنفيذ سياسة وإجراءات واضحة للأمن والسلامة وخطة لإدارة الأزمات والطوارئ تشمل جميع جوانب الحياة المدرسية، وتدريب الموظفين على الاستجابة الفعالة في حالات الأزمات، مما يسهم بشكلٍ فعال جداً في توفير بيئة آمنة للطلبة والموظفين.', NULL, ARRAY[200]),
  ('5.3.1', 1, 4, 'إعداد وتنفيذ سياسة وإجراءات واضحة للأمن والسلامة تشمل الغالبية العظمى من جوانب الحياة المدرسية، وتنفيذ خطة لإدارة الأزمات والطوارئ وتدريب الموظفين على الاستجابة في حالات الأزمات، مما يسهم بشكلٍ فعال في توفير بيئة آمنة للطلبة والموظفين.', NULL, ARRAY[200]),
  ('5.3.1', 1, 3, 'إعداد وتنفيذ سياسة وإجراءات للأمن والسلامة تشمل معظم جوانب الحياة المدرسية، وتنفيذ خطة لإدارة الأزمات والطوارئ وتدريب الموظفين على الاستجابة في حالات الأزمات، مما يسهم بشكلٍ مناسب في توفير بيئة آمنة للطلبة والموظفين.', NULL, ARRAY[200]),
  ('5.3.1', 1, 2, 'يتم تنفيذ خطة لإدارة الأزمات والطوارئ، لكن يتم إعداد وتنفيذ سياسة للأمن والسلامة تشمل بعض جوانب الحياة المدرسية، مما أدى إلى توفير بيئة آمنة للطلبة والموظفين بشكلٍ محدود.
أو
يتم إعداد وتنفيذ سياسة وخطة للأمن والسلامة تشمل جوانب الحياة المدرسية، إلا أن سياسة وخطة إدارة الأزمات والطوارئ تفتقر للجودة، مما أثر على توفير بيئة آمنة للطلبة والموظفين.', NULL, ARRAY[200]),
  ('5.3.1', 1, 1, 'يتم إعداد وتنفيذ سياسة للأمن والسلامة تشمل قلة من جوانب الحياة المدرسية، أدى إلى توفير بيئة آمنة للطلبة والموظفين بشكلٍ محدود جداً.
أو
لا يتم إعداد أو تنفيذ سياسة وإجراءات للأمن والسلامة.
أو
لا يتم إعداد خطة لإدارة الأزمات والطوارئ.', NULL, ARRAY[200]),
  ('5.3.1', 2, 5, 'يتم توفير أنظمة الإنذار المبكر، وتوزيع طفايات الحريق في مرافق المدرسة وصيانتها بشكلٍ دوري للتحقق من سلامتها وجاهزيتها، ويتم تدريب جميع الموظفين بانتظام على كيفية استخدامها، مما يضمن الاستجابة بشكلٍ فعال جداً في حالات الطوارئ وتوفير بيئة آمنة للطلبة والموظفين.', NULL, ARRAY[200,201]),
  ('5.3.1', 2, 4, 'يتم توفير أنظمة الإنذار المبكر، وتوزيع طفايات الحريق في مرافق المدرسة وصيانتها بشكلٍ دوري للتحقق من سلامتها وجاهزيتها، ويتم تدريب الغالبية العظمى من الموظفين بانتظام على كيفية استخدامها، مما يضمن الاستجابة بشكلٍ فعال في حالات الطوارئ وتوفير بيئة آمنة للطلبة والموظفين.', NULL, ARRAY[200,201]),
  ('5.3.1', 2, 3, 'يتم توفير أنظمة الإنذار المبكر، وتوزيع طفايات الحريق في مرافق المدرسة وصيانتها بشكلٍ دوري للتحقق من سلامتها وجاهزيتها، ويتم تدريب معظم الموظفين على كيفية استخدامها، مما يضمن الاستجابة بشكلٍ مناسب في حالات الطوارئ وتوفير بيئة آمنة للطلبة والموظفين.', NULL, ARRAY[200,201]),
  ('5.3.1', 2, 2, 'يتم توفير أنظمة الإنذار المبكر، وتوزيع طفايات الحريق في مرافق المدرسة، إلا أنه يتم تدريب بعض الموظفين على كيفية استخدامها، مما يؤثر على توفير بيئة مدرسية آمنة.
أو
يتم توفير أنظمة الإنذار المبكر، وتوزيع طفايات الحريق في مرافق المدرسة، إلا أنه لا تتم صيانتها بشكلٍ منتظم، مما يؤثر على توفير بيئة مدرسية آمنة.', NULL, ARRAY[200,201]),
  ('5.3.1', 2, 1, 'يتم توفير أنظمة الإنذار المبكر، وتوزيع طفايات الحريق في مرافق المدرسة، إلا أنه يتم تدريب قلة من الموظفين على كيفية استخدامها، مما يؤثر سلباً على توفير بيئة مدرسية آمنة.
أو
لا يتم توفير أنظمة الإنذار المبكر و / أو توزيع طفايات الحريق في مرافق المدرسة.
أو
لا يتم إجراء صيانة لطفايات الحريق للتحقق من سلامتها وجاهزيتها.', NULL, ARRAY[200,201]),
  ('5.3.1', 3, 5, 'يتم نشر مخططات إخلاء واضحة في جميع مرافق المدرسة تتضمن إرشادات دقيقة حول طرق الإخلاء الآمن، كما يتم تحديد مخارج طوارئ ونقاط تجمع آمنة وواضحة، يسهل الوصول إليها، وتتناسب مساحتها مع أعداد الطلبة والموظفين.', NULL, ARRAY[201]),
  ('5.3.1', 3, 4, 'يتم نشر مخططات إخلاء واضحة في الغالبية العظمى من مرافق المدرسة تتضمن إرشادات حول طرق الإخلاء الآمن، كما يتم تحديد مخارج طوارئ ونقاط تجمع آمنة وواضحة يسهل الوصول إليها، وتتناسب مساحتها مع أعداد الطلبة والموظفين.', NULL, ARRAY[201]),
  ('5.3.1', 3, 3, 'يتم نشر مخططات إخلاء واضحة في معظم مرافق المدرسة، كما يتم تحديد مخارج طوارئ ونقاط تجمع آمنة وواضحة تتناسب مساحتها مع أعداد الطلبة والموظفين.', NULL, ARRAY[201]),
  ('5.3.1', 3, 2, 'يتم تحديد مخارج طوارئ ونقاط تجمع يسهل الوصول إليها، وتتناسب مساحتها مع أعداد الطلبة والموظفين، إلا أنه يتم نشر مخططات إخلاء واضحة في بعض مرافق المدرسة.', NULL, ARRAY[201]),
  ('5.3.1', 3, 1, 'يتم نشر مخططات إخلاء غير واضحة تتضمن إرشادات غير دقيقة في مرافق المدرسة.
أو
لا يتم نشر مخططات إخلاء في مرافق المدرسة.
أو
لا يتم تحديد مخارج طوارئ و/أو نقاط تجمع آمنة.
أو
لا يسهل الوصول إلى نقاط التجمع.', NULL, ARRAY[201]),
  ('5.3.1', 4, 5, 'يتم تنظيم تدريبات دورية على الإخلاء الوهمي للطلبة والموظفين بشكلٍ منتظم في جميع الصفوف/المراحل التعليمية، ويتم توفير إرشادات واضحة وشاملة حول طرق الإخلاء الآمن، ويتم تقييم أداء التدريب لضمان الجاهزية، مما يضمن تنظيماً آمناً وفعالاً جداً في حالات الإخلاء للطوارئ.', NULL, ARRAY[201,202]),
  ('5.3.1', 4, 4, 'يتم تنظيم تدريبات دورية على الإخلاء الوهمي للطلبة والموظفين بشكلٍ منتظم في الغالبية العظمى من الصفوف/المراحل التعليمية، ويتم توفير إرشادات واضحة حول طرق الإخلاء الآمن، مما يضمن تنظيماً آمناً وفعالاً في حالات الإخلاء للطوارئ.', NULL, ARRAY[201,202]),
  ('5.3.1', 4, 3, 'يتم تنظيم تدريبات دورية على الإخلاء الوهمي للطلبة والموظفين بشكلٍ منتظم في معظم الصفوف/المراحل التعليمية، ويتم توفير إرشادات واضحة حول طرق الإخلاء الآمن، مما يضمن تنظيماً آمناً ومناسباً في حالات الإخلاء للطوارئ.', NULL, ARRAY[201,202]),
  ('5.3.1', 4, 2, 'يتم تنظيم تدريبات على الإخلاء الوهمي للطلبة والموظفين في بعض الصفوف/المراحل التعليمية.
أو
يتم تنظيم تدريبات على الإخلاء الوهمي بشكلٍ غير منتظم، مما يؤثر على توفير تنظيماً آمناً في حالات الإخلاء للطوارئ.
أو
يتم تنظيم تدريبات على الإخلاء الوهمي، إلا أن الإرشادات غير واضحة حول طرق الإخلاء الآمن.', NULL, ARRAY[201,202]),
  ('5.3.1', 4, 1, 'يتم تنظيم تدريبات على الإخلاء الوهمي للطلبة والموظفين في قلة من الصفوف/المراحل التعليمية.
أو
لا يتم تنظيم تدريبات على الإخلاء الوهمي.', NULL, ARRAY[201,202]),
  ('5.3.1', 5, 5, 'يتم الإشراف على الطلبة بشكلٍ منتظم في جميع المرافق والصفوف الدراسية طوال اليوم الدراسي، كما يتم تطبيق إجراءات فعالة جداً لتنظيم دخول وخروج الطلبة والموظفين والزوار بشكلٍ آمن، مع وجود مراقبة دقيقة لضمان تطبيق هذه الإجراءات بانتظام.', NULL, ARRAY[202]),
  ('5.3.1', 5, 4, 'يتم الإشراف على الطلبة بشكلٍ منتظم في الغالبية العظمى من المرافق والصفوف الدراسية طوال اليوم الدراسي، كما يتم تطبيق إجراءات فعالة لتنظيم دخول وخروج الطلبة والموظفين والزوار بشكلٍ آمن.', NULL, ARRAY[202]),
  ('5.3.1', 5, 3, 'يتم الإشراف على الطلبة في معظم المرافق والصفوف الدراسية، كما يتم تطبيق إجراءات مناسبة لتنظيم دخول وخروج الطلبة والموظفين والزوار بشكلٍ آمن.', NULL, ARRAY[202]),
  ('5.3.1', 5, 2, 'يتم تطبيق إجراءات لتنظيم دخول وخروج الطلبة والموظفين والزوار، إلا أنه يتم الإشراف على الطلبة بشكلٍ محدود وذلك في بعض المرافق المدرسية، مما أثر على توفير بيئة مدرسية آمنة.
أو
يتم تطبيق إجراءات محدودة لتنظيم دخول وخروج الطلبة والموظفين والزوار بشكلٍ آمن.', NULL, ARRAY[202]),
  ('5.3.1', 5, 1, 'يتم الإشراف على الطلبة في قلة من المرافق المدرسية مما أثر سلباً على توفير بيئة مدرسية آمنة.
أو
لا يتم تطبيق إجراءات لتنظيم دخول وخروج الطلبة والموظفين والزوار بشكلٍ آمن.', NULL, ARRAY[202]),
  ('5.3.1', 6, 5, 'يتم تنفيذ إجراءات واضحة وشاملة بشكلٍ فعال جداً ومنتظم لضمان سلامة الطلبة أثناء استخدام الحافلات، ويتم توفير مشرفين مدربين في كافة الحافلات، مما يسهم في توفير بيئة آمنة لجميع الطلبة أثناء استخدام الحافلات المدرسية. (إن وجدت)', NULL, ARRAY[202,203]),
  ('5.3.1', 6, 4, 'يتم تنفيذ إجراءات واضحة بشكلٍ فعال لضمان سلامة الطلبة أثناء استخدام الحافلات، ويتم توفير مشرفين في كافة الحافلات، مما يسهم في توفير بيئة آمنة للغالبية العظمى من الطلبة أثناء استخدام الحافلات المدرسية. (إن وجدت)', NULL, ARRAY[202,203]),
  ('5.3.1', 6, 3, 'يتم تنفيذ إجراءات مناسبة لضمان سلامة الطلبة أثناء استخدام الحافلات، ويتم توفير مشرفين في كافة الحافلات، مما يسهم في توفير بيئة آمنة لمعظم الطلبة أثناء استخدام الحافلات المدرسية. (إن وجدت)', NULL, ARRAY[202,203]),
  ('5.3.1', 6, 2, 'يتم تنفيذ إجراءات محدودة لضمان سلامة الطلبة أثناء استخدام الحافلات، مما يسهم في توفير بيئة آمنة لبعض الطلبة أثناء استخدام الحافلات المدرسية. (إن وجدت)', NULL, ARRAY[202,203]),
  ('5.3.1', 6, 1, 'لا يتم تنفيذ إجراءات لضمان سلامة الطلبة أثناء استخدام الحافلات المدرسية.
أو
لا يتم توفير مشرفين مدربين في كافة الحافلات المدرسية. (إن وجدت)', NULL, ARRAY[202,203]),
  ('5.3.2', 1, 5, 'يتم إعداد وتنفيذ سياسة وإجراءات واضحة وشاملة وفعالة جداً للأمن الرقمي وحماية بيانات الطلبة والموظفين، مع تفعيل إجراءات الإبلاغ عن الحوادث الرقمية والاستجابة السريعة لها ومعالجتها، وتتم مراجعة هذه الإجراءات وتحديثها بصورة دورية وشاملة، بما يضمن توفير بيئة رقمية آمنة في جميع مرافق المدرسة وأنشطتها التعليمية والإدارية، ويعزز جاهزيتها لمواجهة المخاطر الرقمية.', NULL, ARRAY[203]),
  ('5.3.2', 1, 4, 'يتم إعداد وتنفيذ سياسة وإجراءات واضحة وفعالة للأمن الرقمي وحماية بيانات الطلبة والموظفين، مع تفعيل إجراءات الإبلاغ عن الحوادث الرقمية والاستجابة لها ومعالجتها، وتتم مراجعة هذه الإجراءات وتحديثها، بما يضمن توفير بيئة رقمية آمنة في الغالبية العظمى من مرافق المدرسة وأنشطتها التعليمية والإدارية، ويعزز جاهزيتها لمواجهة المخاطر الرقمية.', NULL, ARRAY[203]),
  ('5.3.2', 1, 3, 'يتم إعداد وتنفيذ سياسة وإجراءات مناسبة للأمن الرقمي وحماية بيانات الطلبة والموظفين، وتتم مراجعة هذه الإجراءات وتحديثها، بما يضمن توفير بيئة رقمية آمنة في معظم مرافق المدرسة وأنشطتها التعليمية والإدارية.', NULL, ARRAY[203]),
  ('5.3.2', 1, 2, 'يتم إعداد وتنفيذ سياسة وإجراءات محدودة للأمن الرقمي وحماية بيانات الطلبة والموظفين، مما يؤدي إلى توفير بيئة رقمية آمنة في بعض مرافق المدرسة وأنشطتها التعليمية والإدارية.
أو
يتم إعداد وتنفيذ سياسة وإجراءات ذات جودة محدودة للأمن الرقمي وحماية البيانات، مما يحد من فاعليتها في ضمان توفير بيئة رقمية آمنة في مرافق المدرسة وأنشطتها التعليمية والإدارية.', NULL, ARRAY[203]),
  ('5.3.2', 1, 1, 'يتم إعداد وتنفيذ سياسة وإجراءات محدودة جداً للأمن الرقمي وحماية بيانات الطلبة والموظفين، وتطبيق أنظمة الحماية التقنية، مما يؤدي إلى توفير بيئة رقمية آمنة في قلة من مرافق المدرسة وأنشطتها التعليمية والإدارية.
أو
لا يتم إعداد / تنفيذ سياسة وإجراءات للأمن الرقمي وحماية بيانات الطلبة والموظفين.', NULL, ARRAY[203]),
  ('5.3.2', 2, 5, 'تُنفذ المدرسة برامج توعية وتدريب منتظمة ومتنوعة لجميع الطلبة والموظفين حول السلامة الرقمية والاستخدام المسؤول للتقنيات الرقمية، مما يسهم بشكلٍ فعال جداً في ترسيخ الممارسات والسلوكيات الرقمية الآمنة.', NULL, ARRAY[203,204]),
  ('5.3.2', 2, 4, 'تُنفذ المدرسة برامج توعية وتدريب منتظمة ومتنوعة للغالبية العظمى من الطلبة والموظفين حول السلامة الرقمية والاستخدام المسؤول للتقنيات الرقمية، مما يسهم بشكلٍ فعال في ترسيخ الممارسات والسلوكيات الرقمية الآمنة.', NULL, ARRAY[203,204]),
  ('5.3.2', 2, 3, 'تُنفذ المدرسة برامج توعية وتدريب منتظمة ومتنوعة لمعظم الطلبة والموظفين حول السلامة الرقمية والاستخدام المسؤول للتقنيات الرقمية، مما يسهم بشكلٍ مناسب في ترسيخ الممارسات والسلوكيات الرقمية الآمنة.', NULL, ARRAY[203,204]),
  ('5.3.2', 2, 2, 'تُنفذ المدارس برامج توعية وتدريب لبعض الطلبة والموظفين حول السلامة الرقمية والاستخدام المسؤول للتقنيات الرقمية، مما يسهم بشكلٍ محدود في ترسيخ الممارسات والسلوكيات الرقمية الآمنة.', NULL, ARRAY[203,204]),
  ('5.3.2', 2, 1, 'تُنفذ المدرسة برامج توعية وتدريب لقلة من الطلبة والموظفين حول السلامة الرقمية والاستخدام المسؤول للتقنيات الرقمية، مما يسهم بشكلٍ محدود جداً في ترسيخ الممارسات والسلوكيات الرقمية الآمنة.', NULL, ARRAY[203,204]),
  ('5.3.3', 1, 5, 'وحدة العناية الصحية مرخصة من الجهات ذات العلاقة في الدولة، ومجهزة بالمستلزمات والأدوات الطبية اللازمة لتقديم خدمات الرعاية الصحية للطلبة، ويتم تخزين الأدوية والأدوات الطبية وفقاً للمعايير الطبية المعتمدة، ويتناسب حجم وحدة العناية الصحية وتنظيمها مع احتياجات جميع الطلبة، بما يشمل أعدادهم واختلاف جنسهم ومختلف فئاتهم العمرية، مما يضمن توفير رعاية صحية فعالة جداً وعالية الجودة.', NULL, ARRAY[204,205]),
  ('5.3.3', 1, 4, 'وحدة العناية الصحية مرخصة من الجهات ذات العلاقة في الدولة، ومجهزة بالمستلزمات والأدوات الطبية اللازمة، ويتم تخزين الأدوية والأدوات الطبية وفقاً للمعايير الطبية المعتمدة، ويتناسب حجم وحدة العناية الصحية وتنظيمها مع احتياجات الغالبية العظمى من الطلبة، مما يضمن توفير رعاية صحية فعالة وذات جودة.', NULL, ARRAY[204,205]),
  ('5.3.3', 1, 3, 'وحدة العناية الصحية مرخصة من الجهات ذات العلاقة في الدولة، ومجهزة بالمستلزمات والأدوات الطبية اللازمة، ويتم تخزين الأدوية والأدوات الطبية وفقاً للمعايير الطبية المعتمدة، ويتناسب حجم وحدة العناية الصحية وتنظيمها مع احتياجات معظم الطلبة، مما يضمن توفير رعاية صحية مناسبة.', NULL, ARRAY[204,205]),
  ('5.3.3', 1, 2, 'وحدة العناية الصحية مرخصة من الجهات ذات العلاقة في الدولة، ومجهزة بالمستلزمات والأدوات الطبية اللازمة، إلا أن حجم وحدة العناية الصحية وتنظيمها يتناسب مع احتياجات بعض الطلبة، مما أثر على توفير خدمات رعاية صحية ذات جودة.
أو
وحدة العناية الصحية مجهزة بالمستلزمات والأدوات الطبية اللازمة، ويتناسب حجم وحدة العناية الصحية وتنظيمها مع احتياجات الطلبة، إلا أن الترخيص قيد الإجراء، ويتم متابعة الإجراءات اللازمة للحصول على الترخيص.', NULL, ARRAY[204,205]),
  ('5.3.3', 1, 1, 'وحدة العناية الصحية مرخصة من الجهات ذات العلاقة في الدولة، ومجهزة بالمستلزمات والأدوات الطبية اللازمة، إلا أن حجمها وتنظيمها يتناسب مع أعداد واحتياجات قلة من الطلبة فقط، مما أثر سلباً على توفير خدمات رعاية صحية ذات جودة.
أو
وحدة العناية الصحية غير مرخصة من الجهات ذات العلاقة في الدولة، ولا يتم متابعة الإجراءات اللازمة للحصول على الترخيص.', NULL, ARRAY[204,205]),
  ('5.3.3', 2, 5, 'يتم تقديم خدمات الرعاية الصحية لجميع الطلبة وفقاً لإرشادات وتعليمات وزارة الصحة والجهات المعنية في الدولة، من خلال ممرض مؤهل ومرخص، كما يتم تحديد الحالات المرضية الخاصة للطلبة وإبلاغ المعنيين بها ومتابعتها بانتظام، واتخاذ الإجراءات الوقائية اللازمة، وتُفعّل آليات منتظمة للتواصل مع أولياء الأمور بشأن الخدمات الصحية المقدمة للطلبة، مما يسهم في تقديم الرعاية الصحية بشكلٍ فعال جداً ومستمر.', NULL, ARRAY[205,206]),
  ('5.3.3', 2, 4, 'يتم تقديم خدمات الرعاية الصحية للغالبية العظمى من الطلبة وفقاً لإرشادات وتعليمات وزارة الصحة والجهات المعنية في الدولة، من خلال ممرض ومؤهل ومرخص، كما يتم تحديد الحالات المرضية الخاصة للطلبة وإبلاغ المعنيين بها ومتابعتها بانتظام، ويتم التواصل مع أولياء الأمور بشأن الخدمات الصحية المقدمة للطلبة، مما يسهم في تقديم الرعاية الصحية بشكلٍ فعال.', NULL, ARRAY[205,206]),
  ('5.3.3', 2, 3, 'يتم تقديم خدمات الرعاية الصحية لمعظم الطلبة، من خلال ممرض مؤهل ومرخص، كما يتم تحديد الحالات المرضية الخاصة للطلبة ومتابعتها، والتواصل مع أولياء الأمور بشأن الخدمات الصحية المقدمة للطلبة، مما يسهم في تقديم الرعاية الصحية بشكلٍ مناسب.', NULL, ARRAY[205,206]),
  ('5.3.3', 2, 2, 'يتم تقديم خدمات الرعاية الصحية بشكلٍ محدود لبعض الطلبة من خلال ممرض مؤهل ومرخص، كما يتم تحديد الحالات المرضية الخاصة للطلبة ومتابعتها.
أو
يتم تقديم خدمات الرعاية الصحية للطلبة من خلال ممرض مؤهل ومرخص، إلا أنه لا يتم تحديد الحالات المرضية الخاصة للطلبة.
أو
يتم تقديم خدمات الرعاية الصحية للطلبة من خلال ممرض مؤهل ومرخص، ويتم تحديد الحالات المرضية الخاصة للطلبة، إلا أنه تتم متابعتها بشكلٍ محدود، مما أثر على تقديم الرعاية الصحية المناسبة لهم.
أو
يتم تقديم الرعاية الصحية للطلبة من خلال ممرض مؤهل، ويتم تحديد الحالات المرضية الخاصة وإبلاغ المعنيين بها ومتابعتها، إلا أن ترخيص الممرض لا يزال قيد الإجراء، ويتم متابعة الإجراءات اللازمة للحصول على الترخيص.', NULL, ARRAY[205,206]),
  ('5.3.3', 2, 1, 'يتم تقديم خدمات الرعاية الصحية بشكل محدود جداً لقلة من الطلبة من خلال ممرض مؤهل ومرخص، كما يتم تحديد الحالات المرضية الخاصة للطلبة ومتابعتها.
أو
يتم تقديم خدمات الرعاية الصحية للطلبة من خلال ممرض غير مؤهل / أو غير مرخص، ولا يتم متابعة الإجراءات اللازمة للحصول على الترخيص.', NULL, ARRAY[205,206]),
  ('5.3.3', 3, 5, 'يتم تدريب جميع الموظفين على إجراءات الإسعافات الأولية والتعامل مع الحالات الطارئة، مما يضمن جاهزيتهم العالية وقدرتهم على التصرف السريع والملائم في مختلف الحالات الطارئة.', NULL, ARRAY[206]),
  ('5.3.3', 3, 4, 'يتم تدريب الغالبية العظمى من الموظفين على إجراءات الإسعافات الأولية، والتعامل مع الحالات الطارئة، مما يضمن جاهزيتهم وقدرتهم على التصرف السريع والملائم في الحالات الطارئة.', NULL, ARRAY[206]),
  ('5.3.3', 3, 3, 'يتم تدريب معظم الموظفين على إجراءات الإسعافات الأولية، والتعامل مع الحالات الطارئة، مما يضمن قدرتهم على التصرف السريع والملائم في الحالات الطارئة.', NULL, ARRAY[206]),
  ('5.3.3', 3, 2, 'يتم تدريب بعض الموظفين على إجراءات الإسعافات الأولية، والتعامل مع الحالات الطارئة، مما يؤثر على جاهزية موظفي المدرسة وقدرتهم على التصرف السريع والملائم في هذه الحالات.', NULL, ARRAY[206]),
  ('5.3.3', 3, 1, 'يتم تدريب قلة من الموظفين على إجراءات الإسعافات الأولية، والتعامل مع الحالات الطارئة، مما يؤثر سلباً على جاهزية موظفي المدرسة وقدرتهم على التصرف السريع والملائم في هذه الحالات.
أو
لا يتم تدريب الموظفين على إجراءات الإسعافات الأولية والتعامل مع الحالات الطارئة.', NULL, ARRAY[206]),
  ('5.3.3', 4, 5, 'يتم تنظيم برامج توعوية وتثقيفية صحية شاملة ومستمرة ومتنوعة للطلبة في جميع الصفوف / المراحل الدراسية لضمان جاهزيتهم، مما يسهم بشكلٍ فعال جداً في تعزيز السلوكيات الصحية الإيجابية ورفع مستوى الوعي الصحي.', NULL, ARRAY[206,207]),
  ('5.3.3', 4, 4, 'يتم تنظيم برامج توعوية وتثقيفية صحية مستمرة للطلبة في الغالبية العظمى من الصفوف / المراحل الدراسية، مما يسهم بشكلٍ فعال في رفع مستوى الوعي الصحي لديهم.', NULL, ARRAY[206,207]),
  ('5.3.3', 4, 3, 'يتم تنظيم برامج توعوية وتثقيفية صحية للطلبة في معظم الصفوف/ المراحل الدراسية، مما يسهم بشكلٍ مناسب في رفع مستوى الوعي الصحي بشكلٍ مناسب لديهم.', NULL, ARRAY[206,207]),
  ('5.3.3', 4, 2, 'يتم تنظيم برامج توعوية وتثقيفية صحية للطلبة بشكلٍ محدود في بعض الصفوف / المراحل الدراسية، مما يؤثر على رفع مستوى الوعي الصحي لديهم.
أو
يتم تنظيم برامج توعوية صحية للطلبة في الصفوف / المراحل الدراسية، إلا أن هذه البرامج محدودة وغير متنوعة و/أو تُقدم بشكلٍ غير مستمر، مما أثر على رفع مستوى الوعي الصحي لدى الطلبة.', NULL, ARRAY[206,207]),
  ('5.3.3', 4, 1, 'يتم تنظيم برامج توعوية وتثقيفية صحية للطلبة بشكلٍ محدود جداً في قلة من الصفوف / المراحل الدراسية، مما يؤثر سلباً على رفع مستوى الوعي الصحي لديهم.
أو
لا يتم تنظيم برامج توعوية وتثقيفية صحية للطلبة.', NULL, ARRAY[206,207]),
  ('5.3.4', 1, 5, 'يتم تنفيذ إجراءات الصيانة لجميع المباني والمرافق المدرسية والمعدات والأثاث بشكلٍ دوري منتظم وفعال جداً، وذلك من خلال التنسيق المستمر مع شركات صيانة متخصصة، كما تُطبق إجراءات الصيانة الوقائية بانتظام لضمان استدامة أداء المرافق وسلامة البيئة التعليمية.', NULL, ARRAY[207]),
  ('5.3.4', 1, 4, 'يتم تنفيذ إجراءات الصيانة للغالبية العظمى من المباني والمرافق المدرسية والمعدات والأثاث بشكلٍ دوري وفعال، وذلك من خلال التنسيق مع شركات صيانة متخصصة، لضمان سلامة البيئة التعليمية.', NULL, ARRAY[207]),
  ('5.3.4', 1, 3, 'يتم تنفيذ إجراءات الصيانة لمعظم المباني والمرافق المدرسية والمعدات والأثاث بشكلٍ مناسب، وذلك من خلال التنسيق مع شركات صيانة متخصصة، لضمان سلامة البيئة التعليمية.', NULL, ARRAY[207]),
  ('5.3.4', 1, 2, 'يتم تنفيذ إجراءات الصيانة لبعض المباني والمرافق المدرسية والمعدات والأثاث، مما يؤثر على سلامة البيئة التعليمية.
أو
يتم تنفيذ إجراءات صيانة محدودة للمباني، والمرافق المدرسية والمعدات والأثاث، مما يؤثر على سلامة البيئة التعليمية.', NULL, ARRAY[207]),
  ('5.3.4', 1, 1, 'لا يتم تنفيذ إجراءات صيانة للمباني والمرافق المدرسية والمعدات والأثاث، مما يؤثر سلباً على سلامة البيئة التعليمية.', NULL, ARRAY[207]),
  ('5.3.5', 1, 5, 'يتم توفير خدمات التنظيف بانتظام وبشكلٍ فعال جداً في جميع المباني والمرافق المدرسية، ويتم التخلص من النفايات بالتنسيق مع الجهات المختصة، مع متابعة دورية لنظافة المرافق والأثاث، وتنفيذ إجراءات وقائية لضمان بيئة مدرسية خالية من الحشرات والقوارض، مما يسهم في توفير بيئة صحية للطلبة والموظفين.', NULL, ARRAY[207,208]),
  ('5.3.5', 1, 4, 'يتم توفير خدمات التنظيف بانتظام وبشكلٍ فعال في الغالبية العظمى من المباني والمرافق المدرسية، ويتم التخلص من النفايات بالتنسيق مع الجهات المختصة، مع متابعة دورية لنظافة المرافق والأثاث، وتنفيذ إجراءات لضمان بيئة مدرسية خالية من الحشرات والقوارض، مما يسهم في توفير بيئة صحية للطلبة والموظفين.', NULL, ARRAY[207,208]),
  ('5.3.5', 1, 3, 'يتم توفير خدمات التنظيف بانتظام وبشكلٍ مناسب في معظم المباني والمرافق المدرسية، ويتم التخلص من النفايات بالتنسيق مع الجهات المختصة، وتنفذ المدرسة إجراءات وقائية لضمان بيئة مدرسية خالية من الحشرات والقوارض.', NULL, ARRAY[207,208]),
  ('5.3.5', 1, 2, 'يتم توفير خدمات التنظيف في بعض المباني والمرافق المدرسية، مما أثر على توفير بيئة صحية للطلبة والموظفين، كما يتم / لا يتم تنفيذ إجراءات الوقاية من الحشرات والقوارض.
أو
يتم توفير خدمات تنظيف محدودة في المباني والمرافق المدرسية، مما أثر على توفير بيئة صحية للطلبة والموظفين، كما يتم / لا يتم تنفيذ إجراءات الوقاية من الحشرات والقوارض.
أو
يتم توفير خدمات التنظيف في المباني والمرافق المدرسية، ويتم التخلص السليم من النفايات المدرسية، إلا أنه لا يتم تنفيذ إجراءات وقائية لضمان بيئة مدرسية خالية من الحشرات والقوارض.', NULL, ARRAY[207,208]),
  ('5.3.5', 1, 1, 'يتم توفير خدمات التنظيف في قلة من المباني والمرافق المدرسية، مما أثر سلباً على توفير بيئة صحية للطلبة والموظفين، كما يتم / لا يتم تنفيذ إجراءات الوقاية من الحشرات والقوارض.
أو
لا يتم توفير خدمات تنظيف في المباني والمرافق المدرسية، مما أثر سلباً على توفير بيئة صحية للطلبة والموظفين، كما يتم / لا يتم تنفيذ إجراءات الوقاية من الحشرات والقوارض.', NULL, ARRAY[207,208]);

DO $rub$
DECLARE fw uuid; n int; orphan int;
BEGIN
  SELECT id INTO fw FROM frameworks WHERE code = 'QNSA' AND version = 'official-2026';
  IF fw IS NULL THEN RAISE EXCEPTION 'الإصدار official-2026 غير موجود — شغّل 070 أولاً'; END IF;

  SELECT count(DISTINCT r.sub) INTO orphan FROM _q26_rubric r
   WHERE NOT EXISTS (SELECT 1 FROM framework_nodes fn
                      WHERE fn.framework_id = fw AND fn.level = 3 AND fn.code = r.sub);
  IF orphan > 0 THEN RAISE EXCEPTION 'أوصاف بلا معيار فرعي مقابل: %', orphan; END IF;

  INSERT INTO framework_rubric (framework_node_id, row_index, level, descriptor_ar, group_ar, source_pages)
  SELECT fn.id, r.row_index, r.level, r.descriptor, r.group_ar, r.pages
  FROM _q26_rubric r
  JOIN framework_nodes fn ON fn.framework_id = fw AND fn.level = 3 AND fn.code = r.sub
  ON CONFLICT (framework_node_id, row_index, level) DO UPDATE
  SET descriptor_ar = EXCLUDED.descriptor_ar, group_ar = EXCLUDED.group_ar,
      source_pages = EXCLUDED.source_pages;

  GET DIAGNOSTICS n = ROW_COUNT;
  RAISE NOTICE 'أوصاف السلم: % عبارة', n;
END $rub$;

-- ── (2) تحقّق ───────────────────────────────────────────────────
SELECT 'عبارات السلم' AS البند, count(*)::text AS العدد,
       CASE WHEN count(*) = 840 THEN 'مطابق' ELSE 'مختلف — المتوقّع 840' END AS الحالة
FROM framework_rubric r
JOIN framework_nodes fn ON fn.id = r.framework_node_id
JOIN frameworks f ON f.id = fn.framework_id
WHERE f.code = 'QNSA' AND f.version = 'official-2026'
UNION ALL
SELECT 'أوصاف (صفوف)', count(*)::text,
       CASE WHEN count(*) = 168 THEN 'مطابق' ELSE 'مختلف — المتوقّع 168' END
FROM (SELECT DISTINCT r.framework_node_id, r.row_index
      FROM framework_rubric r
      JOIN framework_nodes fn ON fn.id = r.framework_node_id
      JOIN frameworks f ON f.id = fn.framework_id
      WHERE f.code = 'QNSA' AND f.version = 'official-2026') x
UNION ALL
SELECT 'أوصاف ناقصة المستويات', count(*)::text,
       CASE WHEN count(*) = 0 THEN 'مطابق' ELSE 'خلل' END
FROM (SELECT r.framework_node_id, r.row_index
      FROM framework_rubric r
      JOIN framework_nodes fn ON fn.id = r.framework_node_id
      JOIN frameworks f ON f.id = fn.framework_id
      WHERE f.code = 'QNSA' AND f.version = 'official-2026'
      GROUP BY r.framework_node_id, r.row_index HAVING count(*) <> 5) y;
-- المتوقّع: 840 · 168 · 0 — كلّها «مطابق»
